(function(){var records={"509":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：石英（α-石英）</td>\n                        <td>英文名：Quartz</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：SiO<sub>2</sub></td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=636\" target=\"_blank\" rel=\"noopener noreferrer\">一轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=642\" target=\"_blank\" rel=\"noopener noreferrer\">石英类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>石英：一轴晶石英类矿物</p>\n<p>【颜色】无色透明，有时因微细包裹体而显得浑浊</p>\n<p>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正低突起</p>\n<p>【干涉色】最高干涉色为一级淡黄，一般为一级灰</p>\n<p>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】平行消光，受应力影响，呈波状消光。</p>\n<p>【延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)】正延性</p>\n<p>【双晶】双晶少见，但在变质岩中的石英则可有狭小的应变双晶片。</p>\n<p>光性异常：因应力作用有时成为二轴晶。2V=0-20°</p>\n<p>1. 紫石英：由于Fe3+高度分散而带紫色，常为二轴晶，2V大致为35°。</p>\n<p>2. 烟石英：由于Si带离子状态而致烟色，也是二轴晶，2V=8-0°，为有多色性，淡褐-淡绿</p>\n<p>【鉴定特征】主要为无色，洁净，不规则的粒状，无解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)，一轴晶，正光性。</p>\n<p>与相似矿物的区别</p>\n<p>（1） 与钠长石的区别在于钠长石为二轴晶，负低突起，有解理</p>\n<p>（2） 与菫青石的区别在于菫青石为二轴晶，常具有三连晶或则六连晶</p>\n<p>（3） 与绿柱石的区别在于绿柱石为负延性，负光性。</p>\n<p>（4） 与玉髓的区别在于玉髓为负突起，呈纤维状放射状或纤维隐晶质细粒集合体</p>\n<p>石英单偏光镜下照片：</p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1490887727.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/509_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n<p>石英镜下特殊现象照片：</p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497061680.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/509_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497061682.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/509_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497061684.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/509_3.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n\n        ","sourceFullDescriptionText":"描述\n            \n石英：一轴晶石英类矿物\n【颜色】无色透明，有时因微细包裹体而显得浑浊\n【突起 (查看突起测定方法)】正低突起\n【干涉色】最高干涉色为一级淡黄，一般为一级灰\n【消光 (查看消光测定方法)】平行消光，受应力影响，呈波状消光。\n【延性 (查看延性测定方法)】正延性\n【双晶】双晶少见，但在变质岩中的石英则可有狭小的应变双晶片。\n光性异常：因应力作用有时成为二轴晶。2V=0-20°\n1. 紫石英：由于Fe3+高度分散而带紫色，常为二轴晶，2V大致为35°。\n2. 烟石英：由于Si带离子状态而致烟色，也是二轴晶，2V=8-0°，为有多色性，淡褐-淡绿\n【鉴定特征】主要为无色，洁净，不规则的粒状，无解理 (查看解理测定方法)，一轴晶，正光性。\n与相似矿物的区别\n（1） 与钠长石的区别在于钠长石为二轴晶，负低突起，有解理\n（2） 与菫青石的区别在于菫青石为二轴晶，常具有三连晶或则六连晶\n（3） 与绿柱石的区别在于绿柱石为负延性，负光性。\n（4） 与玉髓的区别在于玉髓为负突起，呈纤维状放射状或纤维隐晶质细粒集合体\n石英单偏光镜下照片：\n\n\n\n石英镜下特殊现象照片：","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"665":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：方解石</td>\n                        <td>英文名：Calcite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：CaCO<sub>3</sub></td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=636\" target=\"_blank\" rel=\"noopener noreferrer\">一轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=644\" target=\"_blank\" rel=\"noopener noreferrer\">碳酸盐类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p><span>方解石：一轴晶矿物</span></p>\n<p><span>【颜色】纯的方解石在薄片中应该为无色，往往由于有着粘土与氧化铁的混合物而呈现灰色或褐色</span></p>\n<p><span>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】具有明显的闪突起</span></p>\n<p><span>【解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)】</span><span>{10<span>1</span>1}</span><span>极完全，切面垂直解理面时，两解理夹角为</span><span>75</span><span>°；有时有</span><span>{01<span>1</span>2}</span><span>双晶滑动裂开面</span></p>\n<p><span>【干涉色】具有高级白干涉色</span></p>\n<p><span>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】沿解理方向对称消光</span></p>\n<p><span>【延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)】负延性</span></p>\n<p><span>【双晶】</span><span>{01<span>1</span>2}</span><span>切片中聚片双晶常见，双晶纹多半平行菱形解理的长对角线</span></p>\n<p><span>【光性异常】产在变质岩和其他变形岩石中的方解石，由于受力的作用的结果，常显二轴晶负光性，</span><span>2V=4-14</span><span>°</span></p>\n<p><span>【鉴定特征】无色、菱面体解理、明显的闪突起、聚片双晶、高级白干涉色及一轴晶负光性</span></p>\n<p><span>【次生变化】方解石能慢慢溶解于地下水</span></p>\n\n        ","sourceFullDescriptionText":"描述\n            \n方解石：一轴晶矿物\n【颜色】纯的方解石在薄片中应该为无色，往往由于有着粘土与氧化铁的混合物而呈现灰色或褐色\n【突起 (查看突起测定方法)】具有明显的闪突起\n【解理 (查看解理测定方法)】{1011}极完全，切面垂直解理面时，两解理夹角为75°；有时有{0112}双晶滑动裂开面\n【干涉色】具有高级白干涉色\n【消光 (查看消光测定方法)】沿解理方向对称消光\n【延性 (查看延性测定方法)】负延性\n【双晶】{0112}切片中聚片双晶常见，双晶纹多半平行菱形解理的长对角线\n【光性异常】产在变质岩和其他变形岩石中的方解石，由于受力的作用的结果，常显二轴晶负光性，2V=4-14°\n【鉴定特征】无色、菱面体解理、明显的闪突起、聚片双晶、高级白干涉色及一轴晶负光性\n【次生变化】方解石能慢慢溶解于地下水","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"670":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：重晶石</td>\n                        <td>英文名：Barite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式： Ba[SO<sub>4</sub>]</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=652\" target=\"_blank\" rel=\"noopener noreferrer\">角闪石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>重晶石：属于二轴晶角闪石类矿物</p>\n<p>【颜色】薄片中无色透明</p>\n<p>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正中突起</p>\n<p>【解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)】薄片中常见两组直交的解理</p>\n<p>【干涉色】最高达一级黄、橙。干涉色常呈斑点状</p>\n<p>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】平行消光</p>\n<p>【延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)】正延性</p>\n<p>【双晶】有以{110}为双晶面的聚片双晶</p>\n<p>【次生变化】可蚀变毒晶石</p>\n<p>【鉴定特征】比重大，常出现两组解理，较低的干涉色，中等大小的光轴角是重晶石的主要鉴定特征。</p>\n<p>【产状】常见于矿脉中，呈脉状矿物与石英、方解石共生，也可成单独的重晶石脉。有时见于流纹岩和玄武岩的气孔中。也可成为砂岩的胶结物或产于灰岩中</p>\n<p>重晶石讲解视频：</p>\n<p></p><p></p>\n\n        ","sourceFullDescriptionText":"描述\n            \n重晶石：属于二轴晶角闪石类矿物\n【颜色】薄片中无色透明\n【突起 (查看突起测定方法)】正中突起\n【解理 (查看解理测定方法)】薄片中常见两组直交的解理\n【干涉色】最高达一级黄、橙。干涉色常呈斑点状\n【消光 (查看消光测定方法)】平行消光\n【延性 (查看延性测定方法)】正延性\n【双晶】有以{110}为双晶面的聚片双晶\n【次生变化】可蚀变毒晶石\n【鉴定特征】比重大，常出现两组解理，较低的干涉色，中等大小的光轴角是重晶石的主要鉴定特征。\n【产状】常见于矿脉中，呈脉状矿物与石英、方解石共生，也可成单独的重晶石脉。有时见于流纹岩和玄武岩的气孔中。也可成为砂岩的胶结物或产于灰岩中\n重晶石讲解视频：","sourceVideos":[{"title":"重晶石讲解视频：","localPath":"video/670_0.mp4","posterLocalPath":"video/670_0.jpg","url":"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/videos/v_1497093093.mp4","sha256":"11185ecc4b2f4bb3cda47881a3395b05a94f60a4addf3afd3160c5920a1d1109"}],"sourceVideoStatus":"published"},"701":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：普通辉石</td>\n                        <td>英文名：Kugite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：(Ca,Mg,Fe,Al)<sub>2</sub>[(Si,Al)<sub>2</sub>O<sub>6</sub>]</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=654\" target=\"_blank\" rel=\"noopener noreferrer\">辉石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>普通辉石：普通辉石属二轴晶辉石类单斜辉石亚类</p>\n<p>【颜色】薄片中矿物为淡黄-淡褐色</p>\n<p>【形态】纵切面为短柱状，横切面为四边形或八边形</p>\n<p>【解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)】辉石式完全解理，解理夹角90°。纵切面具一组完全解理</p>\n<p>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正高突起 </p>\n<p>【干涉色】干涉色为一级顶部，</p>\n<p>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】横切面对称消光。纵切面斜消光</p>\n<p>【延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)】延性可正可负</p>\n<p>【双晶】{100}简单双晶或聚片双晶。{001}聚片双晶普遍</p>\n<p>【鉴定特征】与角闪石的区别是后者折射率较低、解理夹角为6°、124°，具明显多色性，消光角小，负光性。与橄榄石区别是橄榄石的解理不发育，干涉色高、光轴角大</p>\n<p>【次生变化】常变为绿泥石、假象纤闪石、黑云母，有时变为蛇纹石、绿帘石、方解石、绿脱石</p>\n<p>【产状】常见于基性、超基性岩浆岩中</p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497061321.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/701_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497061323.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/701_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n<p> 普通辉石纵切面初步讲解：</p>\n<p></p><p></p>\n<p> </p>\n\n        ","sourceFullDescriptionText":"描述\n            \n普通辉石：普通辉石属二轴晶辉石类单斜辉石亚类\n【颜色】薄片中矿物为淡黄-淡褐色\n【形态】纵切面为短柱状，横切面为四边形或八边形\n【解理 (查看解理测定方法)】辉石式完全解理，解理夹角90°。纵切面具一组完全解理\n【突起 (查看突起测定方法)】正高突起 \n【干涉色】干涉色为一级顶部，\n【消光 (查看消光测定方法)】横切面对称消光。纵切面斜消光\n【延性 (查看延性测定方法)】延性可正可负\n【双晶】{100}简单双晶或聚片双晶。{001}聚片双晶普遍\n【鉴定特征】与角闪石的区别是后者折射率较低、解理夹角为6°、124°，具明显多色性，消光角小，负光性。与橄榄石区别是橄榄石的解理不发育，干涉色高、光轴角大\n【次生变化】常变为绿泥石、假象纤闪石、黑云母，有时变为蛇纹石、绿帘石、方解石、绿脱石\n【产状】常见于基性、超基性岩浆岩中\n\n\n\n\n 普通辉石纵切面初步讲解：","sourceVideos":[{"title":"普通辉石纵切面初步讲解：","localPath":"video/701_0.mp4","posterLocalPath":"video/701_0.jpg","url":"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/videos/v_1489894269.mp4","sha256":"26ac213fba48c54592e8794fe471fcca8abcc54569239292c42391ee312fbb6e"}],"sourceVideoStatus":"published"},"713":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：蓝闪石</td>\n                        <td>英文名：Glaucophane</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：Na<sub>2</sub>Mg<sub>3</sub>Al<sub>2</sub>[Si<sub>4</sub>O<sub>11</sub>]<sub>2</sub>(OH)<sub>2</sub></td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=652\" target=\"_blank\" rel=\"noopener noreferrer\">角闪石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>蓝闪石：蓝闪石属二轴晶角闪石类单斜角闪石亚类矿物。</p>\n<p>【颜色】蓝色到紫色，具明显多色性，转动物台一周见蓝色-浅蓝色-无色，</p>\n<p>【解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)】闪石式完全解理，</p>\n<p>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正中突起，</p>\n<p>【干涉色】最高干涉色为一级顶部，</p>\n<p>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】纵切面近于平行消光，正延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)。</p>\n<p>蓝闪石是高压低温的产物，常见于片岩、片麻岩、榴辉岩中。</p>\n<p>【鉴定特征】近于平行消光、正吸收、正延性为蓝闪石与其他碱性角闪石的区别</p>\n<p>蓝闪石镜下特殊现象照片：</p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497060946.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/713_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div>\n<br><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497060947.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/713_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a>\n</div>\n</div>\n<p>蓝闪石镜下初步讲解视频</p>\n<p></p><p></p>\n\n        ","sourceFullDescriptionText":"描述\n            \n蓝闪石：蓝闪石属二轴晶角闪石类单斜角闪石亚类矿物。\n【颜色】蓝色到紫色，具明显多色性，转动物台一周见蓝色-浅蓝色-无色，\n【解理 (查看解理测定方法)】闪石式完全解理，\n【突起 (查看突起测定方法)】正中突起，\n【干涉色】最高干涉色为一级顶部，\n【消光 (查看消光测定方法)】纵切面近于平行消光，正延性 (查看延性测定方法)。\n蓝闪石是高压低温的产物，常见于片岩、片麻岩、榴辉岩中。\n【鉴定特征】近于平行消光、正吸收、正延性为蓝闪石与其他碱性角闪石的区别\n蓝闪石镜下特殊现象照片：\n\n\n\n\n\n\n蓝闪石镜下初步讲解视频","sourceVideos":[{"title":"蓝闪石镜下初步讲解视频","localPath":"video/713_0.mp4","posterLocalPath":"video/713_0.jpg","url":"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/videos/v_1490408565.mp4","sha256":"207ca63b57146e82d52d3d7c3b81aaaaeb514fd46b48ab8778c2f711b858ac50"}],"sourceVideoStatus":"published"},"715":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：普通角闪石</td>\n                        <td>英文名：Common hornblende</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：A<sub>0-1</sub>B<sub>2</sub>C<sub>5</sub>[Si<sub>4</sub>O<sub>11</sub>]<sub>2</sub>(OH)<sub>2</sub></td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=652\" target=\"_blank\" rel=\"noopener noreferrer\">角闪石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>普通角闪石：二轴晶角闪石类单斜角闪石亚类矿物</p>\n<p>【颜色】 按颜色可以分为绿色（含Fe2+高）和棕色（含Fe3+高）两种。多色性均很明显</p>\n<p>（1） 绿色普通角闪石：深绿—黄绿—淡黄或无色</p>\n<p>（2） 棕色普通角闪石：深棕—棕色—淡棕</p>\n<p>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正中—正高突起；折射率随含铁量增多而升高</p>\n<p> 【干涉色】横切面干涉色较低，干涉色最高达二级黄绿，但干涉色常受矿物自身颜色所影响而不易分辨</p>\n<p>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】横切面对称消光，垂直（010）纵切面为平行消光，其余纵切面为斜消光</p>\n<p>【延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)】正延性</p>\n<p>【次生变化】常蚀变为黑云母、绿泥石、绿帘石和碳酸盐矿物以及纤维状阳起石、绢云母、石英、磁铁矿。某些低Al的普通角闪石还可变为蛇纹石。棕色普通角闪石变为绿色种属时，可产生次生榍石。火山岩中的角闪石，常具有磁铁矿、黑云母等构成的暗化边。</p>\n<p>【鉴定特征】长柱状，强多色性，角闪石式解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)，斜消光（消光角一般小于25°）正延性，负光性等为普通角闪石的重要特征。</p>\n<p>（1） 与普通辉石区别—主要是具角闪石解理，多色性强，消光角小，负光性。</p>\n<p>（2） 与阳起石区别—阳起石色浅，不呈褐色，弱多色性，产状也不同</p>\n<p>（3） 棕色普通角闪石与黑云母的区别—在于黑云母是具有一组极完全解理，进平行消光，干涉色可达三级，光轴角小，2V=0-25°，常呈现类似一轴晶负光性的干涉图。</p>\n<p>（4） 棕色普通角闪石与棕闪石的区别在于——棕闪石消光角小，Ng^c=11-20°，2V小，2V=40-50°，产于碱性岩中。</p>\n<p>（5） 棕色普通角闪石与玄武闪石的区别——玄武闪石消光角小，Ng^c=0-12°，高级干涉色，多产于喷出岩中，常有暗化边。</p>\n<p>（6） 纤维状棕色普通角闪石和纤维状电气石的区别——角闪石吸收性最强的方向近于∥c轴，而电气石⊥c轴。</p>\n<p>普通角闪石镜下特殊现象照片：</p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497060291.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/715_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497060293.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/715_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497060296.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/715_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n<p> </p>\n<p> </p>\n<p><br><br></p>\n\n        ","sourceFullDescriptionText":"描述\n            \n普通角闪石：二轴晶角闪石类单斜角闪石亚类矿物\n【颜色】 按颜色可以分为绿色（含Fe2+高）和棕色（含Fe3+高）两种。多色性均很明显\n（1） 绿色普通角闪石：深绿—黄绿—淡黄或无色\n（2） 棕色普通角闪石：深棕—棕色—淡棕\n【突起 (查看突起测定方法)】正中—正高突起；折射率随含铁量增多而升高\n 【干涉色】横切面干涉色较低，干涉色最高达二级黄绿，但干涉色常受矿物自身颜色所影响而不易分辨\n【消光 (查看消光测定方法)】横切面对称消光，垂直（010）纵切面为平行消光，其余纵切面为斜消光\n【延性 (查看延性测定方法)】正延性\n【次生变化】常蚀变为黑云母、绿泥石、绿帘石和碳酸盐矿物以及纤维状阳起石、绢云母、石英、磁铁矿。某些低Al的普通角闪石还可变为蛇纹石。棕色普通角闪石变为绿色种属时，可产生次生榍石。火山岩中的角闪石，常具有磁铁矿、黑云母等构成的暗化边。\n【鉴定特征】长柱状，强多色性，角闪石式解理 (查看解理测定方法)，斜消光（消光角一般小于25°）正延性，负光性等为普通角闪石的重要特征。\n（1） 与普通辉石区别—主要是具角闪石解理，多色性强，消光角小，负光性。\n（2） 与阳起石区别—阳起石色浅，不呈褐色，弱多色性，产状也不同\n（3） 棕色普通角闪石与黑云母的区别—在于黑云母是具有一组极完全解理，进平行消光，干涉色可达三级，光轴角小，2V=0-25°，常呈现类似一轴晶负光性的干涉图。\n（4） 棕色普通角闪石与棕闪石的区别在于——棕闪石消光角小，Ng^c=11-20°，2V小，2V=40-50°，产于碱性岩中。\n（5） 棕色普通角闪石与玄武闪石的区别——玄武闪石消光角小，Ng^c=0-12°，高级干涉色，多产于喷出岩中，常有暗化边。\n（6） 纤维状棕色普通角闪石和纤维状电气石的区别——角闪石吸收性最强的方向近于∥c轴，而电气石⊥c轴。\n普通角闪石镜下特殊现象照片：","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"730":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：石榴子石</td>\n                        <td>英文名：Garnet</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：A<sub>3</sub>B<sub>2</sub>[SiO<sub>4</sub>]<sub>3</sub></td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=6\" target=\"_blank\" rel=\"noopener noreferrer\">均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=570\" target=\"_blank\" rel=\"noopener noreferrer\">方钠石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p> </p>\n<p> 石榴子石：均质矿物</p>\n<p>【颜色】颜色多种，与内部元素有关。主要有深红、褐色、黄、绿、玫瑰色及黑色。</p>\n<p>【形态】多呈六边形或八边形，也呈等轴粒状。</p>\n<p>【解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)】无解理，裂纹发育。</p>\n<p>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正高——正极高突起，糙面明显</p>\n<p>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】均质体，绝大数为全消光。钙质石榴子石具有弱的非均质性，呈一级灰干涉色。</p>\n<p>【鉴定特征】晶形，正高至正极高突起，全消光，常有光性异常和环带构造。根据颜色、折射率、比重、产状等特征区分本类各种石榴子石种属，精确测定需要配合化学分析及电子探针等方法。</p>\n<p>与尖晶石的区别在于尖晶石颜色较深，常具有八面体晶形和{111}解理。而石榴子石多呈菱形十二面体或四角八面体，无解理</p>\n<p>【次生变化】石榴子石可被绿泥石、绿帘石、黑云母及钠长石等矿物交代。</p>\n<p>【变种】水榴石，即谁绿榴石，是含水的钙铝榴石。无色、白色、灰色或粉色。产于接触变质岩，与硅灰石、黄长石等共生。</p>\n<p>石榴子石镜下特殊现象：</p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497061427.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/730_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497061429.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/730_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497061431.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/730_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n\n        ","sourceFullDescriptionText":"描述\n            \n \n 石榴子石：均质矿物\n【颜色】颜色多种，与内部元素有关。主要有深红、褐色、黄、绿、玫瑰色及黑色。\n【形态】多呈六边形或八边形，也呈等轴粒状。\n【解理 (查看解理测定方法)】无解理，裂纹发育。\n【突起 (查看突起测定方法)】正高——正极高突起，糙面明显\n【消光 (查看消光测定方法)】均质体，绝大数为全消光。钙质石榴子石具有弱的非均质性，呈一级灰干涉色。\n【鉴定特征】晶形，正高至正极高突起，全消光，常有光性异常和环带构造。根据颜色、折射率、比重、产状等特征区分本类各种石榴子石种属，精确测定需要配合化学分析及电子探针等方法。\n与尖晶石的区别在于尖晶石颜色较深，常具有八面体晶形和{111}解理。而石榴子石多呈菱形十二面体或四角八面体，无解理\n【次生变化】石榴子石可被绿泥石、绿帘石、黑云母及钠长石等矿物交代。\n【变种】水榴石，即谁绿榴石，是含水的钙铝榴石。无色、白色、灰色或粉色。产于接触变质岩，与硅灰石、黄长石等共生。\n石榴子石镜下特殊现象：","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"736":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：红柱石</td>\n                        <td>英文名：Andalusite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：Al<sub>2</sub>[SiO<sub>4</sub>]O</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=652\" target=\"_blank\" rel=\"noopener noreferrer\">角闪石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>红柱石：红柱石属二轴晶角闪石类单斜角闪石亚类矿物。</p>\n<p>【颜色】薄片中矿物无色（或带浅玫瑰色），具弱多色性，含Fe多时呈淡黄色</p>\n<p>【解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)】纵切面为柱状，见一组完全解理</p>\n<p>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正中突起，折射率随Fe2+的增加而增大</p>\n<p>【干涉色】最高干涉色为以及灰白至一级黄，但一般为一级黄。</p>\n<p>【延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)】负延性。</p>\n<p>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】横切面成方形，见作十字形排列的碳质包裹体，对称消光；纵切面为柱状，平行消光。</p>\n<p>【双晶】有时有以{100}为双晶面的聚片双晶</p>\n<p>【次生变化】硅灰石可以被针钠钙石和方解石脉所交代</p>\n<p>【鉴定特征】主要在于解理夹角、较高的折射率与较低的干涉色，且能溶于HCl.易于透闪石及绿帘石混淆，其区别在于</p>\n<p>（1） 透闪石具有{110}解理，夹角为56°，有较大的双折射率（0.022-0.032）正延性，2V很大</p>\n<p>（2） 绿帘石的折射率、双折射率均高，并且常有明显的多色性及异常干涉色。</p>\n<p>【产状】主要分布于接触变质的大理岩及某些片麻岩中，常与透辉石、钙铝石榴石、方解石、绿帘石、透闪石、符山石和基性斜长石共生</p>\n<p>红柱石镜下特殊现象照片：</p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497059940.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/736_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497059941.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/736_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n<p> </p>\n<p><span>红柱石横切面初步讲解视频</span></p>\n<p><span></span></p>\n<br><br>     <p></p>\n<p><span>红柱石纵切面初步讲解视频</span></p>\n<p></p><p></p>\n\n        ","sourceFullDescriptionText":"描述\n            \n红柱石：红柱石属二轴晶角闪石类单斜角闪石亚类矿物。\n【颜色】薄片中矿物无色（或带浅玫瑰色），具弱多色性，含Fe多时呈淡黄色\n【解理 (查看解理测定方法)】纵切面为柱状，见一组完全解理\n【突起 (查看突起测定方法)】正中突起，折射率随Fe2+的增加而增大\n【干涉色】最高干涉色为以及灰白至一级黄，但一般为一级黄。\n【延性 (查看延性测定方法)】负延性。\n【消光 (查看消光测定方法)】横切面成方形，见作十字形排列的碳质包裹体，对称消光；纵切面为柱状，平行消光。\n【双晶】有时有以{100}为双晶面的聚片双晶\n【次生变化】硅灰石可以被针钠钙石和方解石脉所交代\n【鉴定特征】主要在于解理夹角、较高的折射率与较低的干涉色，且能溶于HCl.易于透闪石及绿帘石混淆，其区别在于\n（1） 透闪石具有{110}解理，夹角为56°，有较大的双折射率（0.022-0.032）正延性，2V很大\n（2） 绿帘石的折射率、双折射率均高，并且常有明显的多色性及异常干涉色。\n【产状】主要分布于接触变质的大理岩及某些片麻岩中，常与透辉石、钙铝石榴石、方解石、绿帘石、透闪石、符山石和基性斜长石共生\n红柱石镜下特殊现象照片：\n\n\n\n\n \n红柱石横切面初步讲解视频\n\n     \n红柱石纵切面初步讲解视频","sourceVideos":[{"title":"红柱石横切面初步讲解视频","localPath":"video/736_0.mp4","posterLocalPath":"video/736_0.jpg","url":"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/videos/v_1492437489.mp4","sha256":"3183d9e93f751adfc6cede9a75ba60b1c494cb02bae099baf21459e84df54f90"},{"title":"红柱石纵切面初步讲解视频","localPath":"video/736_1.mp4","posterLocalPath":"video/736_1.jpg","url":"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/videos/v_1490088731.mp4","sha256":"f1cb0c42f9f7e21c8f96aa6c60ab4fd51ac8e2f84d4eaf2c3aebf8cac6130e7f"}],"sourceVideoStatus":"published"},"740":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：榍石</td>\n                        <td>英文名：Sphene/Titanite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：CaTi[SiO<sub>4</sub>]O</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=656\" target=\"_blank\" rel=\"noopener noreferrer\">绿帘石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>榍石：二轴晶绿帘石类矿物</p>\n<p>【颜色】薄片无色、褐色、棕色、黄色或绿色。碎屑为黄褐色。有色者具有多色性。</p>\n<p>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正极高突起</p>\n<p>【干涉色】高级白干涉色</p>\n<p>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】横切面为对称消光，以{110}解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)为准，则为斜消光</p>\n<p>【双晶】有时可见（100）简单双晶，偶尔见（221）聚片双晶。</p>\n<p>【次生变化】可变为土状白钛矿，但任保持其外形。在水热作用下课分解为方解石、金红石、钛铁矿。次生的榍石是在黑云母变成绿泥石或钛铁矿，普通辉石变为普通角闪石的过程中产生的。</p>\n<p>【鉴定特征】尖菱形状或信封状晶形，正极高突起，高级白干涉色，色散强。</p>\n<p>（1） 与方解石的区别：方解石有闪突起、菱形解理、色浅、聚片双晶常见，一轴晶负光性。</p>\n<p>（2） 与磷钇矿的区别：磷钇矿多为不规则粒状。且突起较低，一轴晶正光性。</p>\n<p>（3） 与独居石的区别：独居石突起和干涉色均较低。</p>\n<p>【产状】在岩浆岩（正长岩、似长似正长岩、二长岩、花岗闪长岩、花岗伟晶岩）中呈副矿物出现；在结晶片岩、片麻岩、沉积岩及接触变质岩中也有产出；为稳定的重矿物，可堆积成砂矿。</p>\n<p>榍石镜下特殊现象照片：</p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497062025.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/740_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497062027.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/740_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497062030.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/740_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n<p> </p>\n\n        ","sourceFullDescriptionText":"描述\n            \n榍石：二轴晶绿帘石类矿物\n【颜色】薄片无色、褐色、棕色、黄色或绿色。碎屑为黄褐色。有色者具有多色性。\n【突起 (查看突起测定方法)】正极高突起\n【干涉色】高级白干涉色\n【消光 (查看消光测定方法)】横切面为对称消光，以{110}解理 (查看解理测定方法)为准，则为斜消光\n【双晶】有时可见（100）简单双晶，偶尔见（221）聚片双晶。\n【次生变化】可变为土状白钛矿，但任保持其外形。在水热作用下课分解为方解石、金红石、钛铁矿。次生的榍石是在黑云母变成绿泥石或钛铁矿，普通辉石变为普通角闪石的过程中产生的。\n【鉴定特征】尖菱形状或信封状晶形，正极高突起，高级白干涉色，色散强。\n（1） 与方解石的区别：方解石有闪突起、菱形解理、色浅、聚片双晶常见，一轴晶负光性。\n（2） 与磷钇矿的区别：磷钇矿多为不规则粒状。且突起较低，一轴晶正光性。\n（3） 与独居石的区别：独居石突起和干涉色均较低。\n【产状】在岩浆岩（正长岩、似长似正长岩、二长岩、花岗闪长岩、花岗伟晶岩）中呈副矿物出现；在结晶片岩、片麻岩、沉积岩及接触变质岩中也有产出；为稳定的重矿物，可堆积成砂矿。\n榍石镜下特殊现象照片：","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"757":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：橄榄石</td>\n                        <td>英文名：Olivine</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：(Mg,Fe)<sub>2</sub>[SiO<sub>4</sub>]</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=655\" target=\"_blank\" rel=\"noopener noreferrer\">橄榄石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>橄榄石：二轴晶橄榄石类矿物</p>\n<p>【颜色】无色透明</p>\n<p>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正高突起，糙面明显</p>\n<p>【干涉色】二级顶干涉色</p>\n<p>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】平行消光，</p>\n<p>【延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)】延性可正可负</p>\n<p>【双晶】双晶少见</p>\n<p>【次生变化】橄榄石极不稳定，常蚀变为蛇纹石，并伴随磁铁矿的析出。蚀变沿边缘及裂隙开始，继而发展为整个颗粒为蛇纹石代替，而呈现橄榄石假象，喷出岩和某些浅层岩中，橄榄石常蚀变为伊丁石、蒙脱石-绿泥石集合体或绿鳞石。此外，橄榄石也可变化为透闪石、滑石、黑云母和菱镁矿等矿物。</p>\n<p>鉴定特征：无色、正高突起、多裂纹、常蚀变成蛇纹石，无解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)</p>\n<p>橄榄石单偏光镜下照片</p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1490689816.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/757_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p> </p>\n<p>橄榄石镜下特殊现象照片：</p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497059884.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/757_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497059886.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/757_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497059888.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/757_3.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497059890.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/757_4.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497059893.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/757_5.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n\n        ","sourceFullDescriptionText":"描述\n            \n橄榄石：二轴晶橄榄石类矿物\n【颜色】无色透明\n【突起 (查看突起测定方法)】正高突起，糙面明显\n【干涉色】二级顶干涉色\n【消光 (查看消光测定方法)】平行消光，\n【延性 (查看延性测定方法)】延性可正可负\n【双晶】双晶少见\n【次生变化】橄榄石极不稳定，常蚀变为蛇纹石，并伴随磁铁矿的析出。蚀变沿边缘及裂隙开始，继而发展为整个颗粒为蛇纹石代替，而呈现橄榄石假象，喷出岩和某些浅层岩中，橄榄石常蚀变为伊丁石、蒙脱石-绿泥石集合体或绿鳞石。此外，橄榄石也可变化为透闪石、滑石、黑云母和菱镁矿等矿物。\n鉴定特征：无色、正高突起、多裂纹、常蚀变成蛇纹石，无解理 (查看解理测定方法)\n橄榄石单偏光镜下照片\n\n \n橄榄石镜下特殊现象照片：","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"765":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：黑云母</td>\n                        <td>英文名：Biotite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式： K(Mg,Fe<sub><sup>2+</sup></sub>)<sub>3</sub>[（Al,Fe）Si<sub>3</sub>O<sub>10</sub>](OH,F)<sub>2</sub></td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=648\" target=\"_blank\" rel=\"noopener noreferrer\">云母类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p><span><br>黑云母：二轴晶云母类矿物。</span></p>\n<p><span>【颜色】薄片中矿物为棕黄、棕红、浅褐色，具明显多色性。转动物台一周，可见薄片颜色变化为由黑褐色-褐色-浅褐色，</span></p>\n<p><span>【解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)】发育一组极完全解理，</span></p>\n<p><span>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】具正中突起，折射率随着Fe<sup>2+</sup>的增加而升高，尤其随Fe<sup>3+</sup>和Ti的增加而升高更快</span></p>\n<p><span>【干涉色】含铁低的类型，最高干涉色为二级橙，含铁高的可达四级。但往往被自身颜色所掩盖</span></p>\n<p><span>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】平行消光，但产于碱性岩和煌斑岩中的黑云母消光角可达8°。往往由于受力的作用可见波状消光。</span></p>\n<p><span>【延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)】正延性。</span></p>\n<p><span>【双晶】以（001）为结合面的云母律双晶，不甚明显</span></p>\n<p><span>【次生变化】黑云母易受蚀变而褪色、并常转为绿泥石，薄片中经常见到绿泥石依黑云母形成的假象、同时析出钛生成针状金红石、细粒钛铁矿、磁铁矿及榍石。黑云母也可变为白云母、矽线石和角闪石。黑云母水化后可形成蛭石。</span></p>\n<p><span>【鉴定特征】薄片下呈各种色调：褐色、红褐色、橙色、绿色；强吸收性，片状，一组极完全解理，突起及干涉色中等，平行消光，在H<sub>2</sub>SO<sub>4</sub>中和褪色。</span></p>\n<p><span>黑云母可能与金云母、绿泥石、棕色普通角闪石、褐帘石、电气石相混。</span></p>\n<p><span>（1） 与金云母的区别在于黑云母颜色深，吸收性强，折射率高，2V大</span></p>\n<p><span>（2） 与棕色普通角闪石的区别在于黑云母为轴面解理，对解理是平行消光，而棕色普通角闪石是柱面解理，对解理是斜消光或则对称消光，其次是黑云母多色性显著，折射率较小，干涉色较高</span></p>\n<p><span>（3） 与电气石的区别是电气石不像黑云母那样是深褐色，与黑云母相反，当电气石柱面延长方向垂直下偏光镜振动方向时，吸收性最强。</span></p>\n<p><span>（4） 与褐帘石的区别是褐帘石的折射率高，双折射率较低</span></p>\n<p><span>（5） 与褐色绿帘石的区别是褐色绿帘石的多色性较弱，干涉色低一级具异常干涉色。</span></p>\n<p><span>【产状】黑云母广泛存在三大岩中，尤其是中酸性岩浆岩、云母煌斑岩、云母片岩、片麻岩等的重要矿物。</span></p>\n<p><span>黑云母相关的镜下照片：</span></p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1493442426.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/765_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1493442427.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/765_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1493442428.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/765_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1493442431.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/765_3.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1493442434.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/765_4.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n<p><span>黑云母纵切面初步讲解：</span></p>\n<p> </p><p></p>\n\n        ","sourceFullDescriptionText":"描述\n            \n黑云母：二轴晶云母类矿物。\n【颜色】薄片中矿物为棕黄、棕红、浅褐色，具明显多色性。转动物台一周，可见薄片颜色变化为由黑褐色-褐色-浅褐色，\n【解理 (查看解理测定方法)】发育一组极完全解理，\n【突起 (查看突起测定方法)】具正中突起，折射率随着Fe2+的增加而升高，尤其随Fe3+和Ti的增加而升高更快\n【干涉色】含铁低的类型，最高干涉色为二级橙，含铁高的可达四级。但往往被自身颜色所掩盖\n【消光 (查看消光测定方法)】平行消光，但产于碱性岩和煌斑岩中的黑云母消光角可达8°。往往由于受力的作用可见波状消光。\n【延性 (查看延性测定方法)】正延性。\n【双晶】以（001）为结合面的云母律双晶，不甚明显\n【次生变化】黑云母易受蚀变而褪色、并常转为绿泥石，薄片中经常见到绿泥石依黑云母形成的假象、同时析出钛生成针状金红石、细粒钛铁矿、磁铁矿及榍石。黑云母也可变为白云母、矽线石和角闪石。黑云母水化后可形成蛭石。\n【鉴定特征】薄片下呈各种色调：褐色、红褐色、橙色、绿色；强吸收性，片状，一组极完全解理，突起及干涉色中等，平行消光，在H2SO4中和褪色。\n黑云母可能与金云母、绿泥石、棕色普通角闪石、褐帘石、电气石相混。\n（1） 与金云母的区别在于黑云母颜色深，吸收性强，折射率高，2V大\n（2） 与棕色普通角闪石的区别在于黑云母为轴面解理，对解理是平行消光，而棕色普通角闪石是柱面解理，对解理是斜消光或则对称消光，其次是黑云母多色性显著，折射率较小，干涉色较高\n（3） 与电气石的区别是电气石不像黑云母那样是深褐色，与黑云母相反，当电气石柱面延长方向垂直下偏光镜振动方向时，吸收性最强。\n（4） 与褐帘石的区别是褐帘石的折射率高，双折射率较低\n（5） 与褐色绿帘石的区别是褐色绿帘石的多色性较弱，干涉色低一级具异常干涉色。\n【产状】黑云母广泛存在三大岩中，尤其是中酸性岩浆岩、云母煌斑岩、云母片岩、片麻岩等的重要矿物。\n黑云母相关的镜下照片：\n\n\n\n\n\n\n\n黑云母纵切面初步讲解：","sourceVideos":[{"title":"黑云母纵切面初步讲解：","localPath":"video/765_0.mp4","posterLocalPath":"video/765_0.jpg","url":"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/videos/v_1490085756.mp4","sha256":"8e64ef05ff916a0470a0d332d33cf06f621e622c205fd2d3b74ce181d7c50b9d"}],"sourceVideoStatus":"published"},"855":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：矽线石</td>\n                        <td>英文名：Sillimanite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：Al<sub>2</sub>[SiO<sub>4</sub>]O</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=652\" target=\"_blank\" rel=\"noopener noreferrer\">角闪石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>矽线石：矽线石属二轴晶矿物。</p>\n<p>【颜色】薄片中矿物为无色，</p>\n<p>【形状】呈针状、簇状、放射状。</p>\n<p>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正中-正高突起，</p>\n<p>【干涉色】纵切面最高干涉色为二级蓝，横切面为一级灰干涉色，</p>\n<p>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】纵切面为平行消光，横切面为对称消光</p>\n<p>【延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)】正延性。</p>\n<p>【次生变化】矽线石易变为绢云母和粘土矿物</p>\n<p>【鉴定特征】晶形，横裂纹及较高干涉色</p>\n<p>【产状】矽线石常见于泥质岩石的接触变质岩及区域变质岩中。</p>\n<p>矽线石镜下特殊现象照片：</p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497061889.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/855_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497061891.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/855_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497061892.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/855_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497061893.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/855_3.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n<p> </p>\n\n        ","sourceFullDescriptionText":"描述\n            \n矽线石：矽线石属二轴晶矿物。\n【颜色】薄片中矿物为无色，\n【形状】呈针状、簇状、放射状。\n【突起 (查看突起测定方法)】正中-正高突起，\n【干涉色】纵切面最高干涉色为二级蓝，横切面为一级灰干涉色，\n【消光 (查看消光测定方法)】纵切面为平行消光，横切面为对称消光\n【延性 (查看延性测定方法)】正延性。\n【次生变化】矽线石易变为绢云母和粘土矿物\n【鉴定特征】晶形，横裂纹及较高干涉色\n【产状】矽线石常见于泥质岩石的接触变质岩及区域变质岩中。\n矽线石镜下特殊现象照片：","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"856":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：菫青石</td>\n                        <td>英文名：Cordierite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：Mg<sub>2</sub>Al<sub>3</sub>[Si<sub>5</sub>AlO<sub>18</sub>]</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>菫青石：二轴晶矿物</p>\n<p>【颜色】通常无色，有时呈浅黄色或则浅蓝色，多色性较弱。</p>\n<p>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正低或则负低突起</p>\n<p>【干涉色】最高干涉色为一级稻草黄，与石英类似</p>\n<p>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】柱面为平行消光，若具六连晶，则对顶的单体同时消光</p>\n<p>【形态】常呈三连晶和六连晶有时也有聚片双晶。</p>\n<p>【光性】二轴晶负光性，少数为正光性、同一薄片不同颗粒可能有不同光性，光轴角可能变化。</p>\n<p>易于石英混淆，特征如下：</p>\n<p>         石英                                菫青石</p>\n<p>1. 正低突起                  1. 负低——正低突起</p>\n<p>2. 薄片中不见双晶        2. 三连晶、六连晶或聚片双晶</p>\n<p>3. 新鲜、干净               3. 常含多量矿物包裹体，易发生次生变化</p>\n<p>4. 一轴晶（+）           <span> 4. 二轴晶（+）或（-）</span>    </p>\n<p> 菫青石镜下特殊现在照片：</p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497060656.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/856_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497060659.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/856_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497060661.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/856_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n<p> </p>\n\n        ","sourceFullDescriptionText":"描述\n            \n菫青石：二轴晶矿物\n【颜色】通常无色，有时呈浅黄色或则浅蓝色，多色性较弱。\n【突起 (查看突起测定方法)】正低或则负低突起\n【干涉色】最高干涉色为一级稻草黄，与石英类似\n【消光 (查看消光测定方法)】柱面为平行消光，若具六连晶，则对顶的单体同时消光\n【形态】常呈三连晶和六连晶有时也有聚片双晶。\n【光性】二轴晶负光性，少数为正光性、同一薄片不同颗粒可能有不同光性，光轴角可能变化。\n易于石英混淆，特征如下：\n         石英                                菫青石\n1. 正低突起                  1. 负低——正低突起\n2. 薄片中不见双晶        2. 三连晶、六连晶或聚片双晶\n3. 新鲜、干净               3. 常含多量矿物包裹体，易发生次生变化\n4. 一轴晶（+）            4. 二轴晶（+）或（-）    \n 菫青石镜下特殊现在照片：","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"857":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：紫苏辉石</td>\n                        <td>英文名：Hypersthene</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：(Mg，Fe)<sub>2</sub>[Si<sub>2</sub>O<sub>6</sub>]</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=654\" target=\"_blank\" rel=\"noopener noreferrer\">辉石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>紫苏辉石：二轴晶辉石类矿物</p>\n<p>【颜色】淡红至淡绿，多色性明显</p>\n<p>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正高突起</p>\n<p>【干涉色】一级橙黄至一级红</p>\n<p>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】柱面为平行消光。横切面为对称消光</p>\n<p>【延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)】正延性</p>\n<p>【双晶】延{100}面的简单双晶和聚片双晶。常见紫苏辉石与单斜辉石形成小连晶，薄片中类似聚片双晶。</p>\n<p>紫苏辉石常含定向排列的铁质包裹体，形成“希勒构造”或“闪烁构造”</p>\n<p>【鉴定特征】紫苏辉石具有正高突起，特殊的多色性，较低的干涉色，平行消光，二轴晶负光性等重要鉴定特征，以此区别于其他辉石</p>\n<p>紫苏辉石讲解视频：</p>\n<p></p><p></p>\n\n        ","sourceFullDescriptionText":"描述\n            \n紫苏辉石：二轴晶辉石类矿物\n【颜色】淡红至淡绿，多色性明显\n【突起 (查看突起测定方法)】正高突起\n【干涉色】一级橙黄至一级红\n【消光 (查看消光测定方法)】柱面为平行消光。横切面为对称消光\n【延性 (查看延性测定方法)】正延性\n【双晶】延{100}面的简单双晶和聚片双晶。常见紫苏辉石与单斜辉石形成小连晶，薄片中类似聚片双晶。\n紫苏辉石常含定向排列的铁质包裹体，形成“希勒构造”或“闪烁构造”\n【鉴定特征】紫苏辉石具有正高突起，特殊的多色性，较低的干涉色，平行消光，二轴晶负光性等重要鉴定特征，以此区别于其他辉石\n紫苏辉石讲解视频：","sourceVideos":[{"title":"紫苏辉石讲解视频：","localPath":"video/857_0.mp4","posterLocalPath":"video/857_0.jpg","url":"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/videos/v_1497091868.mp4","sha256":"72ead06b358dda378b4ca60dd80eef34b694fed0812652f9e10cf17400b9be31"}],"sourceVideoStatus":"published"},"858":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：黝帘石</td>\n                        <td>英文名：Zoisite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：Ca<sub>2</sub>AlAl<sub>2</sub>[SiO<sub>4</sub>][Si<sub>2</sub>O<sub>7</sub>]O(OH)</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=656\" target=\"_blank\" rel=\"noopener noreferrer\">绿帘石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>黝帘石：二轴晶绿帘石类矿物</p>\n<p>【颜色】无色，含Mn的锰黝帘石呈浅紫色，并有强的多色性（玫瑰红—浅玫瑰红—淡黄色）</p>\n<p>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正高突起</p>\n<p>【干涉色】正常干涉色为一级灰，含有铁，锰的变种常有深蓝、褐色的异常干涉色。</p>\n<p>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)及延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)】α—黝帘石：平行消光，负延性；β—黝帘石：平行消光，延性不定</p>\n<p>【鉴定特征】无色粒状，突起高，常具有异常干涉色，色散强</p>\n<p>（1）与绿帘石区别：绿帘石常具有多色性，二级以上干涉色</p>\n<p>（2）与斜绿帘石的区别：斜绿帘石具有斜消光，2V大</p>\n<p>（3）无铁黝帘石与黄长石相似，但黄长石是一轴晶（-）光性</p>\n<p>（3）与符山石相似，但符山石是一轴晶，具有{110}解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)</p>\n<p>黝帘石镜下特殊现象：</p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497062216.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/858_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n\n        ","sourceFullDescriptionText":"描述\n            \n黝帘石：二轴晶绿帘石类矿物\n【颜色】无色，含Mn的锰黝帘石呈浅紫色，并有强的多色性（玫瑰红—浅玫瑰红—淡黄色）\n【突起 (查看突起测定方法)】正高突起\n【干涉色】正常干涉色为一级灰，含有铁，锰的变种常有深蓝、褐色的异常干涉色。\n【消光 (查看消光测定方法)及延性 (查看延性测定方法)】α—黝帘石：平行消光，负延性；β—黝帘石：平行消光，延性不定\n【鉴定特征】无色粒状，突起高，常具有异常干涉色，色散强\n（1）与绿帘石区别：绿帘石常具有多色性，二级以上干涉色\n（2）与斜绿帘石的区别：斜绿帘石具有斜消光，2V大\n（3）无铁黝帘石与黄长石相似，但黄长石是一轴晶（-）光性\n（3）与符山石相似，但符山石是一轴晶，具有{110}解理 (查看解理测定方法)\n黝帘石镜下特殊现象：","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"859":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：阳起石</td>\n                        <td>英文名：Actinolite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：Ca<sub>2</sub>(Mg，Fe<sup>2+</sup>)<sub>5</sub>[Si<sub>4</sub>O<sub>11</sub>]<sub>2</sub>(OH，F)<sub>2</sub></td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=652\" target=\"_blank\" rel=\"noopener noreferrer\">角闪石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>阳起石：二轴晶角闪石类矿物</p>\n<p>【颜色】有时无色，有时浅绿色，具有弱多色性</p>\n<p>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正中——正高突起</p>\n<p>【干涉色】最高干涉色为一级末至二级中</p>\n<p>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】横切面为对称消光，垂直（010）纵切面为平行消光，其余为斜消光</p>\n<p>【延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)】正延性</p>\n<p>【双晶】常见{100}简单双晶或聚片双晶</p>\n<p>【鉴定特征】阳起石在薄片中呈淡绿色而不是褐色，以此区别角闪石。但易于绿色普通角闪石混淆，其区别在于阳起石颜色浅、多色性弱，折射率也低于普通角闪石。</p>\n<p>阳起石镜下特殊现象照片：</p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497062163.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/859_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497062164.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/859_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1490888925.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/859_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n\n        ","sourceFullDescriptionText":"描述\n            \n阳起石：二轴晶角闪石类矿物\n【颜色】有时无色，有时浅绿色，具有弱多色性\n【突起 (查看突起测定方法)】正中——正高突起\n【干涉色】最高干涉色为一级末至二级中\n【消光 (查看消光测定方法)】横切面为对称消光，垂直（010）纵切面为平行消光，其余为斜消光\n【延性 (查看延性测定方法)】正延性\n【双晶】常见{100}简单双晶或聚片双晶\n【鉴定特征】阳起石在薄片中呈淡绿色而不是褐色，以此区别角闪石。但易于绿色普通角闪石混淆，其区别在于阳起石颜色浅、多色性弱，折射率也低于普通角闪石。\n阳起石镜下特殊现象照片：","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"860":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：白云母</td>\n                        <td>英文名：Muscovite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：KAl<sub>2</sub>[AlSi<sub>3</sub>O<sub>10</sub>](OH)<sub>2 <sup> </sup></sub></td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=648\" target=\"_blank\" rel=\"noopener noreferrer\">云母类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>白云母：属于二轴晶云母类矿物</p>\n<p>【颜色】薄片中多为无色，有些高铁类型者为淡黄、淡褐色，弱多色性。含铬变种铬云母无色至绿色。含钒变种呈褐绿色</p>\n<p>【形态】晶体呈假六方形或菱形的柱状和板状，在集合体中往往呈薄片状、鳞片状或板状</p>\n<p>【解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)】{001}极完全解理</p>\n<p>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正低至正中突起，具闪突起，转动载物台时突起有变化，当解理平行于下偏光镜振动方向时，突起为中等，垂直下偏光镜振动方向时呈正低突起</p>\n<p>【干涉色】最高干涉色为二级顶部到三级，双折射率随铁含量增大而变化，平行解理的切面中，最高干涉色为一级灰至灰白波状混合起来的干涉色</p>\n<p>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】近于平行消光</p>\n<p>【延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)】正延性（平行解理方向）</p>\n<p>【双晶】常见云母律双晶，有时可见贯穿的三连晶</p>\n<p>【变种】绢云母为细鳞片状的白云母，该矿物在薄片中为密集的鳞片状集合体，常为长石类及副长石类的次生饰变矿物。正交偏光镜下，绢云母由于在集合体中的方位不同，因而呈现五彩缤纷的干涉色交织在一起</p>\n<p>【产状】白云母多产于花岗岩、花岗伟晶岩、云英岩及变质岩中（云母片岩及某些片麻岩）</p>\n<p>白云母镜下照片：</p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497059634.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/860_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497059637.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/860_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497059638.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/860_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497059640.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/860_3.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n<p>白云母初步讲解视频：</p>\n<p></p><p></p>\n\n        ","sourceFullDescriptionText":"描述\n            \n白云母：属于二轴晶云母类矿物\n【颜色】薄片中多为无色，有些高铁类型者为淡黄、淡褐色，弱多色性。含铬变种铬云母无色至绿色。含钒变种呈褐绿色\n【形态】晶体呈假六方形或菱形的柱状和板状，在集合体中往往呈薄片状、鳞片状或板状\n【解理 (查看解理测定方法)】{001}极完全解理\n【突起 (查看突起测定方法)】正低至正中突起，具闪突起，转动载物台时突起有变化，当解理平行于下偏光镜振动方向时，突起为中等，垂直下偏光镜振动方向时呈正低突起\n【干涉色】最高干涉色为二级顶部到三级，双折射率随铁含量增大而变化，平行解理的切面中，最高干涉色为一级灰至灰白波状混合起来的干涉色\n【消光 (查看消光测定方法)】近于平行消光\n【延性 (查看延性测定方法)】正延性（平行解理方向）\n【双晶】常见云母律双晶，有时可见贯穿的三连晶\n【变种】绢云母为细鳞片状的白云母，该矿物在薄片中为密集的鳞片状集合体，常为长石类及副长石类的次生饰变矿物。正交偏光镜下，绢云母由于在集合体中的方位不同，因而呈现五彩缤纷的干涉色交织在一起\n【产状】白云母多产于花岗岩、花岗伟晶岩、云英岩及变质岩中（云母片岩及某些片麻岩）\n白云母镜下照片：\n\n\n\n\n\n\n白云母初步讲解视频：","sourceVideos":[{"title":"白云母初步讲解视频：","localPath":"video/860_0.mp4","posterLocalPath":"video/860_0.jpg","url":"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/videos/v_1497082864.mp4","sha256":"b37d9725fd34b0a260dc3d6150f857efab1e397ec7826090b32b3a896ad1354d"}],"sourceVideoStatus":"published"},"861":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：正长石</td>\n                        <td>英文名：Orthoclase</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：KAlSi<sub>3</sub>O<sub>8</sub></td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=647\" target=\"_blank\" rel=\"noopener noreferrer\">长石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>正长石：属于二轴晶长石类碱性长石亚类矿物</p>\n<p>【颜色】薄片中无色透明，变化分解后常呈浑浊状，变浑浊的正长石往往呈深褐色或浅红色，这是由于有氧化铁析出的缘故。</p>\n<p>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】负低突起</p>\n<p>【干涉色】为一级灰——灰白</p>\n<p>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】（001）面上为平行消光，（010）面上为斜消光</p>\n<p>【延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)】负延性</p>\n<p>【双晶】最常见的为卡斯巴双晶，在较少情况下可见到巴温诺双晶，不出现聚片双晶</p>\n<p>【光性】二轴晶（-）光性，2V大，较少数为（+）光性</p>\n<p>【次生变化】正长石最易变为高岭石，其次是绢云母。在气成热液作用下，可被绿帘石、方解石、电气石、钠长石、白云母、石英等交代</p>\n<p>【鉴定特征】表面浑浊，负低突起，卡斯巴双晶，无钠长石双晶及肖钠长石双晶</p>\n<p>（1） 与石英的区别：石英为正低突起，表面光滑，无解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)，无双晶，石英为一轴晶，正光性</p>\n<p>（2） 与酸性斜长石的区别：正长石不可能有钠长石聚片双晶，斜长石变化后变为绢云母，而正长石多变化为高岭石（在正交偏光下呈灰色，而绢云母为黄棕色）。斜长石的突起、干涉色均比正长石高</p>\n<p>（3） 与霞石的区别：霞石为一轴晶，突起可正可负，多变化为沸石、钙霞石等。而正长石多变化为高岭石。</p>\n<p>（4） 与微斜长石的区别：微斜长石有格子状双晶，无双晶者其消光角在（001）面上为15°，而正长石为平行消光</p>\n<p>【产状】</p>\n<p>1、 正长石产于酸性岩、碱性岩及其过度类型的岩石中，花岗伟晶岩及各种煌斑岩内也有产出</p>\n<p>2、 在变质岩中的钾钠长石多为微斜长石，很少是正长石，但在正片麻岩、花岗片麻岩、片岩、粒变岩及接触变质岩中也有正长石</p>\n<p>3、 正长石常见于碎屑岩中，如长石砂岩及一些硬砂岩</p>\n<p>正长石单偏光镜下照片：</p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1490887056.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/861_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n<p> </p>\n<p> 钾长石镜下特殊现象照片：</p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497063512.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/861_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497063514.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/861_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497063516.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/861_3.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497063519.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/861_4.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n\n        ","sourceFullDescriptionText":"描述\n            \n正长石：属于二轴晶长石类碱性长石亚类矿物\n【颜色】薄片中无色透明，变化分解后常呈浑浊状，变浑浊的正长石往往呈深褐色或浅红色，这是由于有氧化铁析出的缘故。\n【突起 (查看突起测定方法)】负低突起\n【干涉色】为一级灰——灰白\n【消光 (查看消光测定方法)】（001）面上为平行消光，（010）面上为斜消光\n【延性 (查看延性测定方法)】负延性\n【双晶】最常见的为卡斯巴双晶，在较少情况下可见到巴温诺双晶，不出现聚片双晶\n【光性】二轴晶（-）光性，2V大，较少数为（+）光性\n【次生变化】正长石最易变为高岭石，其次是绢云母。在气成热液作用下，可被绿帘石、方解石、电气石、钠长石、白云母、石英等交代\n【鉴定特征】表面浑浊，负低突起，卡斯巴双晶，无钠长石双晶及肖钠长石双晶\n（1） 与石英的区别：石英为正低突起，表面光滑，无解理 (查看解理测定方法)，无双晶，石英为一轴晶，正光性\n（2） 与酸性斜长石的区别：正长石不可能有钠长石聚片双晶，斜长石变化后变为绢云母，而正长石多变化为高岭石（在正交偏光下呈灰色，而绢云母为黄棕色）。斜长石的突起、干涉色均比正长石高\n（3） 与霞石的区别：霞石为一轴晶，突起可正可负，多变化为沸石、钙霞石等。而正长石多变化为高岭石。\n（4） 与微斜长石的区别：微斜长石有格子状双晶，无双晶者其消光角在（001）面上为15°，而正长石为平行消光\n【产状】\n1、 正长石产于酸性岩、碱性岩及其过度类型的岩石中，花岗伟晶岩及各种煌斑岩内也有产出\n2、 在变质岩中的钾钠长石多为微斜长石，很少是正长石，但在正片麻岩、花岗片麻岩、片岩、粒变岩及接触变质岩中也有正长石\n3、 正长石常见于碎屑岩中，如长石砂岩及一些硬砂岩\n正长石单偏光镜下照片：\n\n\n\n \n 钾长石镜下特殊现象照片：","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"862":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：微斜长石</td>\n                        <td>英文名：Microcline</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：KAlSi<sub>3</sub>O<sub>8</sub></td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=647\" target=\"_blank\" rel=\"noopener noreferrer\">长石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>微斜长石：属于二轴晶长石类碱性长石亚类矿物。</p>\n<p>【颜色】薄片中无色，变化后表面浑浊微带浅红色</p>\n<p>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】负低突起</p>\n<p>【干涉色】一级灰白—一级灰</p>\n<p>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】均为斜消光</p>\n<p>【双晶】最特征的是钠长石聚片双晶与肖钠长石聚片双晶组成的格子状双晶，聚片外形通常为纺锤状，此外尚有卡斯巴双晶以及巴温诺双晶、曼尼巴双晶等</p>\n<p>【光性】二轴晶（-）光性为主，但也有少数为（+）光性的正微斜长石，由于长石的双晶发育，所以不易获得完整的干涉图</p>\n<p>【次生变化】常发生高岭石化</p>\n<p>【鉴定特征】格子状双晶，负低突起</p>\n<p>与正长石的区别：微斜长石具格子状双晶，而正长石不可能具有这类双晶</p>\n<p>与歪长石的区别：微斜长石和歪长石具格子状双晶，歪长石的页片更细密，较平直</p>\n<p>【产状】微斜长石为低温下稳定的变种，主要分布于深成侵入岩中，如花岗岩、花岗伟晶岩。其次，微斜长石大量出现于片麻岩及结晶片岩中，碎屑沉积岩里也有微斜长石出现</p>\n<p>微斜长石单偏光镜下照片：</p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1490683602.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/862_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p>微斜长石镜下特殊现象照片：</p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1490883533.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/862_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1490883536.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/862_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1490883538.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/862_3.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1490883540.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/862_4.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n\n        ","sourceFullDescriptionText":"描述\n            \n微斜长石：属于二轴晶长石类碱性长石亚类矿物。\n【颜色】薄片中无色，变化后表面浑浊微带浅红色\n【突起 (查看突起测定方法)】负低突起\n【干涉色】一级灰白—一级灰\n【消光 (查看消光测定方法)】均为斜消光\n【双晶】最特征的是钠长石聚片双晶与肖钠长石聚片双晶组成的格子状双晶，聚片外形通常为纺锤状，此外尚有卡斯巴双晶以及巴温诺双晶、曼尼巴双晶等\n【光性】二轴晶（-）光性为主，但也有少数为（+）光性的正微斜长石，由于长石的双晶发育，所以不易获得完整的干涉图\n【次生变化】常发生高岭石化\n【鉴定特征】格子状双晶，负低突起\n与正长石的区别：微斜长石具格子状双晶，而正长石不可能具有这类双晶\n与歪长石的区别：微斜长石和歪长石具格子状双晶，歪长石的页片更细密，较平直\n【产状】微斜长石为低温下稳定的变种，主要分布于深成侵入岩中，如花岗岩、花岗伟晶岩。其次，微斜长石大量出现于片麻岩及结晶片岩中，碎屑沉积岩里也有微斜长石出现\n微斜长石单偏光镜下照片：\n\n微斜长石镜下特殊现象照片：","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"863":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：斜长石</td>\n                        <td>英文名：Plagioclase</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：NaAlSi<sub>3</sub>O<sub>8</sub>（Ab）－CaAl<sub>2</sub>Si<sub>2</sub>O<sub>8</sub>（An）</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=647\" target=\"_blank\" rel=\"noopener noreferrer\">长石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>斜长石：二轴晶长石类矿物</p>\n<p>【颜色】无色透明，表面洁净</p>\n<p>【形态】长板状、柱状</p>\n<p>【解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)】一组完全解理</p>\n<p>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正低突起</p>\n<p>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】斜消光</p>\n<p>【干涉色】多数为一级灰，少数可达一级淡黄</p>\n<p>【双晶】斜长石双晶发育，常见的有聚片双晶，其次是卡纳连晶和钠长石-肖钠长石双晶构成的格子状双晶，单独的卡斯巴双晶、曼尼巴双晶等少见</p>\n<p>【次生变化】斜长石很容易发生变化，尤其是基性斜长石更为常见。最常见的是蚀变为绢云母、黝帘石化、碳酸盐化、方柱石化、绿泥石化、钠黝帘石化（所谓的钠黝帘石并非是一种独立的矿物，而是由钠长石、黝帘石、斜黝帘石、方解石、绢云母等矿物集合体）等。具环带构造的斜长石晶体上，富钙的环带往往比贫钙的环带蚀变更加强烈。</p>\n<p>【鉴定特征】聚片双晶，具特征的环带结构，中性斜长石尤为发育（中心为基性斜长石，边缘为酸性斜长石则为正环带结构，否则为反环带结构）</p>\n<p>斜长石镜下特殊现象照片：</p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497062884.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/863_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497062886.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/863_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497062888.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/863_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497062891.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/863_3.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497062893.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/863_4.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497062895.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/863_5.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n\n        ","sourceFullDescriptionText":"描述\n            \n斜长石：二轴晶长石类矿物\n【颜色】无色透明，表面洁净\n【形态】长板状、柱状\n【解理 (查看解理测定方法)】一组完全解理\n【突起 (查看突起测定方法)】正低突起\n【消光 (查看消光测定方法)】斜消光\n【干涉色】多数为一级灰，少数可达一级淡黄\n【双晶】斜长石双晶发育，常见的有聚片双晶，其次是卡纳连晶和钠长石-肖钠长石双晶构成的格子状双晶，单独的卡斯巴双晶、曼尼巴双晶等少见\n【次生变化】斜长石很容易发生变化，尤其是基性斜长石更为常见。最常见的是蚀变为绢云母、黝帘石化、碳酸盐化、方柱石化、绿泥石化、钠黝帘石化（所谓的钠黝帘石并非是一种独立的矿物，而是由钠长石、黝帘石、斜黝帘石、方解石、绢云母等矿物集合体）等。具环带构造的斜长石晶体上，富钙的环带往往比贫钙的环带蚀变更加强烈。\n【鉴定特征】聚片双晶，具特征的环带结构，中性斜长石尤为发育（中心为基性斜长石，边缘为酸性斜长石则为正环带结构，否则为反环带结构）\n斜长石镜下特殊现象照片：","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"864":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：条纹长石</td>\n                        <td>英文名：Perthite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：KAlSi<sub>3</sub>O<sub>8</sub>（or）－NaAlSi<sub>3</sub>O<sub>8</sub>（Ab）</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=647\" target=\"_blank\" rel=\"noopener noreferrer\">长石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>条纹长石：二轴晶长石类矿物</p>\n<p>具有条纹结构，由钾长石和钠长石（有时为更长石）组成。两者多的称为主晶，相对少的称为客晶。如果钠长石（一级白干涉色）为主晶，则为反条纹长石；如果钾长石（一级灰）为主晶，称之为正条纹长石</p>\n<p>【颜色】无色透明，表面洁净</p>\n<p>【形态】长板状、柱状</p>\n<p>【干涉色】钠长石为一级白，钾长石为一级灰</p>\n<p>根据客晶大小，通常可分为4类</p>\n<p>（1）纹长石：标本上可见条纹结构</p>\n<p>（2）微纹长石：显微镜下能看到明显的条纹结构，手标本基本看不见</p>\n<p>（3）隐微纹长石：镜下隐约能见到条纹结构</p>\n<p>（4）X-射线纹长石：只有X-射线才能发觉</p>\n<p>客晶形态多样，如细脉状、薄膜状、树枝状、火焰状等</p>\n<p>【成因】条纹长石成因分为两种</p>\n<p>一、析离成因的条纹</p>\n<p>1.较小，条纹宽度小于0.1~0.15mm</p>\n<p>2.形态规则</p>\n<p>3.沿主晶方向分布[平行（100）或近似平行（100方位）]</p>\n<p>4.钠长石客晶一般不显双晶</p>\n<p>5.形成温度较高</p>\n<p>6.条纹限于晶粒内，核部比边部多</p>\n<p>二、交代成因的条纹</p>\n<p>1.大小不一，粗细不一</p>\n<p>2.形态不规则，如树枝状、羽毛状等</p>\n<p>3.在主晶中无固定方位</p>\n<p>4.钠长石客晶可显钠长石双晶</p>\n<p>5.形成温度较低，由钠长石交代钾长石形成</p>\n<p>6.有的在主晶边缘呈薄膜状，有的由外部向内侵入主晶，尖端朝内</p>\n<p>条纹长石镜下特殊现象照片：</p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497063163.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/864_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497063165.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/864_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497063167.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/864_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497063169.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/864_3.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497063172.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/864_4.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497063174.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/864_5.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n\n        ","sourceFullDescriptionText":"描述\n            \n条纹长石：二轴晶长石类矿物\n具有条纹结构，由钾长石和钠长石（有时为更长石）组成。两者多的称为主晶，相对少的称为客晶。如果钠长石（一级白干涉色）为主晶，则为反条纹长石；如果钾长石（一级灰）为主晶，称之为正条纹长石\n【颜色】无色透明，表面洁净\n【形态】长板状、柱状\n【干涉色】钠长石为一级白，钾长石为一级灰\n根据客晶大小，通常可分为4类\n（1）纹长石：标本上可见条纹结构\n（2）微纹长石：显微镜下能看到明显的条纹结构，手标本基本看不见\n（3）隐微纹长石：镜下隐约能见到条纹结构\n（4）X-射线纹长石：只有X-射线才能发觉\n客晶形态多样，如细脉状、薄膜状、树枝状、火焰状等\n【成因】条纹长石成因分为两种\n一、析离成因的条纹\n1.较小，条纹宽度小于0.1~0.15mm\n2.形态规则\n3.沿主晶方向分布[平行（100）或近似平行（100方位）]\n4.钠长石客晶一般不显双晶\n5.形成温度较高\n6.条纹限于晶粒内，核部比边部多\n二、交代成因的条纹\n1.大小不一，粗细不一\n2.形态不规则，如树枝状、羽毛状等\n3.在主晶中无固定方位\n4.钠长石客晶可显钠长石双晶\n5.形成温度较低，由钠长石交代钾长石形成\n6.有的在主晶边缘呈薄膜状，有的由外部向内侵入主晶，尖端朝内\n条纹长石镜下特殊现象照片：","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"865":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：绿泥石</td>\n                        <td>英文名：Chlorite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式： (Mg,Al, Fe)<sub>6</sub>[(Si, Al)<sub>4</sub>O<sub>10</sub>](OH)<sub>8 </sub></td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=650\" target=\"_blank\" rel=\"noopener noreferrer\">绿泥石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>绿泥石：属于二轴晶绿泥石类矿物</p>\n<p>【颜色】薄片中为浅黄色和浅绿色，有多色性</p>\n<p>【形态】绿泥石属层状硅酸盐，结晶均为单斜晶系，多数为鳞片状集合体</p>\n<p>【解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)】{001}解理极完全</p>\n<p>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正低突起至正中突起</p>\n<p>【干涉色】双折射率低，干涉色不超过一级，一般为一级灰，有些具靛蓝色或铁锈色的异常干涉色</p>\n<p>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】斜消光，消光角小</p>\n<p>【延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)】有正负之分</p>\n<p>【光性】光性符号与延性相反，色散较强，光性符号不同的绿泥石，其吸收公式和色散情况也不相同，正光性绿泥石Np=Nm&gt;Ng，r&lt;v；负光性绿泥石Ng=Nm&gt;Np，r&lt;v</p>\n<p>【产状】绿泥石是分布很广的岩浆期后矿物，交代角闪石、黑云母等镁铁暗色矿物。有时也交代石英、长石。其次，绿泥石也是绿片岩相区域变质岩的主要组成矿物</p>\n\n        ","sourceFullDescriptionText":"描述\n            \n绿泥石：属于二轴晶绿泥石类矿物\n【颜色】薄片中为浅黄色和浅绿色，有多色性\n【形态】绿泥石属层状硅酸盐，结晶均为单斜晶系，多数为鳞片状集合体\n【解理 (查看解理测定方法)】{001}解理极完全\n【突起 (查看突起测定方法)】正低突起至正中突起\n【干涉色】双折射率低，干涉色不超过一级，一般为一级灰，有些具靛蓝色或铁锈色的异常干涉色\n【消光 (查看消光测定方法)】斜消光，消光角小\n【延性 (查看延性测定方法)】有正负之分\n【光性】光性符号与延性相反，色散较强，光性符号不同的绿泥石，其吸收公式和色散情况也不相同，正光性绿泥石Np=Nm>Ng，r<v；负光性绿泥石Ng=Nm>Np，r<v\n【产状】绿泥石是分布很广的岩浆期后矿物，交代角闪石、黑云母等镁铁暗色矿物。有时也交代石英、长石。其次，绿泥石也是绿片岩相区域变质岩的主要组成矿物","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"866":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：电气石</td>\n                        <td>英文名：Tourmaline</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：NaFe<sup>2+</sup><sub>3</sub>Al<sub>6</sub>(BO<sub>3</sub>)<sub>3</sub>[Si<sub>6</sub>O<sub>18</sub>](OH)<sub>4</sub></td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=636\" target=\"_blank\" rel=\"noopener noreferrer\">一轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=643\" target=\"_blank\" rel=\"noopener noreferrer\">电气石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>电气石：属于一轴晶电气石类矿物<br> 【颜色】薄片中常呈灰色、蓝色、紫蓝色、橄榄绿等，颜色随Fe<sup>2+</sup>、Fe<sup>3+</sup>含量的增加而加深，含少量Cu时呈蓝色或蓝绿色，含Cr时呈深绿色<br> 多色性显著：No=浅黄褐至黑色、暗绿色、蓝色<br> Ne=鲜黄色至暗黄色、淡红紫色、浅褐色、浅绿色、紫绿色<br> 吸收性公式：No&gt;Ne<br> 底切面无多色性，颜色常呈环带状分布<br> 【形态】晶体呈短柱状至长柱状，一般含镁铁越多，柱越长。横切面为弧面三角形，晶体时常聚合成柱状或放射状集合体<br> 【解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)】{100}完全解理,{010}清楚解理可见，{001}横裂纹发育<br> 【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正中-正高突起，随Fe<sup>2+</sup>含量的增加而增加<br> 【干涉色】干涉色为二级底部至三级顶部，但常被颜色所掩盖<br> 【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】平行消光<br> 【延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)】负延性<br> 【产状】黑电气石是一种与酸性岩浆有关的典型气成矿物，电气石化属高温蚀变作用。电气石多见于花岗伟晶岩与云英岩中，也可少量出现于花岗岩及混合岩内，针状电气石常包裹于石英、长石、云母中。在片麻岩与沉积岩中可见，也是重砂中分布最广的矿物</p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1491966493.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/866_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1491966495.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/866_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1491966497.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/866_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n\n        ","sourceFullDescriptionText":"描述\n            \n电气石：属于一轴晶电气石类矿物 【颜色】薄片中常呈灰色、蓝色、紫蓝色、橄榄绿等，颜色随Fe2+、Fe3+含量的增加而加深，含少量Cu时呈蓝色或蓝绿色，含Cr时呈深绿色 多色性显著：No=浅黄褐至黑色、暗绿色、蓝色 Ne=鲜黄色至暗黄色、淡红紫色、浅褐色、浅绿色、紫绿色 吸收性公式：No>Ne 底切面无多色性，颜色常呈环带状分布 【形态】晶体呈短柱状至长柱状，一般含镁铁越多，柱越长。横切面为弧面三角形，晶体时常聚合成柱状或放射状集合体 【解理 (查看解理测定方法)】{100}完全解理,{010}清楚解理可见，{001}横裂纹发育 【突起 (查看突起测定方法)】正中-正高突起，随Fe2+含量的增加而增加 【干涉色】干涉色为二级底部至三级顶部，但常被颜色所掩盖 【消光 (查看消光测定方法)】平行消光 【延性 (查看延性测定方法)】负延性 【产状】黑电气石是一种与酸性岩浆有关的典型气成矿物，电气石化属高温蚀变作用。电气石多见于花岗伟晶岩与云英岩中，也可少量出现于花岗岩及混合岩内，针状电气石常包裹于石英、长石、云母中。在片麻岩与沉积岩中可见，也是重砂中分布最广的矿物","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"867":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：蓝晶石</td>\n                        <td>英文名：Kyanite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：Al<sub>2</sub>[SiO<sub>4</sub>]O </td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=656\" target=\"_blank\" rel=\"noopener noreferrer\">绿帘石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>蓝晶石：属于二轴晶绿帘石类矿物<br>【颜色】薄片中无色至浅蓝色<br>【形态】晶体呈沿c轴延伸并平行{100}的板状，有时呈放射状集合体，偶尔可见假六方形形态<br>【解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)】{100}完全解理,{010}清楚解理可见，{001}横裂纹发育<br>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正高突起<br>【干涉色】最高干涉色为二级蓝，一般为一级黄-橙，或者黄白、灰白色<br>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】斜消光，消光角最大可达32°，但在{001}面上近于平行消光<br>【延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)】正延性<br>【双晶】有简单双晶或聚片双晶，双晶面为{100}、{010}、{212}<br>【变种】易变成白云母，有时为叶蜡石代替，也可能被矽线石交代<br>【产状】蓝晶石是典型的泥质岩区域变质矿物，产于蓝晶石片岩、云母片岩、片麻岩、榴辉岩等岩石中。也可出现于碎屑沉积物中，岩浆岩中无蓝晶石产出</p>\n<p>蓝晶石镜下特殊现象照片：</p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1491968075.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/867_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1491968077.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/867_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1491968079.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/867_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1491968081.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/867_3.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1491968082.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/867_4.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n<p>蓝晶石镜下初步讲解：</p>\n<p></p><p></p>\n\n        ","sourceFullDescriptionText":"描述\n            \n蓝晶石：属于二轴晶绿帘石类矿物【颜色】薄片中无色至浅蓝色【形态】晶体呈沿c轴延伸并平行{100}的板状，有时呈放射状集合体，偶尔可见假六方形形态【解理 (查看解理测定方法)】{100}完全解理,{010}清楚解理可见，{001}横裂纹发育【突起 (查看突起测定方法)】正高突起【干涉色】最高干涉色为二级蓝，一般为一级黄-橙，或者黄白、灰白色【消光 (查看消光测定方法)】斜消光，消光角最大可达32°，但在{001}面上近于平行消光【延性 (查看延性测定方法)】正延性【双晶】有简单双晶或聚片双晶，双晶面为{100}、{010}、{212}【变种】易变成白云母，有时为叶蜡石代替，也可能被矽线石交代【产状】蓝晶石是典型的泥质岩区域变质矿物，产于蓝晶石片岩、云母片岩、片麻岩、榴辉岩等岩石中。也可出现于碎屑沉积物中，岩浆岩中无蓝晶石产出\n蓝晶石镜下特殊现象照片：\n\n\n\n\n\n\n\n蓝晶石镜下初步讲解：","sourceVideos":[{"title":"蓝晶石镜下初步讲解：","localPath":"video/867_0.mp4","posterLocalPath":"video/867_0.jpg","url":"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/videos/v_1491968085.mp4","sha256":"51bc1a55a97e4f0a34951d868fe54afe701e0f4aa6e4a9173bb089c8f428370b"}],"sourceVideoStatus":"published"},"868":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：符山石</td>\n                        <td>英文名：Vesuvianite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：Ca<sub>10</sub>(Mg,Fe)<sub>2</sub>Al<sub>4</sub>[SiO<sub>4</sub>]<sub>5</sub>[Si<sub>2</sub>O<sub>7</sub>]<sub>2</sub>(OH)<sub>4</sub></td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=636\" target=\"_blank\" rel=\"noopener noreferrer\">一轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=644\" target=\"_blank\" rel=\"noopener noreferrer\">碳酸盐类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>符山石：一轴晶碳酸盐类矿物<br>【形态】晶体常呈粒状、棒状或放射状集合体<br>【颜色】薄片中无色或浅黄、浅绿、浅褐。多色性不明显<br>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正高突起<br>【解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)】{110}不完全解理，柱面上有纵纹<br>【干涉色】一级灰，但往往呈现灰棕、紫、深蓝，绿色的异常干涉色，有时同一晶体，各部位的干涉色各不相同，有呈环带状变化或呈无定向分布的斑点状<br>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】平行消光<br>【延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)】负延性<br>【次生变化】在热液作用下，可被云母、绿泥石、滑石所代替<br>【鉴定特征】横切面常呈四方形或有颜色的带状集合体，正高突起，双折率低，有异常干涉色，常为一轴晶<br>【产状】硅酸盐类的接触变质产物或脉状产物，产于接触带中，是组成矽卡岩的矿物之一，常与钙铝石榴石、透辉石、硅灰石、绿帘石和方解石伴生，有时也与磁铁矿、萤石、绿泥石共生</p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1491976606.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/868_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n        ","sourceFullDescriptionText":"描述\n            \n符山石：一轴晶碳酸盐类矿物【形态】晶体常呈粒状、棒状或放射状集合体【颜色】薄片中无色或浅黄、浅绿、浅褐。多色性不明显【突起 (查看突起测定方法)】正高突起【解理 (查看解理测定方法)】{110}不完全解理，柱面上有纵纹【干涉色】一级灰，但往往呈现灰棕、紫、深蓝，绿色的异常干涉色，有时同一晶体，各部位的干涉色各不相同，有呈环带状变化或呈无定向分布的斑点状【消光 (查看消光测定方法)】平行消光【延性 (查看延性测定方法)】负延性【次生变化】在热液作用下，可被云母、绿泥石、滑石所代替【鉴定特征】横切面常呈四方形或有颜色的带状集合体，正高突起，双折率低，有异常干涉色，常为一轴晶【产状】硅酸盐类的接触变质产物或脉状产物，产于接触带中，是组成矽卡岩的矿物之一，常与钙铝石榴石、透辉石、硅灰石、绿帘石和方解石伴生，有时也与磁铁矿、萤石、绿泥石共生","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"869":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：十字石</td>\n                        <td>英文名：Staurolite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：(Fe<sup>2+</sup>,Mg,Zn)<sub>2</sub>(Al,Fe<sup>3+</sup>)<sub>9</sub>O<sub>6</sub>[SiO<sub>4</sub>]<sub>4</sub>(O,OH)<sub>2</sub></td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=656\" target=\"_blank\" rel=\"noopener noreferrer\">绿帘石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>十字石：二轴晶矿物<br>【形态】晶体呈短柱状或者粒状，横切面为六边形<br>【颜色】薄片中呈橙黄色，可见较弱的多色性：</p>\n<p>Ng=金黄<br> Nm=浅黄<br> Np=黄白-近于无色<br> 吸收性为：Ng&gt;Nm&gt;Np <br>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正高突起<br>【解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)】{010}解理清楚，{110}不完全解理<br>【干涉色】一级黄至一级红</p>\n<p>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】纵切面为平行消光，横切面为对称消光<br>【延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)】纵切面为正延性<br>【双晶】依{031}和{231}十字形贯穿双晶常见，呈十字形或斜十字形，薄片中少见，而可 见沿{031}的接触双晶<br>【次生变化】十字形变化后可成为绢云母、绿泥石或褐铁矿等<br>【鉴定特征】金黄色，具多色性，含较多的矿物包裹体，干涉色低以及具十字双晶，与褐帘石的区别是十字石折射率较低，常有石英包裹体<br>【产状】主要产于片岩、千枚岩、片麻岩中，与石榴石、蓝晶石、金红石、云母等共生。是砂岩和沉积物中分布较广的碎屑矿物</p>\n<p>镜下特殊现象照片：</p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1491990187.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/869_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1491990189.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/869_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1491990191.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/869_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n\n        ","sourceFullDescriptionText":"描述\n            \n十字石：二轴晶矿物【形态】晶体呈短柱状或者粒状，横切面为六边形【颜色】薄片中呈橙黄色，可见较弱的多色性：\nNg=金黄 Nm=浅黄 Np=黄白-近于无色 吸收性为：Ng>Nm>Np 【突起 (查看突起测定方法)】正高突起【解理 (查看解理测定方法)】{010}解理清楚，{110}不完全解理【干涉色】一级黄至一级红\n【消光 (查看消光测定方法)】纵切面为平行消光，横切面为对称消光【延性 (查看延性测定方法)】纵切面为正延性【双晶】依{031}和{231}十字形贯穿双晶常见，呈十字形或斜十字形，薄片中少见，而可 见沿{031}的接触双晶【次生变化】十字形变化后可成为绢云母、绿泥石或褐铁矿等【鉴定特征】金黄色，具多色性，含较多的矿物包裹体，干涉色低以及具十字双晶，与褐帘石的区别是十字石折射率较低，常有石英包裹体【产状】主要产于片岩、千枚岩、片麻岩中，与石榴石、蓝晶石、金红石、云母等共生。是砂岩和沉积物中分布较广的碎屑矿物\n镜下特殊现象照片：","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"870":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：硬绿泥石</td>\n                        <td>英文名：Chloritoid</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：(Fe<sup>2+</sup>,Mg,Mn)<sub>2</sub>(Al,Fe<sup>3+</sup>)Al<sub>2</sub>O<sub>3</sub>[SiO<sub>4</sub>](OH)<sub>4</sub></td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=653\" target=\"_blank\" rel=\"noopener noreferrer\">脆云母类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>硬绿泥石：属于二轴晶脆云母类矿物<br>【颜色】薄片中从橄榄绿到靛蓝色，<br> 有多色性：Ng=黄绿-靛蓝色<br> Nm=暗灰蓝色<br> Np=橄榄绿-蓝绿<br> 有些具暗色中心或浅色边，其次为绿色的环带，还有砂钟构造<br>【形态】晶体呈柱状或假六方形板状，粒状，有时呈束状集合体，常有石英、磁铁矿、金红石等矿物的包裹体，可呈砂钟构造<br>【解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)】{001}完全解理,{110}不完全解理，并具{010}裂开<br>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正高突起<br>【干涉色】最高干涉色为一级淡黄，但因受颜色影响不易辨别，多显一级灰<br>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】单斜系的平行b轴切面可见平行消光，负延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)。其它切面均为斜消光，消光角在16°左右<br>【双晶】以{001}为结合面的简单双晶，也可见三连晶和聚片双晶<br>【变种】可转变为白云母、叶绿泥石或高岭石<br>【产状】主要产于区域变质的千枚岩、绿泥石片岩及云母片岩中。也可成水热矿物存在于石英-铁白云石石脉中。水热成因的硬绿泥石通常为三斜晶系，而多形者则见于变质岩中，但单斜晶系更普遍的是与铁铝榴石共生</p>\n<p>硬绿泥石镜下特殊现象照片：</p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1491991641.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/870_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1491991643.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/870_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1491991646.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/870_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n<p>硬绿泥石讲解视频：</p>\n<p></p><p></p>\n\n        ","sourceFullDescriptionText":"描述\n            \n硬绿泥石：属于二轴晶脆云母类矿物【颜色】薄片中从橄榄绿到靛蓝色， 有多色性：Ng=黄绿-靛蓝色 Nm=暗灰蓝色 Np=橄榄绿-蓝绿 有些具暗色中心或浅色边，其次为绿色的环带，还有砂钟构造【形态】晶体呈柱状或假六方形板状，粒状，有时呈束状集合体，常有石英、磁铁矿、金红石等矿物的包裹体，可呈砂钟构造【解理 (查看解理测定方法)】{001}完全解理,{110}不完全解理，并具{010}裂开【突起 (查看突起测定方法)】正高突起【干涉色】最高干涉色为一级淡黄，但因受颜色影响不易辨别，多显一级灰【消光 (查看消光测定方法)】单斜系的平行b轴切面可见平行消光，负延性 (查看延性测定方法)。其它切面均为斜消光，消光角在16°左右【双晶】以{001}为结合面的简单双晶，也可见三连晶和聚片双晶【变种】可转变为白云母、叶绿泥石或高岭石【产状】主要产于区域变质的千枚岩、绿泥石片岩及云母片岩中。也可成水热矿物存在于石英-铁白云石石脉中。水热成因的硬绿泥石通常为三斜晶系，而多形者则见于变质岩中，但单斜晶系更普遍的是与铁铝榴石共生\n硬绿泥石镜下特殊现象照片：\n\n\n\n\n\n硬绿泥石讲解视频：","sourceVideos":[{"title":"硬绿泥石讲解视频：","localPath":"video/870_0.mp4","posterLocalPath":"video/870_0.jpg","url":"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/videos/v_1497093512.mp4","sha256":"37ae80ebd347b94cc7fa17f2d1c745c06089828160a3fd4456b3c483b67cb2ae"}],"sourceVideoStatus":"published"},"871":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：霞石</td>\n                        <td>英文名：Nepheline</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：（Na，K）AlSiO<sub>4</sub></td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=636\" target=\"_blank\" rel=\"noopener noreferrer\">一轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=641\" target=\"_blank\" rel=\"noopener noreferrer\">霞石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>霞石：一轴晶霞石类矿物<br>【形态】晶体常呈六方板状、不规则片状，纵切面为长方形或正方形，横切面为六边形，也可呈环带状<br>【颜色】薄片中呈无色或浑浊的浅褐色<br>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】负低-正低突起<br>【解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)】{0001}、{1010}不完全解理，裂纹方向不定，其附近常有蚀变产物<br>【干涉色】一级灰<br>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】六边形地切面全消光，柱状切面具平行消光、负延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)<br>【延性】负延性<br>【次生变化】霞石不稳定，亦转化为钠沸石、水霞石、钙霞石、白云母和方钠石等<br>【鉴定特征】霞石在镜下以其断面形态（四边形、六边形居多），负低-正低突起，干涉色低，表面不洁净，一轴晶负光性<br>【产状】只见于富钠贫硅的碱性岩浆岩中，如霞石正长岩、响岩，因为霞石是二氧化硅不饱和的产物，故不与原生石英共生</p>\n<p>霞石横切面镜下照片：</p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1493872817.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/871_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1493872819.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/871_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n<p>霞石纵切面单偏光镜下照片：</p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1491992223.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/871_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n\n        ","sourceFullDescriptionText":"描述\n            \n霞石：一轴晶霞石类矿物【形态】晶体常呈六方板状、不规则片状，纵切面为长方形或正方形，横切面为六边形，也可呈环带状【颜色】薄片中呈无色或浑浊的浅褐色【突起 (查看突起测定方法)】负低-正低突起【解理 (查看解理测定方法)】{0001}、{1010}不完全解理，裂纹方向不定，其附近常有蚀变产物【干涉色】一级灰【消光 (查看消光测定方法)】六边形地切面全消光，柱状切面具平行消光、负延性 (查看延性测定方法)【延性】负延性【次生变化】霞石不稳定，亦转化为钠沸石、水霞石、钙霞石、白云母和方钠石等【鉴定特征】霞石在镜下以其断面形态（四边形、六边形居多），负低-正低突起，干涉色低，表面不洁净，一轴晶负光性【产状】只见于富钠贫硅的碱性岩浆岩中，如霞石正长岩、响岩，因为霞石是二氧化硅不饱和的产物，故不与原生石英共生\n霞石横切面镜下照片：\n\n\n\n\n霞石纵切面单偏光镜下照片：","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"873":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：绿帘石</td>\n                        <td>英文名：Epidote</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：Ca<sub>2</sub>Al<sub>2</sub>(Fe<sup>3+</sup>,Al)[SiO<sub>4</sub>][Si<sub>2</sub>O<sub>7</sub>]O(OH)</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=656\" target=\"_blank\" rel=\"noopener noreferrer\">绿帘石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>绿帘石：二轴晶绿帘石类矿物<br>【形态】晶体常呈延b轴延伸的柱状、纤维状、厚板状。常呈粒状集合体，放射状的少见<br>【颜色】 薄片中呈淡黄、黄绿、无色，颜色分布常不均匀<br> 微具多色性： Ng=无色-淡黄绿色<br> Nm=绿色<br> Np=无色-淡柠檬黄<br> 吸收性公式：Nm&gt;Ng&gt;Np<br> 有时在中心或者是在边缘同斜黝帘石组成环带，以褐帘石为中心，绿帘石为边的丛生现象也存在<br>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正高突起，折射率随含铁量的增加而增加<br>【解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)】{001}完全解理，{100}不完全解理<br>【干涉色】最高干涉色达二级顶部至三级顶部，通常具有异常的干涉色，常呈很浓的橙黄色、绿色、蓝绿色或者深红色，干涉色分布不均匀<br>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】延长切面为平行消光，其它切面为斜消光<br>【延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)】延性可正可负<br>【双晶】{100}双晶常见<br>【次生变化】稳定，很少变化<br>【鉴定特征】绿黄色，有多色性，正高突起，鲜艳的异常干涉色，且分布不均匀，二轴晶负光性<br>【产状】绿帘石为分布广泛的区域变质和热液蚀变矿物，也常见于矽卡岩</p>\n<p>绿帘石讲解视频：</p>\n<p></p><p></p>\n\n        ","sourceFullDescriptionText":"描述\n            \n绿帘石：二轴晶绿帘石类矿物【形态】晶体常呈延b轴延伸的柱状、纤维状、厚板状。常呈粒状集合体，放射状的少见【颜色】 薄片中呈淡黄、黄绿、无色，颜色分布常不均匀 微具多色性： Ng=无色-淡黄绿色 Nm=绿色 Np=无色-淡柠檬黄 吸收性公式：Nm>Ng>Np 有时在中心或者是在边缘同斜黝帘石组成环带，以褐帘石为中心，绿帘石为边的丛生现象也存在【突起 (查看突起测定方法)】正高突起，折射率随含铁量的增加而增加【解理 (查看解理测定方法)】{001}完全解理，{100}不完全解理【干涉色】最高干涉色达二级顶部至三级顶部，通常具有异常的干涉色，常呈很浓的橙黄色、绿色、蓝绿色或者深红色，干涉色分布不均匀【消光 (查看消光测定方法)】延长切面为平行消光，其它切面为斜消光【延性 (查看延性测定方法)】延性可正可负【双晶】{100}双晶常见【次生变化】稳定，很少变化【鉴定特征】绿黄色，有多色性，正高突起，鲜艳的异常干涉色，且分布不均匀，二轴晶负光性【产状】绿帘石为分布广泛的区域变质和热液蚀变矿物，也常见于矽卡岩\n绿帘石讲解视频：","sourceVideos":[{"title":"绿帘石讲解视频：","localPath":"video/873_0.mp4","posterLocalPath":"video/873_0.jpg","url":"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/videos/v_1497084372.mp4","sha256":"2a418dfb1cd5fada6ae5feafe5a7079329ee39cc8d3e73439fc30b49ad99ea8a"}],"sourceVideoStatus":"published"},"874":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：硅灰石</td>\n                        <td>英文名：Wollastonite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：Ca<sub>3</sub>[Si<sub>3</sub>O<sub>9</sub>]</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=652\" target=\"_blank\" rel=\"noopener noreferrer\">角闪石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            <p>硅灰石：二轴晶角闪石类矿物<br>【颜色】无色，有时呈浑浊状（因含有小的包裹体）。含Fe2+多时为浅黄色<br>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正中突起，折射率随着Fe2+增加而增大<br>【干涉色】最高干涉色为一级橙黄，但一般为一级黄<br>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】在∥b轴的切面上接近平行消光，⊥b轴的切面上为斜消光<br>【双晶】有时有以{100}为双晶面的聚片双晶<br>【次生变化】硅灰石可以被针钠钙石和方解石脉交代<br>【鉴定特征】主要在于解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)夹角、较高的折射率与低的干涉色，且能溶于HCL。<br>易于透闪石及绿泥石相混，其区别如下：<br>（1）透闪石具有{110}解理，夹角56°，有较大的双折射率，正延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)，2V很大<br>（2）绿帘石的折射率、双折射率都很高，并且常有明显的多色性及异常干涉色</p>\n        ","sourceFullDescriptionText":"描述\n            硅灰石：二轴晶角闪石类矿物【颜色】无色，有时呈浑浊状（因含有小的包裹体）。含Fe2+多时为浅黄色【突起 (查看突起测定方法)】正中突起，折射率随着Fe2+增加而增大【干涉色】最高干涉色为一级橙黄，但一般为一级黄【消光 (查看消光测定方法)】在∥b轴的切面上接近平行消光，⊥b轴的切面上为斜消光【双晶】有时有以{100}为双晶面的聚片双晶【次生变化】硅灰石可以被针钠钙石和方解石脉交代【鉴定特征】主要在于解理 (查看解理测定方法)夹角、较高的折射率与低的干涉色，且能溶于HCL。易于透闪石及绿泥石相混，其区别如下：（1）透闪石具有{110}解理，夹角56°，有较大的双折射率，正延性 (查看延性测定方法)，2V很大（2）绿帘石的折射率、双折射率都很高，并且常有明显的多色性及异常干涉色","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"875":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：绿辉石</td>\n                        <td>英文名：Omphacite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：(Ca，Na)(Mg，Fe<sup>2+</sup>,Fe<sup>3+</sup>,Al)[Si<sub>2</sub>O<sub>6</sub>]</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=654\" target=\"_blank\" rel=\"noopener noreferrer\">辉石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            <p>绿辉石：二轴晶辉石类矿物<br>【形态】晶体常呈柱状、粒状<br>【颜色】薄片中呈无色或淡绿色，多色性不明显<br>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】负高突起<br>【解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)】横切面上具有{110}、{110}的两组完全解理，交角为93°-92°，纵断面上可见一组解理<br>【干涉色】最高干涉色为二级蓝绿色<br>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】纵切面上斜消光，正延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)，横切面为对称消光，⊥{010}晶带面上为平行消光<br>【延性】正延性<br>【次生变化】可变为蛇纹石或角闪石<br>【鉴定特征】以其特征的颜色可与一般辉石相区别，与透辉石和普通辉石的区别是光轴角大<br>【产状】为榴辉岩及其有关岩石的典型产物，常与镁铝榴石、金红石、斜方辉石、角闪石、石英、蓝晶石共生</p>\n        ","sourceFullDescriptionText":"描述\n            绿辉石：二轴晶辉石类矿物【形态】晶体常呈柱状、粒状【颜色】薄片中呈无色或淡绿色，多色性不明显【突起 (查看突起测定方法)】负高突起【解理 (查看解理测定方法)】横切面上具有{110}、{110}的两组完全解理，交角为93°-92°，纵断面上可见一组解理【干涉色】最高干涉色为二级蓝绿色【消光 (查看消光测定方法)】纵切面上斜消光，正延性 (查看延性测定方法)，横切面为对称消光，⊥{010}晶带面上为平行消光【延性】正延性【次生变化】可变为蛇纹石或角闪石【鉴定特征】以其特征的颜色可与一般辉石相区别，与透辉石和普通辉石的区别是光轴角大【产状】为榴辉岩及其有关岩石的典型产物，常与镁铝榴石、金红石、斜方辉石、角闪石、石英、蓝晶石共生","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"876":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：透闪石</td>\n                        <td>英文名：Tremolite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：Ca<sub>2</sub>Mg<sub>6</sub>[Si<sub>4</sub>O<sub>11</sub>]<sub>2</sub>(OH，F)<sub>2</sub></td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=652\" target=\"_blank\" rel=\"noopener noreferrer\">角闪石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>透闪石：二轴晶角闪石类矿物<br>【颜色】薄片无色，含Mn时呈粉色<br>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正中突起。折射率随Fe<sup>2+</sup>含量增加而增大<br>【干涉色】最高干涉色二级橙黄<br>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】横切面为对称消光，纵切面均为斜消光。<br>【延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)】正延性<br>【双晶】{100}简单双晶或聚片双晶比较常见<br>【次生变化】蚀变为滑石。也常替代透辉石呈其假象，这种透辉石称为假象纤闪石。<br>【鉴定特征】无色、斜消光、具有角闪石式解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)、纤维状集合体<br>与阳起石的区别：阳起石弱多色性、折射率高<br>与硅灰石区别：硅灰石具有多向解理。解理夹角＞60°，而透闪石二组解理夹角＜60°；透闪石干涉色达二级橙黄，硅灰石一般不超过一级；透闪石（-）2V大约84°，而硅灰石仅39°<br>【产状】透闪石是典型的变质矿物，主要产于白云质碳酸盐岩与火成岩的接触变质带。也见于某些富镁的结晶片岩中。假象纤闪石多分布在超基性、基性岩浆岩内，经常是辉石的蚀变产物</p>\n<p>透闪石纵切面单偏光镜下照片：</p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1493113485.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/876_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n        ","sourceFullDescriptionText":"描述\n            \n透闪石：二轴晶角闪石类矿物【颜色】薄片无色，含Mn时呈粉色【突起 (查看突起测定方法)】正中突起。折射率随Fe2+含量增加而增大【干涉色】最高干涉色二级橙黄【消光 (查看消光测定方法)】横切面为对称消光，纵切面均为斜消光。【延性 (查看延性测定方法)】正延性【双晶】{100}简单双晶或聚片双晶比较常见【次生变化】蚀变为滑石。也常替代透辉石呈其假象，这种透辉石称为假象纤闪石。【鉴定特征】无色、斜消光、具有角闪石式解理 (查看解理测定方法)、纤维状集合体与阳起石的区别：阳起石弱多色性、折射率高与硅灰石区别：硅灰石具有多向解理。解理夹角＞60°，而透闪石二组解理夹角＜60°；透闪石干涉色达二级橙黄，硅灰石一般不超过一级；透闪石（-）2V大约84°，而硅灰石仅39°【产状】透闪石是典型的变质矿物，主要产于白云质碳酸盐岩与火成岩的接触变质带。也见于某些富镁的结晶片岩中。假象纤闪石多分布在超基性、基性岩浆岩内，经常是辉石的蚀变产物\n透闪石纵切面单偏光镜下照片：","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"877":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：刚玉</td>\n                        <td>英文名：Corundum</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：Al<sub>2</sub>O<sub>3</sub></td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=636\" target=\"_blank\" rel=\"noopener noreferrer\">一轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=644\" target=\"_blank\" rel=\"noopener noreferrer\">碳酸盐类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>刚玉：一轴晶矿物<br>【形态】晶体常呈桶状、柱状、锥状、板状<br>【颜色】薄片常呈无色，有时呈不均匀的蓝色或者淡红色，带状或者斑点状晶体常见，在厚切片中可以有多色性<br>           No=蓝色、紫色；<br>           Ne=亮蓝、黄绿、黄</p>\n<p>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正高突起<br>【解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)】无解理，具两组解理且呈正交<br>【干涉色】最高干涉色为一级白，但由于矿物硬度很大，薄片较正常厚度厚，因而呈二级蓝干涉色<br>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】平行消光，对于菱形裂开面呈对称消光<br>【延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)】板状晶体的切面为正延性，柱状者为负光性<br>【双晶】以（1010）为双晶接合面的聚片双晶<br>【光性异常】一轴晶（-）光性，有时表现为二轴晶，2V可达58°。有时晶体中央与边部的光轴角不等。<br>【次生变化】主要变为白云母，有时变为尖晶石，蓝晶石，矽线石等<br>【鉴定特征】在于特殊的晶形和很高的突起，较低的双折射率，菱形裂开和很大的硬度。<br> （1）与橄榄石的区别：橄榄石干涉色高达三级，为二轴晶<br> （2）与矽线石的区别：矽线石呈纤状，突起较低，干涉色高<br>【产状】产于富铝岩石的接触变质高温带或区域变质的高级变质岩中，也见于次生石英化的酸性火山岩和含石英极少而富铝的岩浆岩中，如正长石、二长石、霞石正长岩及其伟晶岩</p>\n<p>刚玉单偏光镜下照片：</p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1493108858.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/877_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1493108861.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/877_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n\n        ","sourceFullDescriptionText":"描述\n            \n刚玉：一轴晶矿物【形态】晶体常呈桶状、柱状、锥状、板状【颜色】薄片常呈无色，有时呈不均匀的蓝色或者淡红色，带状或者斑点状晶体常见，在厚切片中可以有多色性           No=蓝色、紫色；           Ne=亮蓝、黄绿、黄\n【突起 (查看突起测定方法)】正高突起【解理 (查看解理测定方法)】无解理，具两组解理且呈正交【干涉色】最高干涉色为一级白，但由于矿物硬度很大，薄片较正常厚度厚，因而呈二级蓝干涉色【消光 (查看消光测定方法)】平行消光，对于菱形裂开面呈对称消光【延性 (查看延性测定方法)】板状晶体的切面为正延性，柱状者为负光性【双晶】以（1010）为双晶接合面的聚片双晶【光性异常】一轴晶（-）光性，有时表现为二轴晶，2V可达58°。有时晶体中央与边部的光轴角不等。【次生变化】主要变为白云母，有时变为尖晶石，蓝晶石，矽线石等【鉴定特征】在于特殊的晶形和很高的突起，较低的双折射率，菱形裂开和很大的硬度。 （1）与橄榄石的区别：橄榄石干涉色高达三级，为二轴晶 （2）与矽线石的区别：矽线石呈纤状，突起较低，干涉色高【产状】产于富铝岩石的接触变质高温带或区域变质的高级变质岩中，也见于次生石英化的酸性火山岩和含石英极少而富铝的岩浆岩中，如正长石、二长石、霞石正长岩及其伟晶岩\n刚玉单偏光镜下照片：","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"878":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：尖晶石</td>\n                        <td>英文名：Spinel</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：(Mg,Fe,Zn,Mn)(Al,Cr,Fe)<sub>2</sub>O<sub>4</sub></td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=6\" target=\"_blank\" rel=\"noopener noreferrer\">均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=570\" target=\"_blank\" rel=\"noopener noreferrer\">方钠石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>尖晶石：均质体方钠石类矿物<br>【颜色】薄片中颜色多种，无色、浅色、绿色、深红、黄绿、褐色等等<br>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正高至正极高突起。折射率随含铁量的增加而增加<br>【解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)】解理不发育，可见不规则裂理或则八面体裂理<br>【干涉色】多为全消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)，仅锌尖晶石有微弱的干涉色<br>【双晶】常见{111}双晶和简单双晶，也可见聚片双晶<br>【次生变化】尖晶石一般不发生蚀变，但有时可变为蛇纹石或滑石<br>【鉴定特征】尖晶石的主要特征在于他的晶形、颜色、正高至正极高突起、全消光及特有的产状。尖晶石种属之间的区别可凭薄片中的颜色，以及矿物的产状。<br>【产状】<br>1.镁尖晶石为高温接触变质矿物，产于白云岩或白云质灰岩与火成岩的接触带，为石榴石、透辉石、金云母和粒硅镁石共生。岩浆岩和某些变质岩里偶有出现。</p>\n<p>2.镁铁尖晶石是岩浆矿物，产于超基性岩<br>3.铬尖晶石常分布在橄榄石和蛇纹石中<br>4.铁尖晶石产于白粒岩、刚玉岩中<br>5.锌尖晶石产于结晶片岩及伟晶岩中</p>\n<p>铬尖晶石镜下照片：</p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1493110950.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/878_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1493110952.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/878_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1493110955.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/878_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n\n        ","sourceFullDescriptionText":"描述\n            \n尖晶石：均质体方钠石类矿物【颜色】薄片中颜色多种，无色、浅色、绿色、深红、黄绿、褐色等等【突起 (查看突起测定方法)】正高至正极高突起。折射率随含铁量的增加而增加【解理 (查看解理测定方法)】解理不发育，可见不规则裂理或则八面体裂理【干涉色】多为全消光 (查看消光测定方法)，仅锌尖晶石有微弱的干涉色【双晶】常见{111}双晶和简单双晶，也可见聚片双晶【次生变化】尖晶石一般不发生蚀变，但有时可变为蛇纹石或滑石【鉴定特征】尖晶石的主要特征在于他的晶形、颜色、正高至正极高突起、全消光及特有的产状。尖晶石种属之间的区别可凭薄片中的颜色，以及矿物的产状。【产状】1.镁尖晶石为高温接触变质矿物，产于白云岩或白云质灰岩与火成岩的接触带，为石榴石、透辉石、金云母和粒硅镁石共生。岩浆岩和某些变质岩里偶有出现。\n2.镁铁尖晶石是岩浆矿物，产于超基性岩3.铬尖晶石常分布在橄榄石和蛇纹石中4.铁尖晶石产于白粒岩、刚玉岩中5.锌尖晶石产于结晶片岩及伟晶岩中\n铬尖晶石镜下照片：","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"879":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：霓辉石</td>\n                        <td>英文名：Aegirine-augite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：(Na,Ca)(Fe<sup>3+</sup>,Fe<sup>2+</sup>,Mg,Al)[Si<sub>2</sub>O<sub>6</sub>]</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=654\" target=\"_blank\" rel=\"noopener noreferrer\">辉石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>霓辉石：二轴晶辉石类矿物<br>【颜色】薄片中绿色或则浅黄色，多色性明显<br>Ng-黄，浅褐<br>Nm-黄或绿色<br>Np-橄榄绿或草绿色<br>颜色常呈环带分布，一般是外环颜色较深，因其霓石含量较高些，而核心近于无色的透辉石或普通辉石成分，但也有相反的 <br>环带。<br>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正高突起，折射率随着霓石分子的增加而增大<br>【干涉色】最高干涉色可达三级蓝绿<br>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】横切面上对于解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)缝呈对称消光，纵切面呈斜消光。<br>【延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)】负延性<br>【双晶】双晶沿{100}常见。简单双晶或聚片双晶。<br>【次生变化】常变为绿泥石，绿帘石、褐帘石、赤铁矿、褐铁矿。<br>【鉴定特征】霓辉石与普通辉石、透辉石的区别是霓辉石呈特有的绿色，多色性明显和负延性，在纵切面上的消光角Ng^C比 <br>后者大。与霓辉石和普通角闪石的区别在于前者的突起、干涉色均较后者高，负延性和辉石式解理。<br>【产状】是碱性岩浆岩晚期结晶产物。主要产于碱性岩石如：正长岩、碱性粗面岩、霞石正长岩、响岩等岩石中。常与霞石 <br>、霓石、碱性长石、钾长石、黑榴石、星叶石、钠锆石、负异性石及富铁黑云母等矿物共生。</p>\n<p>霓辉石镜下特殊现象：</p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497061055.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/879_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n\n        ","sourceFullDescriptionText":"描述\n            \n霓辉石：二轴晶辉石类矿物【颜色】薄片中绿色或则浅黄色，多色性明显Ng-黄，浅褐Nm-黄或绿色Np-橄榄绿或草绿色颜色常呈环带分布，一般是外环颜色较深，因其霓石含量较高些，而核心近于无色的透辉石或普通辉石成分，但也有相反的 环带。【突起 (查看突起测定方法)】正高突起，折射率随着霓石分子的增加而增大【干涉色】最高干涉色可达三级蓝绿【消光 (查看消光测定方法)】横切面上对于解理 (查看解理测定方法)缝呈对称消光，纵切面呈斜消光。【延性 (查看延性测定方法)】负延性【双晶】双晶沿{100}常见。简单双晶或聚片双晶。【次生变化】常变为绿泥石，绿帘石、褐帘石、赤铁矿、褐铁矿。【鉴定特征】霓辉石与普通辉石、透辉石的区别是霓辉石呈特有的绿色，多色性明显和负延性，在纵切面上的消光角Ng^C比 后者大。与霓辉石和普通角闪石的区别在于前者的突起、干涉色均较后者高，负延性和辉石式解理。【产状】是碱性岩浆岩晚期结晶产物。主要产于碱性岩石如：正长岩、碱性粗面岩、霞石正长岩、响岩等岩石中。常与霞石 、霓石、碱性长石、钾长石、黑榴石、星叶石、钠锆石、负异性石及富铁黑云母等矿物共生。\n霓辉石镜下特殊现象：","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"880":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：斜黝帘石</td>\n                        <td>英文名：Clinozoisite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：Ca<sub>2</sub>AlAl<sub>2</sub>[SiO<sub>4</sub>][Si<sub>2</sub>O<sub>7</sub>]O[OH]</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=656\" target=\"_blank\" rel=\"noopener noreferrer\">绿帘石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>斜黝帘石：二轴晶绿帘石类矿物<br>【颜色】薄片中无色，含Fe3+者可稍具有多色性，从浅黄色至橙黄色。<br>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正高突起<br>【干涉色】常为一级灰、以及浅灰白色、且往往有靛青蓝异常干涉色。由于双折射率的变化，晶体上可以显示环带。<br>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】沿b轴方向为平行消光、其他切面均为斜消光。<br>【延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)】可正可负<br>【双晶】有沿{100}的聚片双晶<br>【次生变化】很稳定，不易发生变化<br>【鉴定特征】与黝帘石相似，其区别在于黝帘石为平行消光，光轴角较小，而斜黝帘石为斜消光，光轴角很大。与绿帘石的区别为，斜黝帘石无多色性，靛蓝色异常干涉色，二轴晶（+），而绿帘石有多色性，具有鲜艳的异常干涉色，二轴晶（-）<br>【产状】为分布很广的岩浆岩后期矿物，常与绿帘石，次闪石及绢云母等共生。也产于结晶片岩、片麻岩及接触变质岩中。</p>\n<p>单偏光镜下照片：</p>\n<p> <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497062459.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/880_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p>靛蓝色异常干涉色：</p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497062461.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/880_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n\n        ","sourceFullDescriptionText":"描述\n            \n斜黝帘石：二轴晶绿帘石类矿物【颜色】薄片中无色，含Fe3+者可稍具有多色性，从浅黄色至橙黄色。【突起 (查看突起测定方法)】正高突起【干涉色】常为一级灰、以及浅灰白色、且往往有靛青蓝异常干涉色。由于双折射率的变化，晶体上可以显示环带。【消光 (查看消光测定方法)】沿b轴方向为平行消光、其他切面均为斜消光。【延性 (查看延性测定方法)】可正可负【双晶】有沿{100}的聚片双晶【次生变化】很稳定，不易发生变化【鉴定特征】与黝帘石相似，其区别在于黝帘石为平行消光，光轴角较小，而斜黝帘石为斜消光，光轴角很大。与绿帘石的区别为，斜黝帘石无多色性，靛蓝色异常干涉色，二轴晶（+），而绿帘石有多色性，具有鲜艳的异常干涉色，二轴晶（-）【产状】为分布很广的岩浆岩后期矿物，常与绿帘石，次闪石及绢云母等共生。也产于结晶片岩、片麻岩及接触变质岩中。\n单偏光镜下照片：\n \n靛蓝色异常干涉色：","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"881":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：霓石</td>\n                        <td>英文名：Aegirine</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：NaFe<sup>3+</sup>[Si<sub>2</sub>O<sub>6</sub>]</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=654\" target=\"_blank\" rel=\"noopener noreferrer\">辉石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>霓石：二轴晶辉石类单斜辉石亚类矿物<br>【颜色】薄片中淡绿、暗绿及黄绿色。多色性强<br>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正极高突起，糙面明显。<br>【干涉色】三至四级，常被本身颜色掩盖<br>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】（010）面上斜消光，消光角极小，横切面上对称消光，（100）面上平行消光<br>【延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)】负延性<br>【次生变化】可变为褐铁矿，也可发生次闪石化<br>【鉴定特征】你是以其特殊的多色性、负光性、近于平行消光与其他辉石区别。与霓辉石区别是消光角更小，多色性更强。霓石与普通辉石的区别是横切面上解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)夹角不同。你是折射率、干涉色高于普通角闪石，且霓石消光角小，近于平行消光，负延性。<br>【产状】霓石是碱性岩的特征矿物，与钠铁闪石、黑榴石、星叶石、霞石、负异性石、钾长石等矿物共生。也出现于碱性伟晶岩，碱性岩与围岩接触带中和某些富含Na、Fe的金属矿床的气化高温蚀变带中，在麻粒岩中也可发现。</p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1493869224.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/881_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n        ","sourceFullDescriptionText":"描述\n            \n霓石：二轴晶辉石类单斜辉石亚类矿物【颜色】薄片中淡绿、暗绿及黄绿色。多色性强【突起 (查看突起测定方法)】正极高突起，糙面明显。【干涉色】三至四级，常被本身颜色掩盖【消光 (查看消光测定方法)】（010）面上斜消光，消光角极小，横切面上对称消光，（100）面上平行消光【延性 (查看延性测定方法)】负延性【次生变化】可变为褐铁矿，也可发生次闪石化【鉴定特征】你是以其特殊的多色性、负光性、近于平行消光与其他辉石区别。与霓辉石区别是消光角更小，多色性更强。霓石与普通辉石的区别是横切面上解理 (查看解理测定方法)夹角不同。你是折射率、干涉色高于普通角闪石，且霓石消光角小，近于平行消光，负延性。【产状】霓石是碱性岩的特征矿物，与钠铁闪石、黑榴石、星叶石、霞石、负异性石、钾长石等矿物共生。也出现于碱性伟晶岩，碱性岩与围岩接触带中和某些富含Na、Fe的金属矿床的气化高温蚀变带中，在麻粒岩中也可发现。","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"884":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：蛇纹石</td>\n                        <td>英文名：Serpentine</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式： Mg<sub>6</sub>[Si<sub>4</sub>O<sub>10</sub>](OH)<sub>2</sub></td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=649\" target=\"_blank\" rel=\"noopener noreferrer\">蛇纹石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>蛇纹石：二轴晶蛇纹石类矿物<br>【颜色】薄片中无色至淡绿色，含Fe多的有色变种可有多色性。<br>【干涉色】最高达一级淡黄，但常见为一级灰<br>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】平行消光<br>【延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)】正延性<br>【次生变化】可变为镁质斜绿泥石<br>【鉴定特征】与纤维蛇纹石的区别：在于纤维蛇纹石呈更长纤维状集合体，其突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)可正可负；与水镁石的区别：水镁石是一轴晶，有较高的折射率，螺旋状构造，及异常干涉色。<br>【变种】绢石—为呈斜方辉石假象的叶蛇纹石，常沿斜方辉石的边部细缝或解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)发育而成。绢石的特征似白云母，无色，片状，但干涉色多为一级灰白到浅黄，平行消光，负延性。<br>【产状】在Mg质基性、超基性岩中分布最广，是蛇纹岩的主要成分。为镁硅酸盐蚀变的产物，常同纤维蛇纹石一起，有时亦同化石，蛭石、绿泥石及铬铁矿共生。</p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1493871898.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/884_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n\n        ","sourceFullDescriptionText":"描述\n            \n蛇纹石：二轴晶蛇纹石类矿物【颜色】薄片中无色至淡绿色，含Fe多的有色变种可有多色性。【干涉色】最高达一级淡黄，但常见为一级灰【消光 (查看消光测定方法)】平行消光【延性 (查看延性测定方法)】正延性【次生变化】可变为镁质斜绿泥石【鉴定特征】与纤维蛇纹石的区别：在于纤维蛇纹石呈更长纤维状集合体，其突起 (查看突起测定方法)可正可负；与水镁石的区别：水镁石是一轴晶，有较高的折射率，螺旋状构造，及异常干涉色。【变种】绢石—为呈斜方辉石假象的叶蛇纹石，常沿斜方辉石的边部细缝或解理 (查看解理测定方法)发育而成。绢石的特征似白云母，无色，片状，但干涉色多为一级灰白到浅黄，平行消光，负延性。【产状】在Mg质基性、超基性岩中分布最广，是蛇纹岩的主要成分。为镁硅酸盐蚀变的产物，常同纤维蛇纹石一起，有时亦同化石，蛭石、绿泥石及铬铁矿共生。","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"885":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：钙沸石</td>\n                        <td>英文名：Scolecite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：Ca[Al<sub>2</sub>Si<sub>3</sub>O<sub>10</sub>]·3H<sub>2</sub>O</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=645\" target=\"_blank\" rel=\"noopener noreferrer\">沸石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>钙沸石：二轴晶沸石类矿物<br>【颜色】薄片中无色<br>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】负极低突起<br>【解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)】{110}解理完全<br>【干涉色】最高一级灰白<br>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】斜消光<br>【延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)】负延性<br>【双晶】常见以C轴为双晶，（100）为双晶面的双晶<br>【鉴定特征】钙沸石具斜消光、负延性，以此区分开于杆沸石和钠沸石的平行消光和正延性。<br>【产状】产于喷出岩的气孔和裂隙中。</p>\n<p>钙沸石单偏光镜下照片：</p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1493874518.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/885_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n        ","sourceFullDescriptionText":"描述\n            \n钙沸石：二轴晶沸石类矿物【颜色】薄片中无色【突起 (查看突起测定方法)】负极低突起【解理 (查看解理测定方法)】{110}解理完全【干涉色】最高一级灰白【消光 (查看消光测定方法)】斜消光【延性 (查看延性测定方法)】负延性【双晶】常见以C轴为双晶，（100）为双晶面的双晶【鉴定特征】钙沸石具斜消光、负延性，以此区分开于杆沸石和钠沸石的平行消光和正延性。【产状】产于喷出岩的气孔和裂隙中。\n钙沸石单偏光镜下照片：","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"886":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：透辉石</td>\n                        <td>英文名：Diopside</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：CaMg[Si<sub>2</sub>O<sub>6</sub>]</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=654\" target=\"_blank\" rel=\"noopener noreferrer\">辉石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>透辉石：二轴晶辉石类矿物<br>【形态】晶体常呈轴面较发育的短轴状，集合体呈粒状或者放射状<br>【颜色】薄片中呈无色，<br>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正高突起，折射率与成分关系密切<br>【解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)】辉石式完全解理<br>【干涉色】最高干涉色达二级<br>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】横切面上对于解理缝为对称消光，纵切面为斜消光<br>【延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)】正延性<br>【双晶】{100}或者{001}简单双晶或者聚片双晶比较常见<br>【次生变化】蚀变为蛇纹石、滑石、角闪石、绿泥石及碳酸盐等矿物<br>【鉴定特征】无色、斜消光、具辉石式解理，最大消光角常小于40°<br>【产状】常见于各种成分的岩浆岩，尤其以超基性及基性岩浆岩中最为普遍。透辉石又是一种常见的接触变质矿物，在矽卡岩中与石榴石、符山石、硅灰石等共生，片麻岩和结晶片岩内也有分布</p>\n<p>透辉石单偏光下照片：</p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1494302104.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/886_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n<p>透辉石镜下特殊现象照片：</p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1494302106.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/886_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1494302108.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/886_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n\n        ","sourceFullDescriptionText":"描述\n            \n透辉石：二轴晶辉石类矿物【形态】晶体常呈轴面较发育的短轴状，集合体呈粒状或者放射状【颜色】薄片中呈无色，【突起 (查看突起测定方法)】正高突起，折射率与成分关系密切【解理 (查看解理测定方法)】辉石式完全解理【干涉色】最高干涉色达二级【消光 (查看消光测定方法)】横切面上对于解理缝为对称消光，纵切面为斜消光【延性 (查看延性测定方法)】正延性【双晶】{100}或者{001}简单双晶或者聚片双晶比较常见【次生变化】蚀变为蛇纹石、滑石、角闪石、绿泥石及碳酸盐等矿物【鉴定特征】无色、斜消光、具辉石式解理，最大消光角常小于40°【产状】常见于各种成分的岩浆岩，尤其以超基性及基性岩浆岩中最为普遍。透辉石又是一种常见的接触变质矿物，在矽卡岩中与石榴石、符山石、硅灰石等共生，片麻岩和结晶片岩内也有分布\n透辉石单偏光下照片：\n\n\n\n透辉石镜下特殊现象照片：","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"887":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：石膏</td>\n                        <td>英文名：Gypsum</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：CaSO<sub>4</sub>·2H<sub>2</sub>O </td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=646\" target=\"_blank\" rel=\"noopener noreferrer\">粘土矿物类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>石膏：二轴晶矿物<br>【颜色】薄片中无色<br>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】负低突起<br>【干涉色】最高一级淡黄<br>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】⊥(010)晶带为平行消光或对称消光，但沿{010}解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)为斜消光<br>【双晶】常见{100}燕尾双晶，也可见聚片双晶<br>【鉴定特征】负低突起，斜消光，聚片双晶及产状<br>与硬石膏区别：硬石膏为正突起，干涉色高达三级<br>【产状】产于蒸发岩中，有时呈单矿物出现，但往往与硬石膏共生，是硬石膏水化后的产物。</p>\n<p>石膏单偏光镜下照片：</p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1494306489.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/887_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n        ","sourceFullDescriptionText":"描述\n            \n石膏：二轴晶矿物【颜色】薄片中无色【突起 (查看突起测定方法)】负低突起【干涉色】最高一级淡黄【消光 (查看消光测定方法)】⊥(010)晶带为平行消光或对称消光，但沿{010}解理 (查看解理测定方法)为斜消光【双晶】常见{100}燕尾双晶，也可见聚片双晶【鉴定特征】负低突起，斜消光，聚片双晶及产状与硬石膏区别：硬石膏为正突起，干涉色高达三级【产状】产于蒸发岩中，有时呈单矿物出现，但往往与硬石膏共生，是硬石膏水化后的产物。\n石膏单偏光镜下照片：","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"888":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：硬石膏</td>\n                        <td>英文名：Anhydrite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式： CaSO<sub>4</sub></td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=650\" target=\"_blank\" rel=\"noopener noreferrer\">绿泥石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>硬石膏：二轴晶绿泥石类矿物<br>【颜色】薄片中无色。碎屑颗粒呈浅粉红色或浅蓝色<br>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正低——正中突起<br>【干涉色】最高可达三级绿<br>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】平行消光<br>【延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)】可正可负<br>【双晶】常见{101}简单双晶，有时有聚片双晶及三连晶<br>【次生变化】水化后变为石膏<br>【鉴定特征】硬石膏和石膏的区别在于前者为正突起，后者为负突起；其次，硬石膏的双折射率远比石膏要高，并且具有三组相互正交的解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)<br>【产状】<br>（1）产于热液矿床和接触交代矿床或火山岩的空隙中<br>（2）外生条件下硬石膏常见于石膏和岩盐矿层中，出露地表为石膏。</p>\n<p>硬石膏镜下特殊现象照片：</p>\n<div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1494307116.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/888_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1494307118.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/888_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n\n        ","sourceFullDescriptionText":"描述\n            \n硬石膏：二轴晶绿泥石类矿物【颜色】薄片中无色。碎屑颗粒呈浅粉红色或浅蓝色【突起 (查看突起测定方法)】正低——正中突起【干涉色】最高可达三级绿【消光 (查看消光测定方法)】平行消光【延性 (查看延性测定方法)】可正可负【双晶】常见{101}简单双晶，有时有聚片双晶及三连晶【次生变化】水化后变为石膏【鉴定特征】硬石膏和石膏的区别在于前者为正突起，后者为负突起；其次，硬石膏的双折射率远比石膏要高，并且具有三组相互正交的解理 (查看解理测定方法)【产状】（1）产于热液矿床和接触交代矿床或火山岩的空隙中（2）外生条件下硬石膏常见于石膏和岩盐矿层中，出露地表为石膏。\n硬石膏镜下特殊现象照片：","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"889":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：滑石</td>\n                        <td>英文名：Talc</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：Mg<sub>3</sub>[Si<sub>4</sub>O<sub>10</sub>](OH)<sub>2 </sub></td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=637\" target=\"_blank\" rel=\"noopener noreferrer\">二轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=650\" target=\"_blank\" rel=\"noopener noreferrer\">绿泥石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>滑石：二轴晶绿泥石类矿物<br>【颜色】薄片中无色。铁滑石微带淡绿色<br>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正低突起<br>【干涉色】最高干涉色达二级，很像白云母干涉色。<br>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】多数平行消光，少数斜消光，但消光角极小<br>【延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)】正延性<br>【次生变化】可变为镁质斜绿泥石。当CaO和CO2大量存在时，滑石可被菱镁矿代替。<br>【产状】滑石为富镁变质矿物，通常产于浅变质的结晶片岩。滑石也是镁质超基性岩的蚀变矿物。</p>\n<p>滑石镜下特殊现象照片：</p>\n<div>\n<div>\n<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1494307627.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/889_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><p> </p>\n</div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1494307630.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/889_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n<div><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1494307632.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/889_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></div>\n</div>\n\n        ","sourceFullDescriptionText":"描述\n            \n滑石：二轴晶绿泥石类矿物【颜色】薄片中无色。铁滑石微带淡绿色【突起 (查看突起测定方法)】正低突起【干涉色】最高干涉色达二级，很像白云母干涉色。【消光 (查看消光测定方法)】多数平行消光，少数斜消光，但消光角极小【延性 (查看延性测定方法)】正延性【次生变化】可变为镁质斜绿泥石。当CaO和CO2大量存在时，滑石可被菱镁矿代替。【产状】滑石为富镁变质矿物，通常产于浅变质的结晶片岩。滑石也是镁质超基性岩的蚀变矿物。\n滑石镜下特殊现象照片：","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"890":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：方钠石</td>\n                        <td>英文名：Sodalite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：Na<sub>8</sub>[AlSiO<sub>4</sub>]<sub>6</sub>Cl<sub>2</sub></td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=6\" target=\"_blank\" rel=\"noopener noreferrer\">均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=570\" target=\"_blank\" rel=\"noopener noreferrer\">方钠石类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>方钠石：均质矿物方钠石类</p>\n<p>【颜色】薄片中无色，有时呈现浅黄色或淡青色</p>\n<p>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】负低突起</p>\n<p>【干涉色】全消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)</p>\n<p>【双晶】偶见{111}的尖晶石律双晶</p>\n<p>【次生变化】风化时易变为钠沸石、绢云母、水铝石等，也可变成钙霞石、石榴石、方解石及褐铁矿</p>\n<p>【鉴定特征】方钠石易于白榴石混淆，其区别在于白榴石常包含包裹体，无解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)，常有聚片双晶，二方钠石一般无包裹体，具有解理，不出现聚片双晶。</p>\n<p>【产状】产于碱性岩中，少见。常与霞石共生。</p>\n<p>单偏光镜下照片：</p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497064268.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/890_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p>正交偏光下镜下照片：</p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497064270.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/890_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n        ","sourceFullDescriptionText":"描述\n            \n方钠石：均质矿物方钠石类\n【颜色】薄片中无色，有时呈现浅黄色或淡青色\n【突起 (查看突起测定方法)】负低突起\n【干涉色】全消光 (查看消光测定方法)\n【双晶】偶见{111}的尖晶石律双晶\n【次生变化】风化时易变为钠沸石、绢云母、水铝石等，也可变成钙霞石、石榴石、方解石及褐铁矿\n【鉴定特征】方钠石易于白榴石混淆，其区别在于白榴石常包含包裹体，无解理 (查看解理测定方法)，常有聚片双晶，二方钠石一般无包裹体，具有解理，不出现聚片双晶。\n【产状】产于碱性岩中，少见。常与霞石共生。\n单偏光镜下照片：\n\n正交偏光下镜下照片：","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"891":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：绿柱石</td>\n                        <td>英文名：Beryl</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">晶体化学式：Be<sub>3</sub>Al<sub>2</sub>[Si<sub>6</sub>O<sub>18</sub>]</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=7\" target=\"_blank\" rel=\"noopener noreferrer\">非均质矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=636\" target=\"_blank\" rel=\"noopener noreferrer\">一轴晶矿物</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=642\" target=\"_blank\" rel=\"noopener noreferrer\">石英类</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p>绿柱石：一轴晶环状结构硅酸盐亚类矿物</p>\n<p>【颜色】薄片中无色，极少数情况会出现淡黄或淡绿色</p>\n<p>【突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)】正中突起</p>\n<p>【干涉色】最高为一级黄，一般为一级灰白色</p>\n<p>【消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)】平行消光</p>\n<p>【延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)】负延性</p>\n<p>【光性异常】具有环带构造者，在环带边缘部分有的具有异常光性，为二轴晶。（-）2V=0-6°，光轴角可达10-17°</p>\n<p>【次生变化】绿柱石可蚀变为高岭石，也会被白云母或则硅铍石代换</p>\n<p>【鉴定特征】以晶形、光泽、突起、延性、轴性及光性为主要特征，绿柱石与石英易混淆，区别在于延性和光性不同，石英为正延性，正光性，绿柱石为负延性，负光性。绿柱石与磷灰石的区别在于后者突起较高，硬度较小，且可溶于酸。</p>\n<p>【产状】主要产于花岗伟晶岩及其围岩中，与锂辉石、锂云母、铌钽铁矿、电气石、叶钠长石等矿物共生。在云英岩、矽卡岩中与黄玉共生。花岗岩、片麻岩、云母片岩及大理岩内也有绿柱石产出</p>\n<p>单偏光下绿柱石镜下照片:</p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1497069517.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/891_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p> </p>\n\n        ","sourceFullDescriptionText":"描述\n            \n绿柱石：一轴晶环状结构硅酸盐亚类矿物\n【颜色】薄片中无色，极少数情况会出现淡黄或淡绿色\n【突起 (查看突起测定方法)】正中突起\n【干涉色】最高为一级黄，一般为一级灰白色\n【消光 (查看消光测定方法)】平行消光\n【延性 (查看延性测定方法)】负延性\n【光性异常】具有环带构造者，在环带边缘部分有的具有异常光性，为二轴晶。（-）2V=0-6°，光轴角可达10-17°\n【次生变化】绿柱石可蚀变为高岭石，也会被白云母或则硅铍石代换\n【鉴定特征】以晶形、光泽、突起、延性、轴性及光性为主要特征，绿柱石与石英易混淆，区别在于延性和光性不同，石英为正延性，正光性，绿柱石为负延性，负光性。绿柱石与磷灰石的区别在于后者突起较高，硬度较小，且可溶于酸。\n【产状】主要产于花岗伟晶岩及其围岩中，与锂辉石、锂云母、铌钽铁矿、电气石、叶钠长石等矿物共生。在云英岩、矽卡岩中与黄玉共生。花岗岩、片麻岩、云母片岩及大理岩内也有绿柱石产出\n单偏光下绿柱石镜下照片:","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"892":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：纯橄榄岩</td>\n                        <td>英文名：dunite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=4\" target=\"_blank\" rel=\"noopener noreferrer\">岩石标本</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=160\" target=\"_blank\" rel=\"noopener noreferrer\">岩浆岩</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=161\" target=\"_blank\" rel=\"noopener noreferrer\">超基性岩</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：Ia10.1</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p><strong>纯橄岩内容概述：</strong></p>\n<p>       纯橄岩属于超基性侵入岩，属硅酸不饱和的钙碱性系列岩石。纯橄岩化学成分的总的特征是贫硅（SiO<sub>2</sub> ＜45％、贫碱、富镁铁）。反应在矿物成分上则体现为几乎完全由铁镁矿物组成，镁铁质矿物主要有橄榄石、辉石，次要矿物主要为角闪石、黑云母、偶见斜长石，副矿物主要为尖晶石类、铬铁矿、钛铁矿、磷灰石以及磁铁矿。</p>\n<p>本类岩石分布极少，约占岩浆岩分布面积的0.4％，其对应喷出岩（金伯利岩）更为罕见，且岩石新鲜者不多，总是不同程度的遭受蛇纹石化的蚀变。</p>\n<p><strong>纯橄岩薄片镜下鉴定：</strong></p>\n<p>【<strong>主要矿物</strong>】</p>\n<p>       镜下可见主要矿物为橄榄石，其中橄榄石含量大约为90％；次要矿物主要有单斜辉石、斜方辉石，有时也可见棕色角闪石。岩石具自形-半自形细粒粒状结构（见图1），网状结构（见图2）。局部可见橄榄石发生滑石化（见图3）、蛇纹石化（见图2）。</p>\n<p>橄榄石（90%）：主要为镁橄榄石和贵橄榄石，无色。单偏光镜下一般为半自形--自形粒状，正高突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)。两组不完全解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)，干涉色达二级顶部。可以包裹磁铁矿、铬铁矿、尖晶石，或出溶作用形成的针状、板状铁质矿物。橄榄石易蛇纹石化，滑石化、纤闪石化。在橄榄石外围常见斜方辉石、单斜辉石甚至棕色角闪石组成的反应边结构。</p>\n<p>【<strong>次要矿物</strong>】</p>\n<ol>\n<li>斜方辉石（3%）：通常为紫苏辉石、顽火辉石、古铜辉石。它们与单斜辉石的区别是其干涉色低（一级），平行消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)。（紫苏辉石有时斜消光，但消光角不超过35°）。在斜方辉石中可见出溶的单斜辉石呈条纹状交生。可发生绿泥石化、碳酸盐化、纤闪石化。</li>\n<li>单斜辉石（2%）：主要为普通辉石、透辉石及变种异剥辉石等富钙辉石。单斜辉石在镜下多呈无色或浅色，短柱状。正高突起。辉石式解理。斜消光，消光角一般&gt;35°。二级干涉色。常见简单双晶、反应边结构、与斜方辉石等组成的交生结构和席勒构造。可发生绿泥石化、碳酸盐化、纤闪石化。</li>\n<li>黑云母（2%）：单偏光镜下通常呈棕色色调，多色性明显，片状矿物。正中突起。干涉色可达二级橙。有时包裹磁铁矿，在氧逸度变化时呈反应矿物产出。</li>\n</ol>\n<p>【<strong>副矿物</strong>】副矿物主要可见尖晶石、铬铁矿、钛铁矿、磁铁矿、磷灰石，但含量一般不超过3％。</p>\n<p>【<strong>次生变化</strong>】橄榄石多发生滑石化、蛇纹石化，纤闪石化；辉石多发生绿泥石化、碳酸盐化、纤闪石化。</p>\n<p>滑石化：镁质超基性岩蚀变为滑石的次生变化（见图3）；蛇纹石化：蛇纹石化是超基性岩中的一种后期自变质产物，或中、低温热液对含镁的岩石进行交代产生含蛇纹石的一种蚀变作用，蚀变过程中H<sub>2</sub>O起着重要作用。</p>\n<p>【<strong>结构构造</strong>】纯橄岩中常见自形-半自形粒状结构、包含结构、填隙结构、网状结构、反应边结构、海绵陨铁结构等。</p>\n<p>       网状结构：橄榄石遭受蛇纹石化的次生结构。其特征是蛇纹石构成网状，网孔中保留着残余的橄榄石。如果临近的若干块残余橄榄石同时消光，则表明原来是同一个颗粒（见图2）。</p>\n<p>包含结构:泛指岩石中大晶体包含小晶体的一类结构，其中大的称为主晶，小的或被包裹的称为客晶。</p>\n<p>       反应边结构：早期析出的矿物由于结晶条件的改变与周围尚未凝固的岩浆发生的反应，在其外围形成新的矿物。如橄榄石晶体与岩浆发生反应后呈圆形或卵圆形，被大的辉石、角闪石晶体包裹，形成的包橄结构，即为反应边结构的一种。</p>\n<p>详细定名：纯橄岩</p>\n<p> <img src=\"img/pic/892_0.jpg\" alt=\"自形-半自形细粒粒状结构\" loading=\"lazy\" decoding=\"async\"><img src=\"img/pic/892_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></p>\n<p>                                 <strong>   </strong></p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p><strong>                                   图1a 单偏光下自形-半自形细粒粒状结构                                                                                              图1b 正交偏光下自形-半自形细粒粒状结</strong></p>\n<p><img src=\"img/pic/892_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"><img src=\"img/pic/892_3.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></p>\n<p>                                        <strong>         </strong></p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p><strong> </strong></p>\n<p><strong>                                                       图2a 单偏光下网状结构                                                                                                                  图2b 正交偏光下网状结构</strong></p>\n<p><strong><strong><img src=\"img/pic/892_4.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></strong></strong><img src=\"img/pic/892_5.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></p>\n<p>                           <strong><strong>  </strong></strong></p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p><strong><strong>                            图3a 单偏光下镁质超基性岩蚀变为滑石的次生变化                                                                           图3b 正交偏光下镁质超基性岩蚀变为滑石的次生变化</strong></strong></p>\n\n        ","sourceFullDescriptionText":"描述\n            \n纯橄岩内容概述：\n       纯橄岩属于超基性侵入岩，属硅酸不饱和的钙碱性系列岩石。纯橄岩化学成分的总的特征是贫硅（SiO2 ＜45％、贫碱、富镁铁）。反应在矿物成分上则体现为几乎完全由铁镁矿物组成，镁铁质矿物主要有橄榄石、辉石，次要矿物主要为角闪石、黑云母、偶见斜长石，副矿物主要为尖晶石类、铬铁矿、钛铁矿、磷灰石以及磁铁矿。\n本类岩石分布极少，约占岩浆岩分布面积的0.4％，其对应喷出岩（金伯利岩）更为罕见，且岩石新鲜者不多，总是不同程度的遭受蛇纹石化的蚀变。\n纯橄岩薄片镜下鉴定：\n【主要矿物】\n       镜下可见主要矿物为橄榄石，其中橄榄石含量大约为90％；次要矿物主要有单斜辉石、斜方辉石，有时也可见棕色角闪石。岩石具自形-半自形细粒粒状结构（见图1），网状结构（见图2）。局部可见橄榄石发生滑石化（见图3）、蛇纹石化（见图2）。\n橄榄石（90%）：主要为镁橄榄石和贵橄榄石，无色。单偏光镜下一般为半自形--自形粒状，正高突起 (查看突起测定方法)。两组不完全解理 (查看解理测定方法)，干涉色达二级顶部。可以包裹磁铁矿、铬铁矿、尖晶石，或出溶作用形成的针状、板状铁质矿物。橄榄石易蛇纹石化，滑石化、纤闪石化。在橄榄石外围常见斜方辉石、单斜辉石甚至棕色角闪石组成的反应边结构。\n【次要矿物】\n\n斜方辉石（3%）：通常为紫苏辉石、顽火辉石、古铜辉石。它们与单斜辉石的区别是其干涉色低（一级），平行消光 (查看消光测定方法)。（紫苏辉石有时斜消光，但消光角不超过35°）。在斜方辉石中可见出溶的单斜辉石呈条纹状交生。可发生绿泥石化、碳酸盐化、纤闪石化。\n单斜辉石（2%）：主要为普通辉石、透辉石及变种异剥辉石等富钙辉石。单斜辉石在镜下多呈无色或浅色，短柱状。正高突起。辉石式解理。斜消光，消光角一般>35°。二级干涉色。常见简单双晶、反应边结构、与斜方辉石等组成的交生结构和席勒构造。可发生绿泥石化、碳酸盐化、纤闪石化。\n黑云母（2%）：单偏光镜下通常呈棕色色调，多色性明显，片状矿物。正中突起。干涉色可达二级橙。有时包裹磁铁矿，在氧逸度变化时呈反应矿物产出。\n\n【副矿物】副矿物主要可见尖晶石、铬铁矿、钛铁矿、磁铁矿、磷灰石，但含量一般不超过3％。\n【次生变化】橄榄石多发生滑石化、蛇纹石化，纤闪石化；辉石多发生绿泥石化、碳酸盐化、纤闪石化。\n滑石化：镁质超基性岩蚀变为滑石的次生变化（见图3）；蛇纹石化：蛇纹石化是超基性岩中的一种后期自变质产物，或中、低温热液对含镁的岩石进行交代产生含蛇纹石的一种蚀变作用，蚀变过程中H2O起着重要作用。\n【结构构造】纯橄岩中常见自形-半自形粒状结构、包含结构、填隙结构、网状结构、反应边结构、海绵陨铁结构等。\n       网状结构：橄榄石遭受蛇纹石化的次生结构。其特征是蛇纹石构成网状，网孔中保留着残余的橄榄石。如果临近的若干块残余橄榄石同时消光，则表明原来是同一个颗粒（见图2）。\n包含结构:泛指岩石中大晶体包含小晶体的一类结构，其中大的称为主晶，小的或被包裹的称为客晶。\n       反应边结构：早期析出的矿物由于结晶条件的改变与周围尚未凝固的岩浆发生的反应，在其外围形成新的矿物。如橄榄石晶体与岩浆发生反应后呈圆形或卵圆形，被大的辉石、角闪石晶体包裹，形成的包橄结构，即为反应边结构的一种。\n详细定名：纯橄岩\n \n                                    \n \n \n \n \n \n \n                                   图1a 单偏光下自形-半自形细粒粒状结构                                                                                              图1b 正交偏光下自形-半自形细粒粒状结\n\n                                                 \n \n \n \n \n \n \n                                                       图2a 单偏光下网状结构                                                                                                                  图2b 正交偏光下网状结构\n\n                             \n \n \n \n \n \n \n \n \n                            图3a 单偏光下镁质超基性岩蚀变为滑石的次生变化                                                                           图3b 正交偏光下镁质超基性岩蚀变为滑石的次生变化","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"893":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：辉石橄榄岩</td>\n                        <td>英文名：Pyroxene peridotite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=4\" target=\"_blank\" rel=\"noopener noreferrer\">岩石标本</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=160\" target=\"_blank\" rel=\"noopener noreferrer\">岩浆岩</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=161\" target=\"_blank\" rel=\"noopener noreferrer\">超基性岩</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：Ia10.2</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p><strong>辉石橄榄岩概述：</strong></p>\n<p>       辉石橄榄岩属于超基性侵入岩，属硅酸不饱和的钙碱性系列岩石。化学成分的总的特征是贫硅（SiO2 ＜45％、贫碱、富镁铁）。反映在化学成分上，岩石几乎完全由铁镁矿物组成，主要是橄榄石、辉石，次要矿物主要为角闪石、黑云母、偶见斜长石，副矿物主要为尖晶石类、铬铁矿、钛铁矿、磷灰石以及磁铁矿。与纯橄岩相比，差别主要在于辉石橄榄岩的橄榄石含量（40％-90％）低于纯橄榄的橄榄石含量（＞90％）。本类岩石分布极少，约占岩浆岩分布面积的0.4％，其中喷出岩更为罕见，本类岩石新鲜者不多，主要矿物及次要矿物（橄榄石、辉石等）总是不同程度的遭受蛇纹石化的蚀变。</p>\n<p><strong>辉石橄榄岩薄片镜下鉴定：</strong></p>\n<p>        镜下矿物主要为橄榄石，橄榄石含量在40％-90％；次要矿物主要有斜方辉石、单斜辉石，有时可见少量角闪石、黑云母、铬铁矿等，每种辉石含量都大于5％，但两者相加不超过60％。岩石具中-粗粒粒状结构，也可见包橄结构（见图1、2）、网状结构（见图4、5）、填隙结构（见图3），海绵陨铁结构等。</p>\n<p><strong>【主要矿物】</strong></p>\n<p>       橄榄石（40％-90%）：主要为贵橄榄石，无色。一般为半自形--自形粒状，正高突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)。两组不完全解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)。干涉色可达二级顶部。可以包裹磁铁矿、铬铁矿、尖晶石，或出溶作用形成的针状、板状铁质矿物。橄榄石易发生蛇纹石化，在橄榄石外围常见斜方辉石、单斜辉石甚至棕色角闪石组成反应边结构。</p>\n<p><strong>【次要矿物】</strong></p>\n<ol>\n<li>斜方辉石（10-5%）：通常为紫苏辉石、顽火辉石、古铜辉石。它们与单斜辉石的区别是其干涉色低（一级），多为平行消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)。（紫苏辉石有时斜消光，但消光角不超过35°）。在斜方辉石中可见出溶的单斜辉石呈条纹、似文象交生。</li>\n<li>单斜辉石（30-35%）：主要为普通辉石、透辉石及变种异剥辉石等富钙辉石。单斜辉石镜下多呈无色或浅色，短柱状。正高突起。辉石式解理。斜消光，消光角一般&gt;35°。二级干涉色。常见简单双晶、反应边结构、与斜方辉石等组成的交生结构和席勒构造。可发生绿泥石化、碳酸盐化、纤闪石化。</li>\n</ol>\n<p>【<strong>副矿物</strong>】主要为磁铁矿、磷灰石、榍石、尖晶石。总含量不超过2%。</p>\n<p>【<strong>次生变化</strong>】橄榄石多发生蛇纹石化、滑石化、碳酸盐化等。</p>\n<p>       蛇纹石化：蛇纹石化是超基性岩中的一种后期自变质产物，或中、低温热液对含镁的岩石进行交代产生含蛇纹石的一种蚀变作用，蚀变过程中H2O起着重要作用；滑石化：镁质超基性岩蚀变为滑石的次生变化；      </p>\n<p>        碳酸盐化：岩石遭受热液（中、低温热液为主）蚀变后，产生相当数量的碳酸盐矿物，如方解石、菱铁矿、铁白云石、白云石及菱镁矿等的作用。大多数岩石都能发生碳酸盐化。</p>\n<p><strong>【结构构造】</strong>辉石橄榄岩与纯橄岩同属超基性岩类，岩石中常见的结构有粒状镶嵌结构、包橄结构、网状结构、填隙结构等。</p>\n<p>       粒状镶嵌结构：超基性岩中常见的结构。粒状矿物（如橄榄石）近似等轴，彼此呈直线镶嵌接触。</p>\n<p>       包橄结构：包含结构的一种，泛指岩石中大晶体包含小晶体的一种结构。根据包裹和被包裹的关系可分为主晶和客晶。主晶指大的包裹矿物，客晶指小的被包裹矿物。这种结构说明：客晶矿物形成早于主晶矿物。主晶常有熔蚀和交代早期客晶的现象。例如，在超基性岩中常见到大的辉石晶体包裹小的圆形的橄榄石晶体，即是包橄结构（见图1、2）。                                 </p>\n<p>       网状结构：橄榄石遭受蛇纹石化的次生结构。其特征是蛇纹石构成网状，网孔中保留着残余的橄榄石。如果临近的若干块残余橄榄石同时消光，则表明原来是同一个颗粒（见图4、5）。</p>\n<p>       填隙结构：在斜长石微晶所组成的间隙内，充填有辉石等暗色矿物，以及隐晶质、玻璃质等。有时也把填隙（间）结构看成是斜长石微晶之间充填了沸石、绿泥石等非粒状矿物的一种结构（见图3）。</p>\n<p>详细定名：二辉橄榄岩</p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528780877.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/893_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528780878.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/893_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>                                                                                                    <strong> 图1a 单偏光下包橄结构                                                                                                                  图1b 正交偏光下包橄结构  </strong></p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528780878(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/893_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528780879.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/893_3.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>                                                                                                                     <strong> 图2a 单偏光下包橄结构                                                                                                                  图2b 正交偏光下包橄结构  </strong><br><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528781584.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/893_4.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528781585.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/893_5.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><strong>                                                 图3a 单偏光下填隙结构                                                                                                                  图3b 正交偏光下填隙结构  </strong><br><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528781585(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/893_6.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528781586.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/893_7.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><strong>                                             图4a 单偏光下网状结构                                                                                                                 图4b 正交偏光下网状结构</strong></p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528780881.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/893_8.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p><strong><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528781942.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/893_9.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></strong></p>\n<p><strong>                                              图5a 单偏光下网状结构                                                                                                                    图5b 正交偏光下网状结构</strong></p>\n<p> </p>\n<p> </p>\n\n        ","sourceFullDescriptionText":"描述\n            \n辉石橄榄岩概述：\n       辉石橄榄岩属于超基性侵入岩，属硅酸不饱和的钙碱性系列岩石。化学成分的总的特征是贫硅（SiO2 ＜45％、贫碱、富镁铁）。反映在化学成分上，岩石几乎完全由铁镁矿物组成，主要是橄榄石、辉石，次要矿物主要为角闪石、黑云母、偶见斜长石，副矿物主要为尖晶石类、铬铁矿、钛铁矿、磷灰石以及磁铁矿。与纯橄岩相比，差别主要在于辉石橄榄岩的橄榄石含量（40％-90％）低于纯橄榄的橄榄石含量（＞90％）。本类岩石分布极少，约占岩浆岩分布面积的0.4％，其中喷出岩更为罕见，本类岩石新鲜者不多，主要矿物及次要矿物（橄榄石、辉石等）总是不同程度的遭受蛇纹石化的蚀变。\n辉石橄榄岩薄片镜下鉴定：\n        镜下矿物主要为橄榄石，橄榄石含量在40％-90％；次要矿物主要有斜方辉石、单斜辉石，有时可见少量角闪石、黑云母、铬铁矿等，每种辉石含量都大于5％，但两者相加不超过60％。岩石具中-粗粒粒状结构，也可见包橄结构（见图1、2）、网状结构（见图4、5）、填隙结构（见图3），海绵陨铁结构等。\n【主要矿物】\n       橄榄石（40％-90%）：主要为贵橄榄石，无色。一般为半自形--自形粒状，正高突起 (查看突起测定方法)。两组不完全解理 (查看解理测定方法)。干涉色可达二级顶部。可以包裹磁铁矿、铬铁矿、尖晶石，或出溶作用形成的针状、板状铁质矿物。橄榄石易发生蛇纹石化，在橄榄石外围常见斜方辉石、单斜辉石甚至棕色角闪石组成反应边结构。\n【次要矿物】\n\n斜方辉石（10-5%）：通常为紫苏辉石、顽火辉石、古铜辉石。它们与单斜辉石的区别是其干涉色低（一级），多为平行消光 (查看消光测定方法)。（紫苏辉石有时斜消光，但消光角不超过35°）。在斜方辉石中可见出溶的单斜辉石呈条纹、似文象交生。\n单斜辉石（30-35%）：主要为普通辉石、透辉石及变种异剥辉石等富钙辉石。单斜辉石镜下多呈无色或浅色，短柱状。正高突起。辉石式解理。斜消光，消光角一般>35°。二级干涉色。常见简单双晶、反应边结构、与斜方辉石等组成的交生结构和席勒构造。可发生绿泥石化、碳酸盐化、纤闪石化。\n\n【副矿物】主要为磁铁矿、磷灰石、榍石、尖晶石。总含量不超过2%。\n【次生变化】橄榄石多发生蛇纹石化、滑石化、碳酸盐化等。\n       蛇纹石化：蛇纹石化是超基性岩中的一种后期自变质产物，或中、低温热液对含镁的岩石进行交代产生含蛇纹石的一种蚀变作用，蚀变过程中H2O起着重要作用；滑石化：镁质超基性岩蚀变为滑石的次生变化；      \n        碳酸盐化：岩石遭受热液（中、低温热液为主）蚀变后，产生相当数量的碳酸盐矿物，如方解石、菱铁矿、铁白云石、白云石及菱镁矿等的作用。大多数岩石都能发生碳酸盐化。\n【结构构造】辉石橄榄岩与纯橄岩同属超基性岩类，岩石中常见的结构有粒状镶嵌结构、包橄结构、网状结构、填隙结构等。\n       粒状镶嵌结构：超基性岩中常见的结构。粒状矿物（如橄榄石）近似等轴，彼此呈直线镶嵌接触。\n       包橄结构：包含结构的一种，泛指岩石中大晶体包含小晶体的一种结构。根据包裹和被包裹的关系可分为主晶和客晶。主晶指大的包裹矿物，客晶指小的被包裹矿物。这种结构说明：客晶矿物形成早于主晶矿物。主晶常有熔蚀和交代早期客晶的现象。例如，在超基性岩中常见到大的辉石晶体包裹小的圆形的橄榄石晶体，即是包橄结构（见图1、2）。                                 \n       网状结构：橄榄石遭受蛇纹石化的次生结构。其特征是蛇纹石构成网状，网孔中保留着残余的橄榄石。如果临近的若干块残余橄榄石同时消光，则表明原来是同一个颗粒（见图4、5）。\n       填隙结构：在斜长石微晶所组成的间隙内，充填有辉石等暗色矿物，以及隐晶质、玻璃质等。有时也把填隙（间）结构看成是斜长石微晶之间充填了沸石、绿泥石等非粒状矿物的一种结构（见图3）。\n详细定名：二辉橄榄岩\n\n \n \n \n \n \n \n \n \n \n                                                                                                     图1a 单偏光下包橄结构                                                                                                                  图1b 正交偏光下包橄结构  \n\n \n \n \n \n \n \n \n \n                                                                                                                      图2a 单偏光下包橄结构                                                                                                                  图2b 正交偏光下包橄结构                                                   图3a 单偏光下填隙结构                                                                                                                  图3b 正交偏光下填隙结构                                               图4a 单偏光下网状结构                                                                                                                 图4b 正交偏光下网状结构\n\n\n                                              图5a 单偏光下网状结构                                                                                                                    图5b 正交偏光下网状结构","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"894":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：云闪辉橄岩</td>\n                        <td>英文名：Mica hornbill pyroxene peridotite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=4\" target=\"_blank\" rel=\"noopener noreferrer\">岩石标本</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=160\" target=\"_blank\" rel=\"noopener noreferrer\">岩浆岩</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=161\" target=\"_blank\" rel=\"noopener noreferrer\">超基性岩</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：Ia21.1</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p><strong>云闪辉橄岩概述：</strong></p>\n<p>       云闪辉榄岩属于超基性侵入岩，属硅酸不饱和的钙碱性系列岩石。化学成分的总的特征是贫硅（SiO<sub>2</sub> ＜45％、贫碱、富镁铁）。反映在化学成分上，岩石几乎完全由铁镁矿物组成，主要是橄榄石、辉石，次要矿物主要为角闪石、黑云母、偶见斜长石，副矿物主要为尖晶石类、铬铁矿、钛铁矿、磷灰石以及磁铁矿。与纯橄岩相比，差别主要在于辉石橄榄岩的橄榄石含量低于纯橄榄的橄榄石含量（＞90％），辉石的含量明显多于纯橄岩中辉石的含量。本类岩石分布较低，属于纯橄岩向辉长岩过渡的中间单元，主要矿物及次要矿物（橄榄石、辉石等）总是不同程度的遭受蛇纹石化的蚀变。</p>\n<p><strong>云闪辉橄岩薄片镜下鉴定：</strong></p>\n<p>        镜下矿物主要为橄榄石、辉石，橄榄石含量在40％左右，辉石含量在40％左右；次要矿物主要有黑云母、角闪石，含量在5％-10％之间。岩石具中-细粒半自形粒状结构（见图1），也可见包橄结构（见图2）、网状结构（见图4、5）、反应边结构（见图3）等。</p>\n<p><strong>【主要矿物】</strong></p>\n<p>       橄榄石（40％）：主要为贵橄榄石，无色。一般为半自形—自形粒状，正高突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)。两组不完全解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)。干涉色可达二级顶部。可以包裹磁铁矿、铬铁矿、尖晶石，或出溶作用形成的针状、板状铁质矿物。橄榄石易发生蛇纹石化，在橄榄石外围常见斜方辉石、单斜辉石甚至棕色角闪石组成反应边结构。</p>\n<p>       斜方辉石（15％-25％）：通常为紫苏辉石、顽火辉石、古铜辉石。它们与单斜辉石的区别是其干涉色低（一级），多为平行消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)。（紫苏辉石有时斜消光，但消光角不超过35°）。在斜方辉石中可见出溶的单斜辉石呈条纹、似文象交生。</p>\n<p>       单斜辉石（15％-25％）：主要为普通辉石、透辉石及变种异剥辉石等富钙辉石。单斜辉石镜下多呈无色或浅色，短柱状。正高突起。辉石式解理。斜消光，消光角一般&gt;35°。二级干涉色。常见简单双晶、反应边结构、与斜方辉石等组成的交生结构和席勒构造。可发生绿泥石化、碳酸盐化、纤闪石化。</p>\n<p><strong>【次要矿物】</strong></p>\n<p>       黑云母（5-10%）：镜下为片状，具浅黄色至棕色多色性，正中突起，解理极完全，干涉色最高为二级橙，平行消光，有时可见波状消光，常发生绿泥石化。</p>\n<p>       角闪石（5-10%）：单偏光镜下呈绿色，多色性明显，旋转物台一周，颜色呈深绿—黄绿—淡黄绿变化，正中-正高突起，具角闪石式解理（横切面具两组完全解理，解理夹角为56°、124°，纵切面具一组完全解理），多为自形-半自形长柱状，最高干涉色达二级黄绿，横切面呈对称消光，纵切面为斜消光，消光角一般小于25°，正延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)，负光性，常见简单双晶或聚片双晶，横切面上双晶缝平行菱形解理长对角线。</p>\n<p>【<strong>副矿物</strong>】主要为磁铁矿、磷灰石、榍石、尖晶石。总含量不超过2%。</p>\n<p>【<strong>次生变化</strong>】橄榄石多发生蛇纹石化、绿泥石化、滑石化、碳酸盐化等。</p>\n<p>       蛇纹石化：蛇纹石化是超基性岩中的一种后期自变质产物，或中、低温热液对含镁的岩石进行交代产生含蛇纹石的一种蚀变作用，蚀变过程中H<sub>2</sub>O起着重要作用（见图4）；</p>\n<p>       滑石化：镁质超基性岩蚀变为滑石的次生变化；</p>\n<p>       碳酸盐化：岩石遭受热液（中、低温热液为主）蚀变后，产生相当数量的碳酸盐矿物，如方解石、菱铁矿、铁白云石、白云石及菱镁矿等的作用。大多数岩石都能发生碳酸盐化。</p>\n<p>【结构构造】辉石橄榄岩与纯橄岩同属超基性岩类，岩石中常见的结构有包含结构、反应边结构、包橄结构、网状结构、填隙结构等。</p>\n<p>       反应边结构：岩浆中早期析出的矿物，因物理化学条件改变，与周围岩浆发生反应，在其外围产生新的反应矿物，这种现象称为反应边构造。例如，橄榄石外围可反应成为辉石，辉石外围可反应成为角闪石，角闪石外围又可反应成为黑云母。这种构造常见于超基性和基性岩中（见图3）。</p>\n<p>       包橄结构：包含结构的一种，泛指岩石中大晶体包含小晶体的一种结构。根据包裹和被包裹的关系可分为主晶和客晶。主晶指大的包裹矿物，客晶指小的被包裹矿物。这种结构说明：客晶矿物形成早于主晶矿物。主晶常有熔蚀和交代早期客晶的现象。例如，在超基性岩中常见到大的辉石晶体包裹小的圆形的橄榄石晶体，即是包橄结构（见图2）。                                 </p>\n<p>       网状结构：橄榄石遭受蛇纹石化的次生结构。其特征是蛇纹石构成网状，网孔中保留着残余的橄榄石。如果临近的若干块残余橄榄石同时消光，则表明原来是同一个颗粒（见图4、5）。</p>\n<p>详细定名：云闪二辉橄榄岩<br><br></p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529231794.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/894_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529231794(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/894_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>                                        </p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529231795.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/894_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529231795(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/894_3.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529231796.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/894_4.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529231796(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/894_5.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529231796(2).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/894_6.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529231797.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/894_7.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529231797(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/894_8.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529231797(2).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/894_9.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p> </p>\n<p> </p>\n\n        ","sourceFullDescriptionText":"描述\n            \n云闪辉橄岩概述：\n       云闪辉榄岩属于超基性侵入岩，属硅酸不饱和的钙碱性系列岩石。化学成分的总的特征是贫硅（SiO2 ＜45％、贫碱、富镁铁）。反映在化学成分上，岩石几乎完全由铁镁矿物组成，主要是橄榄石、辉石，次要矿物主要为角闪石、黑云母、偶见斜长石，副矿物主要为尖晶石类、铬铁矿、钛铁矿、磷灰石以及磁铁矿。与纯橄岩相比，差别主要在于辉石橄榄岩的橄榄石含量低于纯橄榄的橄榄石含量（＞90％），辉石的含量明显多于纯橄岩中辉石的含量。本类岩石分布较低，属于纯橄岩向辉长岩过渡的中间单元，主要矿物及次要矿物（橄榄石、辉石等）总是不同程度的遭受蛇纹石化的蚀变。\n云闪辉橄岩薄片镜下鉴定：\n        镜下矿物主要为橄榄石、辉石，橄榄石含量在40％左右，辉石含量在40％左右；次要矿物主要有黑云母、角闪石，含量在5％-10％之间。岩石具中-细粒半自形粒状结构（见图1），也可见包橄结构（见图2）、网状结构（见图4、5）、反应边结构（见图3）等。\n【主要矿物】\n       橄榄石（40％）：主要为贵橄榄石，无色。一般为半自形—自形粒状，正高突起 (查看突起测定方法)。两组不完全解理 (查看解理测定方法)。干涉色可达二级顶部。可以包裹磁铁矿、铬铁矿、尖晶石，或出溶作用形成的针状、板状铁质矿物。橄榄石易发生蛇纹石化，在橄榄石外围常见斜方辉石、单斜辉石甚至棕色角闪石组成反应边结构。\n       斜方辉石（15％-25％）：通常为紫苏辉石、顽火辉石、古铜辉石。它们与单斜辉石的区别是其干涉色低（一级），多为平行消光 (查看消光测定方法)。（紫苏辉石有时斜消光，但消光角不超过35°）。在斜方辉石中可见出溶的单斜辉石呈条纹、似文象交生。\n       单斜辉石（15％-25％）：主要为普通辉石、透辉石及变种异剥辉石等富钙辉石。单斜辉石镜下多呈无色或浅色，短柱状。正高突起。辉石式解理。斜消光，消光角一般>35°。二级干涉色。常见简单双晶、反应边结构、与斜方辉石等组成的交生结构和席勒构造。可发生绿泥石化、碳酸盐化、纤闪石化。\n【次要矿物】\n       黑云母（5-10%）：镜下为片状，具浅黄色至棕色多色性，正中突起，解理极完全，干涉色最高为二级橙，平行消光，有时可见波状消光，常发生绿泥石化。\n       角闪石（5-10%）：单偏光镜下呈绿色，多色性明显，旋转物台一周，颜色呈深绿—黄绿—淡黄绿变化，正中-正高突起，具角闪石式解理（横切面具两组完全解理，解理夹角为56°、124°，纵切面具一组完全解理），多为自形-半自形长柱状，最高干涉色达二级黄绿，横切面呈对称消光，纵切面为斜消光，消光角一般小于25°，正延性 (查看延性测定方法)，负光性，常见简单双晶或聚片双晶，横切面上双晶缝平行菱形解理长对角线。\n【副矿物】主要为磁铁矿、磷灰石、榍石、尖晶石。总含量不超过2%。\n【次生变化】橄榄石多发生蛇纹石化、绿泥石化、滑石化、碳酸盐化等。\n       蛇纹石化：蛇纹石化是超基性岩中的一种后期自变质产物，或中、低温热液对含镁的岩石进行交代产生含蛇纹石的一种蚀变作用，蚀变过程中H2O起着重要作用（见图4）；\n       滑石化：镁质超基性岩蚀变为滑石的次生变化；\n       碳酸盐化：岩石遭受热液（中、低温热液为主）蚀变后，产生相当数量的碳酸盐矿物，如方解石、菱铁矿、铁白云石、白云石及菱镁矿等的作用。大多数岩石都能发生碳酸盐化。\n【结构构造】辉石橄榄岩与纯橄岩同属超基性岩类，岩石中常见的结构有包含结构、反应边结构、包橄结构、网状结构、填隙结构等。\n       反应边结构：岩浆中早期析出的矿物，因物理化学条件改变，与周围岩浆发生反应，在其外围产生新的反应矿物，这种现象称为反应边构造。例如，橄榄石外围可反应成为辉石，辉石外围可反应成为角闪石，角闪石外围又可反应成为黑云母。这种构造常见于超基性和基性岩中（见图3）。\n       包橄结构：包含结构的一种，泛指岩石中大晶体包含小晶体的一种结构。根据包裹和被包裹的关系可分为主晶和客晶。主晶指大的包裹矿物，客晶指小的被包裹矿物。这种结构说明：客晶矿物形成早于主晶矿物。主晶常有熔蚀和交代早期客晶的现象。例如，在超基性岩中常见到大的辉石晶体包裹小的圆形的橄榄石晶体，即是包橄结构（见图2）。                                 \n       网状结构：橄榄石遭受蛇纹石化的次生结构。其特征是蛇纹石构成网状，网孔中保留着残余的橄榄石。如果临近的若干块残余橄榄石同时消光，则表明原来是同一个颗粒（见图4、5）。\n详细定名：云闪二辉橄榄岩","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"895":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：苏长岩</td>\n                        <td>英文名：Norite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=4\" target=\"_blank\" rel=\"noopener noreferrer\">岩石标本</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=160\" target=\"_blank\" rel=\"noopener noreferrer\">岩浆岩</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=162\" target=\"_blank\" rel=\"noopener noreferrer\">基性岩</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：Id12.3</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p><strong>苏长岩内容概述：</strong></p>\n<p>       苏长岩属于基性侵入岩类，其岩石化学成分特点为，SiO<sub>2</sub>含量在45％-52％之间，高于超基性岩类，低于中酸性岩类。基性岩类的矿物成分特点是：以紫苏辉石和基性斜长石（拉长石、培长石）为主要组分，有时含少量橄榄石，单斜辉石，色率一般为35-65之间，岩石呈灰黑色，密度较大。苏长岩常与辉长岩、超镁铁质岩共生。</p>\n<p><strong>苏长岩薄片镜下鉴定：</strong></p>\n<p>       镜下主要由基性斜长石、紫苏辉石组成，次要矿物主要有橄榄石、单斜辉石，有时可见棕色角闪石。岩石具常具苏长结构或辉长辉绿结构（图1），有时局部还可见包含结构（图2）。</p>\n<p>【<strong>主要矿物</strong>】</p>\n<p>       1.斜长石（40-45%）：主要为An&gt;50的拉长石和倍长石，偶见钙长石。长石多为自形—半自形的板状，但也有近于等轴状 。无色或浅褐色， 长石中常含矿物包裹体，包括铁、钛氧化物及其早结晶的铁镁矿物，当其包裹体含量较多时，长石呈暗色。低突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)。干涉色一级灰。聚片双晶发育且双晶个体宽，环带结构少见。常发生钠黝帘石化、绿泥石化，绢云母化等次生变化。局部可见斜长石包含斜方辉石呈包含结构（图2）。</p>\n<p>       2.斜方辉石（30-35%）：通常为紫苏辉石、顽火辉石、古铜辉石。它们与单斜辉石的区别是其干涉色低（ 一级），多为平行消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)。（紫苏辉石有时斜消光，但消光角不超过35°）。在斜方辉石中可见出溶的单斜辉石呈条纹、似文象交生。蚀变类型同单斜辉石。</p>\n<p>【<strong>次要矿物</strong>】</p>\n<p>       1.橄榄石（10-15%）：主要为贵橄榄石，无色。一般为半自形--自形粒状，正极高突起。两组不完全解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)。干涉色达二级顶部。可以包裹磁铁矿、铬铁矿、尖晶石，或出溶作用形成的针状、板状铁质矿物。在橄榄石外围常见斜方辉石、单斜辉石甚至棕色角闪石的反应边结构。</p>\n<p>       2.单斜辉石（5-10%）：主要为普通辉石、透辉石及二者的变种异剥辉石等富钙辉石。单斜辉石镜下多呈无色或浅色，短柱状。正高突起。辉石式解理。斜消光，消光角一般&gt;35°。二级干涉色。常见简单双晶、反应边结构、与斜方辉石等组成的交生结构和席勒构造。可发生绿泥石化、碳酸盐化、纤闪石化。</p>\n<p>       3.黑云母（1-3%）：通常呈棕色色调，多色性明显。片状矿物。正中突起。干涉色二级橙。有时包裹磁铁矿，在氧逸度变化时呈反应矿物产出。</p>\n<p>【<strong>副矿物</strong>】主要为磁铁矿、磷灰石、榍石、尖晶石。总含量不超过2%。</p>\n<p>【<strong>次生变化</strong>】多发生钠黝帘石化、绿泥石化，绢云母化、碳酸盐化、纤闪石化等。</p>\n<p>       钠黝帘石化：这是基性斜长石经常发生的一种蚀变现象。“钠黝帘石”就是钠长石、黝帘石和绿帘石等矿物的集合体，无或有少量的绢云母、绿泥石、石英、葡萄石、石榴石等矿物。</p>\n<p>       绿泥石化：绿泥石是分布很广的岩浆期后矿物，交代角闪石、黑云母等铁镁暗色矿物。有时也交代长石、石英。</p>\n<p>       碳酸盐化：岩石遭受热液（中、低温热液为主）蚀变后，产生相当数量的碳酸盐矿物，如方解石、菱铁矿、铁白云石、白云石及菱镁矿等的作用。大多数岩石都能发生碳酸盐化。</p>\n<p>       纤闪石化：指纤维状的角闪石（主要是阳起石、透闪石）集合体交代辉石的现象，所以又称次闪石化。</p>\n<p>【<strong>结构</strong>】</p>\n<p>       苏长结构：粒状结构的一种，以苏长岩最为特征。这种结构是斜方辉石和斜长石晶形发育程度相近，或均为半自形晶粒，或均为他形晶粒，这表明是辉石和斜长石同时从岩浆中共结结晶的结果。</p>\n<p>       包含结构：超基性岩类与基性岩类所特有的一种结构，其表现为颗粒粗大的辉石或角闪石中包含有许多较小的圆粒状橄榄石。有一种说法认为，被包围的矿物是熔浆中早期结晶矿物，经重力作用堆积到熔体底部，晶体之间充满了粒间熔浆，熔浆结晶后形成巨大晶体，由于粒间熔浆溶蚀早结晶的矿物，所以多为浑圆状。它与反应边结构不同的是主晶和客晶之间并不是反应关系，而是包裹关系（早期结晶出来的橄榄石被晚期结晶的辉石所包裹）。</p>\n<p>       辉长辉绿结构：板状或短柱状斜长石晶体比等轴状或短柱状辉石的自形程度稍高，介于辉长结构和辉绿结构之间。</p>\n<p> </p>\n<p><br>                                              详细定名：苏长岩</p>\n<p> </p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528786457.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/895_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528786458.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/895_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a>                                                                                                         </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>                                                                                         <strong>       图1a 单偏光下辉长辉绿结构                                                                                                         图1b 正交偏光下辉长辉绿结构</strong></p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528786458(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/895_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528786459.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/895_3.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>                                                                                          <strong>        图2a 单偏光下包含结构      </strong>                                                                                     <strong>                     图2b 正交偏光下包含结构</strong></p>\n<p> </p>\n\n        ","sourceFullDescriptionText":"描述\n            \n苏长岩内容概述：\n       苏长岩属于基性侵入岩类，其岩石化学成分特点为，SiO2含量在45％-52％之间，高于超基性岩类，低于中酸性岩类。基性岩类的矿物成分特点是：以紫苏辉石和基性斜长石（拉长石、培长石）为主要组分，有时含少量橄榄石，单斜辉石，色率一般为35-65之间，岩石呈灰黑色，密度较大。苏长岩常与辉长岩、超镁铁质岩共生。\n苏长岩薄片镜下鉴定：\n       镜下主要由基性斜长石、紫苏辉石组成，次要矿物主要有橄榄石、单斜辉石，有时可见棕色角闪石。岩石具常具苏长结构或辉长辉绿结构（图1），有时局部还可见包含结构（图2）。\n【主要矿物】\n       1.斜长石（40-45%）：主要为An>50的拉长石和倍长石，偶见钙长石。长石多为自形—半自形的板状，但也有近于等轴状 。无色或浅褐色， 长石中常含矿物包裹体，包括铁、钛氧化物及其早结晶的铁镁矿物，当其包裹体含量较多时，长石呈暗色。低突起 (查看突起测定方法)。干涉色一级灰。聚片双晶发育且双晶个体宽，环带结构少见。常发生钠黝帘石化、绿泥石化，绢云母化等次生变化。局部可见斜长石包含斜方辉石呈包含结构（图2）。\n       2.斜方辉石（30-35%）：通常为紫苏辉石、顽火辉石、古铜辉石。它们与单斜辉石的区别是其干涉色低（ 一级），多为平行消光 (查看消光测定方法)。（紫苏辉石有时斜消光，但消光角不超过35°）。在斜方辉石中可见出溶的单斜辉石呈条纹、似文象交生。蚀变类型同单斜辉石。\n【次要矿物】\n       1.橄榄石（10-15%）：主要为贵橄榄石，无色。一般为半自形--自形粒状，正极高突起。两组不完全解理 (查看解理测定方法)。干涉色达二级顶部。可以包裹磁铁矿、铬铁矿、尖晶石，或出溶作用形成的针状、板状铁质矿物。在橄榄石外围常见斜方辉石、单斜辉石甚至棕色角闪石的反应边结构。\n       2.单斜辉石（5-10%）：主要为普通辉石、透辉石及二者的变种异剥辉石等富钙辉石。单斜辉石镜下多呈无色或浅色，短柱状。正高突起。辉石式解理。斜消光，消光角一般>35°。二级干涉色。常见简单双晶、反应边结构、与斜方辉石等组成的交生结构和席勒构造。可发生绿泥石化、碳酸盐化、纤闪石化。\n       3.黑云母（1-3%）：通常呈棕色色调，多色性明显。片状矿物。正中突起。干涉色二级橙。有时包裹磁铁矿，在氧逸度变化时呈反应矿物产出。\n【副矿物】主要为磁铁矿、磷灰石、榍石、尖晶石。总含量不超过2%。\n【次生变化】多发生钠黝帘石化、绿泥石化，绢云母化、碳酸盐化、纤闪石化等。\n       钠黝帘石化：这是基性斜长石经常发生的一种蚀变现象。“钠黝帘石”就是钠长石、黝帘石和绿帘石等矿物的集合体，无或有少量的绢云母、绿泥石、石英、葡萄石、石榴石等矿物。\n       绿泥石化：绿泥石是分布很广的岩浆期后矿物，交代角闪石、黑云母等铁镁暗色矿物。有时也交代长石、石英。\n       碳酸盐化：岩石遭受热液（中、低温热液为主）蚀变后，产生相当数量的碳酸盐矿物，如方解石、菱铁矿、铁白云石、白云石及菱镁矿等的作用。大多数岩石都能发生碳酸盐化。\n       纤闪石化：指纤维状的角闪石（主要是阳起石、透闪石）集合体交代辉石的现象，所以又称次闪石化。\n【结构】\n       苏长结构：粒状结构的一种，以苏长岩最为特征。这种结构是斜方辉石和斜长石晶形发育程度相近，或均为半自形晶粒，或均为他形晶粒，这表明是辉石和斜长石同时从岩浆中共结结晶的结果。\n       包含结构：超基性岩类与基性岩类所特有的一种结构，其表现为颗粒粗大的辉石或角闪石中包含有许多较小的圆粒状橄榄石。有一种说法认为，被包围的矿物是熔浆中早期结晶矿物，经重力作用堆积到熔体底部，晶体之间充满了粒间熔浆，熔浆结晶后形成巨大晶体，由于粒间熔浆溶蚀早结晶的矿物，所以多为浑圆状。它与反应边结构不同的是主晶和客晶之间并不是反应关系，而是包裹关系（早期结晶出来的橄榄石被晚期结晶的辉石所包裹）。\n       辉长辉绿结构：板状或短柱状斜长石晶体比等轴状或短柱状辉石的自形程度稍高，介于辉长结构和辉绿结构之间。\n \n                                              详细定名：苏长岩\n \n                                                                                                         \n \n \n \n \n \n                                                                                                图1a 单偏光下辉长辉绿结构                                                                                                         图1b 正交偏光下辉长辉绿结构\n\n \n \n \n \n \n \n \n \n                                                                                                  图2a 单偏光下包含结构                                                                                                                图2b 正交偏光下包含结构","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"896":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：辉绿玢岩</td>\n                        <td>英文名：Diabase-porphyrite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=4\" target=\"_blank\" rel=\"noopener noreferrer\">岩石标本</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=160\" target=\"_blank\" rel=\"noopener noreferrer\">岩浆岩</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=162\" target=\"_blank\" rel=\"noopener noreferrer\">基性岩</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：Ie30.1</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p><strong>辉绿玢岩内容概述：</strong></p>\n<p>       辉绿玢岩是矿物成分和化学成分与辉长岩相当的浅成岩，常呈岩墙、岩床产出。</p>\n<p><strong>辉绿玢岩薄片镜下鉴定：</strong></p>\n<p>       镜下可见其具斑状结构，斑晶主要由斜长石、辉石组成（有时含有角闪石），基质有斜长石、辉石、黑云母等组成，其整体呈斑状结构，基质具有典型的辉绿结构和次辉绿结构。</p>\n<p>该示范薄片中，矿物蚀变严重，无论是暗色矿物还是浅色矿物，都有明显的蚀变现象，其中以斜长石的钠黝帘石化、绿泥石化、绢云母化，暗色矿物的绿泥石化、皂石化、绿帘石化为主。</p>\n<p> </p>\n<p>【<strong>斑晶</strong>】</p>\n<p>       1.斜长石（10-15%）：主要为An&gt;50的拉长石和倍长石，偶见钙长石。长石多为自形—半自形的板状，但也有近于等轴状。单偏光镜下无色或浅褐色，长石中常含矿物包裹体，包括铁、钛氧化物及其早结晶的铁镁矿物，当其包裹体含量较多时，长石呈暗色。低突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)，干涉色一级灰。聚片双晶发育且双晶个体宽，环带结构较少见。多数发生钠黝帘石化、绿泥石化，绢云母化等次生变化，有时可见其呈交代残余现象。</p>\n<p>       2. 单斜辉石（5%左右）：主要为普通辉石、透辉石及二者的变种异剥辉石等富钙辉石。单斜辉石镜下多呈无色或浅色，短柱状。正高突起。具辉石式解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)，即横断面上具两组完全解理，近于垂直，交角为93°—92°（87°—88°），纵断面上具一组完全解理。最高干涉色可达二级。横断面呈对称消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)，纵断面为斜消光，消光角一般&gt;35°。有时可见简单双晶。多数发生绿泥石化、皂石化、绿帘石化。</p>\n<p>【<strong>基质</strong>】</p>\n<p>        1.斜长石（40-45%）：主要为An&gt;50的拉长石和倍长石，偶见钙长石。单偏光镜下无色或浅褐色，低突起，干涉色一级灰。基质中的斜长石颗粒较小，为自形—半自形的长板状，有时可见其聚片双晶发育，多呈交织状分布于斑晶周围，有时略显示轻微的定向性，其交织构成的三角架之间被辉石颗粒所充填而构成辉绿结构。但多数发生钠黝帘石化、绿泥石化，绢云母化等次生变化。</p>\n<p>        2. 单斜辉石（20-25%左右）：主要为普通辉石、透辉石及二者的变种异剥辉石等富钙辉石。单斜辉石镜下多呈无色或浅色，短柱状。正高突起。具辉石式解理，即横断面上具两组完全解理，近于垂直，交角为93°—92°（87°—88°），纵断面上具一组完全解理。最高干涉色可达二级。横断面呈对称消光，纵断面为斜消光，消光角一般&gt;35°。基质中辉石颗粒较小，多呈细小颗粒充填于斜长石组成的空隙中。多数发生绿泥石化、皂石化、绿帘石化。</p>\n<p>       3. 磷灰石（3-5%）：单偏光镜下呈无色，正高突起，其典型特征是横切面为六边形形态（常呈圆形粒状），全消光；纵切面为长柱状或针状，斜消光，干涉色为一级灰白，呈细小颗粒分布于其它基质矿物之间。</p>\n<p>       4.黑云母（2-3%）：通常呈棕色色调，单偏光镜下多色性明显，片状矿物。正中突起。正交偏光镜下干涉色二级橙，平行消光，呈细小片状分布于其他基质之间。</p>\n<p>       5.不透明矿物（2%）：多数为铁质物质，不透明。</p>\n<p>【<strong>副矿物</strong>】主要为磁铁矿、榍石、尖晶石。总含量不超过2%。</p>\n<p>【<strong>次生变化</strong>】多发生绿泥石化、绢云母化、钠黝帘石化等。</p>\n<p>       1.绿泥石化：绿泥石是分布很广的岩浆期后矿物，常交代角闪石、黑云母等铁镁暗色矿物。单偏光镜下多为浅绿色和浅黄色，多色性明显，正低-正中突起，具一组极完全解理，多呈片状、鳞片状集合体，干涉色较低，不超过一级，且多具有靛蓝色或铁锈色的异常干涉色（图1）。</p>\n<p>       2.绢云母化：绢云母在薄片中为密集的鳞片状集合体，常为长石类及副长石类的此生蚀变矿物，尤其是斜长石，比钾长石更易发生绢云母化。正交偏光镜间，绢云母由于在集合体中的方位不同，因而呈现五彩缤纷的干涉色交织在一起。根据研究，绢云母的成因有两种，一是水热蚀变的产物，二是风化成因。</p>\n<p>       3.钠黝帘石化：基性斜长石经常发生的一种蚀变现象。“钠黝帘石”就是钠长石、黝帘石和绿帘石等矿物的集合体，无或有少量的绢云母、绿泥石、石英、葡萄石、石榴石等矿物（图2）。</p>\n<p> </p>\n<p>【结构】薄片整体呈斑状结构，基质具辉绿结构，有时可见包含结构和嵌晶含长结构。</p>\n<p>       1.斑状结构：岩石中矿物颗粒分为大小截然不同的两群，大的称为斑晶，小的及不结晶的玻璃质称为基质。其间没有中等大小的颗粒，可与不等粒结构相区别（图3）。</p>\n<p>       2.辉绿结构：浅成的基性岩如辉绿岩常具有的结构，故名。在肉眼或偏光显微镜下，岩石中斜长石呈自形板条状交织分布，而他形粒状辉石则充填在斜长石板条状晶粒构成的三角形空隙中间（图4）。</p>\n<p>       3.嵌晶含长结构：属于包含结构中的一种，其特征是在较大的他形辉石颗粒中，包含有许多较自形的柱状斜长石晶体，与辉绿结构的结晶条件相似，但晚期辉石的晶出量较多，晶粒较大。常见于基性侵入岩中（图5）。</p>\n<p>       4.包含结构：又称“嵌晶状结构”。泛指岩石中大晶体包含小晶体的一种结构。根据包裹和被包裹的关系可分为主晶和客晶。主晶指大的包裹矿物，客晶指小的被包裹矿物。这种结构说明：客晶矿物形成早于主 晶矿物。主晶常有熔蚀和交代早期客晶的现象。例如，在超基性岩中常见到大的辉石晶体包裹小的圆形的橄榄石晶体，是一种典型的包含结构。</p>\n<p>                                              详细定名： 辉绿玢岩</p>\n<p><br><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528788406.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/896_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528788406(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/896_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>                                                                                 </p>\n<p>                                          <strong>      图1a 单偏光下斜长石绿泥石化                                                                                                   图1b 正交偏光下斜长石绿泥石化</strong></p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528788989.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/896_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528788990.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/896_3.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p><strong>                                                                   图2a 单偏光下斜长石钠黝帘石化                                                                                                   图2b 正交偏光下斜长石钠黝帘石化</strong>                 </p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528788407(2).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/896_4.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528788408.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/896_5.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a>                                                                   </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p><strong>                                                      图3a 单偏光下斑状结构                                                                                                          图3b 正交偏光下斑状结构</strong>       </p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528788408(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/896_6.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528788409.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/896_7.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p><strong>                                                                                                    图4a 单偏光下辉绿结构                                                                                                            图4b 正交偏光下辉绿结构</strong>      </p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528788409(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/896_8.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528788409(2).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/896_9.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p><strong>                                                                                                图5a 单偏光下嵌晶含长结构                                                                                                          图5b 正交偏光下嵌晶含长结构</strong>    </p>\n\n        ","sourceFullDescriptionText":"描述\n            \n辉绿玢岩内容概述：\n       辉绿玢岩是矿物成分和化学成分与辉长岩相当的浅成岩，常呈岩墙、岩床产出。\n辉绿玢岩薄片镜下鉴定：\n       镜下可见其具斑状结构，斑晶主要由斜长石、辉石组成（有时含有角闪石），基质有斜长石、辉石、黑云母等组成，其整体呈斑状结构，基质具有典型的辉绿结构和次辉绿结构。\n该示范薄片中，矿物蚀变严重，无论是暗色矿物还是浅色矿物，都有明显的蚀变现象，其中以斜长石的钠黝帘石化、绿泥石化、绢云母化，暗色矿物的绿泥石化、皂石化、绿帘石化为主。\n \n【斑晶】\n       1.斜长石（10-15%）：主要为An>50的拉长石和倍长石，偶见钙长石。长石多为自形—半自形的板状，但也有近于等轴状。单偏光镜下无色或浅褐色，长石中常含矿物包裹体，包括铁、钛氧化物及其早结晶的铁镁矿物，当其包裹体含量较多时，长石呈暗色。低突起 (查看突起测定方法)，干涉色一级灰。聚片双晶发育且双晶个体宽，环带结构较少见。多数发生钠黝帘石化、绿泥石化，绢云母化等次生变化，有时可见其呈交代残余现象。\n       2. 单斜辉石（5%左右）：主要为普通辉石、透辉石及二者的变种异剥辉石等富钙辉石。单斜辉石镜下多呈无色或浅色，短柱状。正高突起。具辉石式解理 (查看解理测定方法)，即横断面上具两组完全解理，近于垂直，交角为93°—92°（87°—88°），纵断面上具一组完全解理。最高干涉色可达二级。横断面呈对称消光 (查看消光测定方法)，纵断面为斜消光，消光角一般>35°。有时可见简单双晶。多数发生绿泥石化、皂石化、绿帘石化。\n【基质】\n        1.斜长石（40-45%）：主要为An>50的拉长石和倍长石，偶见钙长石。单偏光镜下无色或浅褐色，低突起，干涉色一级灰。基质中的斜长石颗粒较小，为自形—半自形的长板状，有时可见其聚片双晶发育，多呈交织状分布于斑晶周围，有时略显示轻微的定向性，其交织构成的三角架之间被辉石颗粒所充填而构成辉绿结构。但多数发生钠黝帘石化、绿泥石化，绢云母化等次生变化。\n        2. 单斜辉石（20-25%左右）：主要为普通辉石、透辉石及二者的变种异剥辉石等富钙辉石。单斜辉石镜下多呈无色或浅色，短柱状。正高突起。具辉石式解理，即横断面上具两组完全解理，近于垂直，交角为93°—92°（87°—88°），纵断面上具一组完全解理。最高干涉色可达二级。横断面呈对称消光，纵断面为斜消光，消光角一般>35°。基质中辉石颗粒较小，多呈细小颗粒充填于斜长石组成的空隙中。多数发生绿泥石化、皂石化、绿帘石化。\n       3. 磷灰石（3-5%）：单偏光镜下呈无色，正高突起，其典型特征是横切面为六边形形态（常呈圆形粒状），全消光；纵切面为长柱状或针状，斜消光，干涉色为一级灰白，呈细小颗粒分布于其它基质矿物之间。\n       4.黑云母（2-3%）：通常呈棕色色调，单偏光镜下多色性明显，片状矿物。正中突起。正交偏光镜下干涉色二级橙，平行消光，呈细小片状分布于其他基质之间。\n       5.不透明矿物（2%）：多数为铁质物质，不透明。\n【副矿物】主要为磁铁矿、榍石、尖晶石。总含量不超过2%。\n【次生变化】多发生绿泥石化、绢云母化、钠黝帘石化等。\n       1.绿泥石化：绿泥石是分布很广的岩浆期后矿物，常交代角闪石、黑云母等铁镁暗色矿物。单偏光镜下多为浅绿色和浅黄色，多色性明显，正低-正中突起，具一组极完全解理，多呈片状、鳞片状集合体，干涉色较低，不超过一级，且多具有靛蓝色或铁锈色的异常干涉色（图1）。\n       2.绢云母化：绢云母在薄片中为密集的鳞片状集合体，常为长石类及副长石类的此生蚀变矿物，尤其是斜长石，比钾长石更易发生绢云母化。正交偏光镜间，绢云母由于在集合体中的方位不同，因而呈现五彩缤纷的干涉色交织在一起。根据研究，绢云母的成因有两种，一是水热蚀变的产物，二是风化成因。\n       3.钠黝帘石化：基性斜长石经常发生的一种蚀变现象。“钠黝帘石”就是钠长石、黝帘石和绿帘石等矿物的集合体，无或有少量的绢云母、绿泥石、石英、葡萄石、石榴石等矿物（图2）。\n \n【结构】薄片整体呈斑状结构，基质具辉绿结构，有时可见包含结构和嵌晶含长结构。\n       1.斑状结构：岩石中矿物颗粒分为大小截然不同的两群，大的称为斑晶，小的及不结晶的玻璃质称为基质。其间没有中等大小的颗粒，可与不等粒结构相区别（图3）。\n       2.辉绿结构：浅成的基性岩如辉绿岩常具有的结构，故名。在肉眼或偏光显微镜下，岩石中斜长石呈自形板条状交织分布，而他形粒状辉石则充填在斜长石板条状晶粒构成的三角形空隙中间（图4）。\n       3.嵌晶含长结构：属于包含结构中的一种，其特征是在较大的他形辉石颗粒中，包含有许多较自形的柱状斜长石晶体，与辉绿结构的结晶条件相似，但晚期辉石的晶出量较多，晶粒较大。常见于基性侵入岩中（图5）。\n       4.包含结构：又称“嵌晶状结构”。泛指岩石中大晶体包含小晶体的一种结构。根据包裹和被包裹的关系可分为主晶和客晶。主晶指大的包裹矿物，客晶指小的被包裹矿物。这种结构说明：客晶矿物形成早于主 晶矿物。主晶常有熔蚀和交代早期客晶的现象。例如，在超基性岩中常见到大的辉石晶体包裹小的圆形的橄榄石晶体，是一种典型的包含结构。\n                                              详细定名： 辉绿玢岩\n\n \n \n \n \n \n \n \n                                                                                 \n                                                图1a 单偏光下斜长石绿泥石化                                                                                                   图1b 正交偏光下斜长石绿泥石化\n\n \n \n \n \n \n \n \n \n \n                                                                   图2a 单偏光下斜长石钠黝帘石化                                                                                                   图2b 正交偏光下斜长石钠黝帘石化                 \n                                                                   \n \n \n \n \n \n \n \n \n                                                      图3a 单偏光下斑状结构                                                                                                          图3b 正交偏光下斑状结构       \n\n \n \n \n \n \n \n \n \n                                                                                                    图4a 单偏光下辉绿结构                                                                                                            图4b 正交偏光下辉绿结构      \n\n \n \n \n \n \n \n \n \n                                                                                                图5a 单偏光下嵌晶含长结构                                                                                                          图5b 正交偏光下嵌晶含长结构","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"897":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：辉绿岩</td>\n                        <td>英文名：Diabase</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=4\" target=\"_blank\" rel=\"noopener noreferrer\">岩石标本</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=160\" target=\"_blank\" rel=\"noopener noreferrer\">岩浆岩</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=162\" target=\"_blank\" rel=\"noopener noreferrer\">基性岩</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：Ie30.3</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p><strong>辉绿岩内容概述：</strong></p>\n<p>       辉绿岩是矿物成分和化学成分与辉长岩相当的浅成岩，常呈岩墙、岩床产出。</p>\n<p><strong>辉绿岩薄片镜下鉴定</strong>：</p>\n<p>      镜下可见主要矿物为辉石、基性斜长石，二者含量相近；次要矿物主要有橄榄石、角闪石、黑云母、碱性长石中的一种或几种。岩石具细-中粒粒状结构，辉绿岩具有典型的辉绿结构和次辉绿结构。</p>\n<p>【<strong>主要矿物</strong>】</p>\n<p>       1.斜长石（40-45%）：主要为An&gt;50的拉长石和倍长石，偶见钙长石。长石多为自形—半自形的板状，但也有近于等轴状。单偏光镜下无色或浅褐色，长石中常含矿物包裹体，包括铁、钛氧化物及其早结晶的铁镁矿物，当其包裹体含量较多时，长石呈暗色。低突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)，干涉色一级灰。聚片双晶发育且双晶个体宽，环带结构较少见。常发生钠黝帘石化、绿泥石化，绢云母化等次生变化。</p>\n<p>       2.单斜辉石（30-35%）：主要为普通辉石、透辉石及二者的变种异剥辉石等富钙辉石。单斜辉石镜下多呈无色或浅色，短柱状。正高突起。辉石式解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)。斜消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)，消光角一般&gt;35°。常见简单双晶、反应边结构、与斜方辉石等组成的交生结构和席勒构造。可发生绿泥石化、碳酸盐化、纤闪石化。</p>\n<p>【<strong>次要矿物</strong>】      </p>\n<p>       1.斜方辉石（10-15%）：通常为紫苏辉石、顽火辉石、古铜辉石。它们与单斜辉石的区别是其干涉色低（一级），多为平行消光。（紫苏辉石有时斜消光，但消光角不超过35°）。在斜方辉石中可见出溶的单斜辉石呈条纹、似文象交生。蚀变类型同单斜辉石。</p>\n<p>       2.橄榄石（5-10%）：主要为贵橄榄石，单偏光镜下无色。一般为半自形--自形粒状，正极高突起，两组不完全解理。正交偏光镜下干涉色达二级顶部。可以包裹磁铁矿、铬铁矿、尖晶石，或出溶作用形成的针状、板状铁质矿物。在橄榄石外围常见斜方辉石、单斜辉石甚至棕色角闪石的反应边结构。</p>\n<p>       3.黑云母（1-3%）：通常呈棕色色调，单偏光镜下多色性明显，片状矿物。正中突起。正交偏光镜下干涉色二级橙。有时包裹磁铁矿，在氧逸度变化时呈反应矿物产出。</p>\n<p>【<strong>副矿物</strong>】主要为磁铁矿、磷灰石、榍石、尖晶石。总含量不超过2%。</p>\n<p>【<strong>次生变化</strong>】多发生钠黝帘石化、绿泥石化，绢云母化、碳酸盐化、纤闪石化等。</p>\n<p>       钠黝帘石化：基性斜长石经常发生的一种蚀变现象。“钠黝帘石”就是钠长石、黝帘石和绿帘石等矿物的集合体，无或有少量的绢云母、绿泥石、石英、葡萄石、石榴石等矿物。</p>\n<p>       绿泥石化：绿泥石是分布很广的岩浆期后矿物，流体交代角闪石、黑云母等铁镁暗色矿物后在暗色矿物边界可见绿泥石化（图1）。</p>\n<p>       碳酸盐化：岩石遭受热液（中、低温热液为主）蚀变后，产生相当数量的碳酸盐矿物，如方解石、菱铁矿、铁白云石、白云石及菱镁矿等的作用，即为碳酸盐化。</p>\n<p>       纤闪石化：指纤维状的角闪石（主要是阳起石、透闪石）集合体交代辉石的现象，所以又称次闪石化。</p>\n<p><strong>【结构】</strong></p>\n<p>        辉绿结构：浅成的基性岩如辉绿岩常具有的结构，故名。在肉眼或偏光显微镜下，岩石中斜长石呈自形板条状交织分布，而他形粒状辉石则充填在斜长石板条状晶粒构成的三角形空隙中间（图2）。</p>\n<p>        次辉绿结构：斜长石晶体被包裹和半包裹在几个普通的辉石晶体中。</p>\n<p>        嵌晶含长结构：属于包含结构中的一种，其特征是在较大的他形辉石颗粒中，包含有许多较自形的柱状斜长石晶体，与辉绿结构的结晶条件相似，但晚期辉石的晶出量较多，晶粒较大（图3）。常见于基性侵入岩中。</p>\n<p>       包含结构：又称“嵌晶状结构”。泛指岩石中大晶体包含小晶体的一种结构。根据包裹和被包裹的关系可分为主晶和客晶。主晶指大的包裹矿物，客晶指小的被包裹矿物。这种结构说明：客晶矿物形成早于主晶矿物。主晶常有熔蚀和交代早期客晶的现象。例如，在超基性岩中常见到大的辉石晶体包裹小的圆形的橄榄石晶体，是一种典型的包含结构。</p>\n<p>                                                详细定名： 辉绿岩</p>\n<p> </p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528791037.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/897_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528791037(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/897_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p><strong>                                                                                                 图1a 单偏光下绿泥石化                                                                                                              图1b 正交偏光下绿泥石化</strong></p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528791038.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/897_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528791038(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/897_3.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a>                                                                                                                         </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p><strong>                                                                           图2a 单偏光下辉绿结构                                                                                                             图2b 正交偏光下辉绿结构</strong></p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528791039.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/897_4.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528791039(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/897_5.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p><strong>                                                                                                  图3a 单偏光下嵌晶含长结构                                                                                                         图3b 正交偏光下嵌晶含长结构</strong></p>\n<p> </p>\n\n        ","sourceFullDescriptionText":"描述\n            \n辉绿岩内容概述：\n       辉绿岩是矿物成分和化学成分与辉长岩相当的浅成岩，常呈岩墙、岩床产出。\n辉绿岩薄片镜下鉴定：\n      镜下可见主要矿物为辉石、基性斜长石，二者含量相近；次要矿物主要有橄榄石、角闪石、黑云母、碱性长石中的一种或几种。岩石具细-中粒粒状结构，辉绿岩具有典型的辉绿结构和次辉绿结构。\n【主要矿物】\n       1.斜长石（40-45%）：主要为An>50的拉长石和倍长石，偶见钙长石。长石多为自形—半自形的板状，但也有近于等轴状。单偏光镜下无色或浅褐色，长石中常含矿物包裹体，包括铁、钛氧化物及其早结晶的铁镁矿物，当其包裹体含量较多时，长石呈暗色。低突起 (查看突起测定方法)，干涉色一级灰。聚片双晶发育且双晶个体宽，环带结构较少见。常发生钠黝帘石化、绿泥石化，绢云母化等次生变化。\n       2.单斜辉石（30-35%）：主要为普通辉石、透辉石及二者的变种异剥辉石等富钙辉石。单斜辉石镜下多呈无色或浅色，短柱状。正高突起。辉石式解理 (查看解理测定方法)。斜消光 (查看消光测定方法)，消光角一般>35°。常见简单双晶、反应边结构、与斜方辉石等组成的交生结构和席勒构造。可发生绿泥石化、碳酸盐化、纤闪石化。\n【次要矿物】      \n       1.斜方辉石（10-15%）：通常为紫苏辉石、顽火辉石、古铜辉石。它们与单斜辉石的区别是其干涉色低（一级），多为平行消光。（紫苏辉石有时斜消光，但消光角不超过35°）。在斜方辉石中可见出溶的单斜辉石呈条纹、似文象交生。蚀变类型同单斜辉石。\n       2.橄榄石（5-10%）：主要为贵橄榄石，单偏光镜下无色。一般为半自形--自形粒状，正极高突起，两组不完全解理。正交偏光镜下干涉色达二级顶部。可以包裹磁铁矿、铬铁矿、尖晶石，或出溶作用形成的针状、板状铁质矿物。在橄榄石外围常见斜方辉石、单斜辉石甚至棕色角闪石的反应边结构。\n       3.黑云母（1-3%）：通常呈棕色色调，单偏光镜下多色性明显，片状矿物。正中突起。正交偏光镜下干涉色二级橙。有时包裹磁铁矿，在氧逸度变化时呈反应矿物产出。\n【副矿物】主要为磁铁矿、磷灰石、榍石、尖晶石。总含量不超过2%。\n【次生变化】多发生钠黝帘石化、绿泥石化，绢云母化、碳酸盐化、纤闪石化等。\n       钠黝帘石化：基性斜长石经常发生的一种蚀变现象。“钠黝帘石”就是钠长石、黝帘石和绿帘石等矿物的集合体，无或有少量的绢云母、绿泥石、石英、葡萄石、石榴石等矿物。\n       绿泥石化：绿泥石是分布很广的岩浆期后矿物，流体交代角闪石、黑云母等铁镁暗色矿物后在暗色矿物边界可见绿泥石化（图1）。\n       碳酸盐化：岩石遭受热液（中、低温热液为主）蚀变后，产生相当数量的碳酸盐矿物，如方解石、菱铁矿、铁白云石、白云石及菱镁矿等的作用，即为碳酸盐化。\n       纤闪石化：指纤维状的角闪石（主要是阳起石、透闪石）集合体交代辉石的现象，所以又称次闪石化。\n【结构】\n        辉绿结构：浅成的基性岩如辉绿岩常具有的结构，故名。在肉眼或偏光显微镜下，岩石中斜长石呈自形板条状交织分布，而他形粒状辉石则充填在斜长石板条状晶粒构成的三角形空隙中间（图2）。\n        次辉绿结构：斜长石晶体被包裹和半包裹在几个普通的辉石晶体中。\n        嵌晶含长结构：属于包含结构中的一种，其特征是在较大的他形辉石颗粒中，包含有许多较自形的柱状斜长石晶体，与辉绿结构的结晶条件相似，但晚期辉石的晶出量较多，晶粒较大（图3）。常见于基性侵入岩中。\n       包含结构：又称“嵌晶状结构”。泛指岩石中大晶体包含小晶体的一种结构。根据包裹和被包裹的关系可分为主晶和客晶。主晶指大的包裹矿物，客晶指小的被包裹矿物。这种结构说明：客晶矿物形成早于主晶矿物。主晶常有熔蚀和交代早期客晶的现象。例如，在超基性岩中常见到大的辉石晶体包裹小的圆形的橄榄石晶体，是一种典型的包含结构。\n                                                详细定名： 辉绿岩\n \n\n \n \n \n \n \n \n \n \n                                                                                                 图1a 单偏光下绿泥石化                                                                                                              图1b 正交偏光下绿泥石化\n                                                                                                                         \n \n \n \n \n \n                                                                           图2a 单偏光下辉绿结构                                                                                                             图2b 正交偏光下辉绿结构\n\n \n \n \n \n \n \n \n \n                                                                                                  图3a 单偏光下嵌晶含长结构                                                                                                         图3b 正交偏光下嵌晶含长结构","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"898":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：伊丁石玄武岩</td>\n                        <td>英文名：Olivine Basalt</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=4\" target=\"_blank\" rel=\"noopener noreferrer\">岩石标本</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=160\" target=\"_blank\" rel=\"noopener noreferrer\">岩浆岩</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=162\" target=\"_blank\" rel=\"noopener noreferrer\">基性岩</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：If10.1</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p><strong>伊丁石玄武岩内容概述：</strong></p>\n<p>       玄武岩是基性喷出岩的代表性岩石，主要呈熔岩产出，少数呈岩墙、岩床等形式的浅成侵入体。由辉石和基性斜长石组成，有些种属（如苦橄玄武岩、碱性玄武岩）含丰富的橄榄石，次要矿物是钛、铁氧化物（磁铁矿、钛铁矿、赤铁矿）、正长石、石英等。</p>\n<p><strong>伊丁石玄武岩薄片镜下鉴定：</strong></p>\n<p>       玄武岩一般呈细粒隐晶至玻璃质，反应岩浆冷却速率较快，常见斑状结构、显微斑状结构和聚斑结构，基质往往具间粒结构、间隐结构和填间结构，以及绳状构造、柱状节理、枕状构造。</p>\n<p>【<strong>斑晶</strong>】</p>\n<ol>\n<li>斜长石（6%）：无色，正低突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)，半自形长板状，解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)完全，具聚片双晶和卡纳复合双晶。少数具边缘环带结构，在⊥ a切面上，测得其为An65号的拉长石。</li>\n<li>伊丁石（8%）：棕红色，交代橄榄石而成，具较自形或具熔蚀结构的橄榄石假象，常见颜色不均匀构成的环带结构；正高突起，可见一组解理，最高干涉色可达三级红，但多被本身颜色所掩盖；平行消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)，正延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)；有时可见橄榄石交代残余（图1）。</li>\n<li>普通辉石（2%）:半自形粒状至短柱状，正高突起，具两组近于直交的完全解理，最高干涉色二级橙，少数见环带结构。</li>\n</ol>\n<p>【<strong>基质</strong>】主要由斜长石微晶和辉石微粒组成。</p>\n<ol>\n<li>斜长石（57%）：约占基质的60％，呈半自形长条状，大小不一，杂乱排列构成许多三角状孔隙，微粒状的辉石、磁铁矿、玻璃质及显微隐晶质物质充填其中，构成典型的间粒间隐结构；具聚片双晶，斜长石主要为An47-50的拉长石。</li>\n<li>普通辉石（13%）：它形粒状，正高突起，光性与斑晶中的辉石相似，常分布于斜长石微晶之间的空隙之中。</li>\n<li>伊丁石（5%）：它形微粒状，其光性特征与斑晶相似，常见橄榄石残余。</li>\n<li>黑色不透明针状、粒状磁铁矿和红色透明细小片状的赤铁矿（共约9％）。</li>\n</ol>\n<p>       此外，局部还有黄绿色、褐黄色的火山玻璃分布；岩石中偶见少量圆或椭圆的气孔，部分气孔被方解石充填。</p>\n<p>       可能的的结晶顺序为：橄榄石、拉长石、普通辉石（斑晶）→中长石（基质）→微粒状的普通辉石、磁铁矿（基质）→玻璃。方解石和伊丁石是次生矿物，前者充填在气孔中，后者交代橄榄石。</p>\n<p>【<strong>次生变化</strong>】多发生伊丁石化、绿泥石化、帘石化、碳酸盐化、黏土化等。</p>\n<p>伊丁石化：低温氧化条件下橄榄石蚀变成伊丁石的次生变化。</p>\n<p>钠黝帘石化：这是基性斜长石经常发生的一种蚀变现象。“钠黝帘石”就是钠长石、黝帘石和绿帘石等矿物的集合体，无或有少量的绢云母、绿泥石、石英、葡萄石、石榴石等矿物。</p>\n<p>绿泥石化：绿泥石是分布很广的岩浆期后矿物，流体交代角闪石、黑云母等铁镁暗色矿物生成绿泥石的变化。</p>\n<p>碳酸盐化：岩石遭受热液（中、低温热液为主）蚀变后，产生相当数量的碳酸盐矿物，如方解石、菱铁矿、铁白云石、白云石及菱镁矿等的作用。大多数岩石都能发生碳酸盐化。</p>\n<p><strong>【结构和构造】</strong></p>\n<p>斑状结构：在玄武岩中存在少量结晶程度较高的辉石和长石斑晶，斑晶的粒径明显比周围的基质大（图2）。</p>\n<p>       间粒结构：是玄武岩的一种典型结构。在偏光显微镜下，可见斜长石呈板条状的微晶交叉生长，在其空隙中充填有细小的辉石、磁铁矿或其他深色矿物晶粒。具这种结构的玄武岩比一般的玄武岩肉眼看来颗粒要粗一些，故又称粗玄结构（图3）。</p>\n<p>       间隐结构：又称“填间结构”。是玄武岩常见的一种结构。多见于隐晶质或半晶质的玄武岩中，由微晶和玻璃组成。密集的斜长石板条状晶体组成架状，在其空隙中充填有玻璃质物质。如晶体间隙中除玻璃质之外，还有粒状矿物，如辉石、磁铁矿等，则称为“拉斑玄武结构”。</p>\n<p>       枕状构造：海底喷发的基性熔岩所形成的一种特殊构造。熔岩多呈枕状椭球体，互相堆叠。枕状熔岩常与沉积岩伴生，枕状椭球体之间常有沉积物充填，其中还可以找到海生化石。多数枕状体在生成固结时常残留塑性变形遗迹，有因重力向下方间隙下垂的形迹，由此特征可以判断沉积当时的上下方向。枕状椭球体表层坚硬，结晶程度比内层要差，以此可与球状风化所成的椭球体区别开来。</p>\n<p>       柱状节理：火山岩特别是中—基性熔岩和某些次火山岩中发育的呈多角柱状的节理。由岩浆或熔岩流冷却收缩而成，柱体垂直于冷却面发生，断面近六角形。例如玄武岩、安山岩等的柱状节理。                            </p>\n<p>        详细定名： 伊丁石化橄榄玄武岩</p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529232654.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/898_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><strong> <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529232655.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/898_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a> <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529232655(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/898_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529232656.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/898_3.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a> <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529232656(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/898_4.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529232657.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/898_5.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a>                                                                                                                            </strong></p>\n\n        ","sourceFullDescriptionText":"描述\n            \n伊丁石玄武岩内容概述：\n       玄武岩是基性喷出岩的代表性岩石，主要呈熔岩产出，少数呈岩墙、岩床等形式的浅成侵入体。由辉石和基性斜长石组成，有些种属（如苦橄玄武岩、碱性玄武岩）含丰富的橄榄石，次要矿物是钛、铁氧化物（磁铁矿、钛铁矿、赤铁矿）、正长石、石英等。\n伊丁石玄武岩薄片镜下鉴定：\n       玄武岩一般呈细粒隐晶至玻璃质，反应岩浆冷却速率较快，常见斑状结构、显微斑状结构和聚斑结构，基质往往具间粒结构、间隐结构和填间结构，以及绳状构造、柱状节理、枕状构造。\n【斑晶】\n\n斜长石（6%）：无色，正低突起 (查看突起测定方法)，半自形长板状，解理 (查看解理测定方法)完全，具聚片双晶和卡纳复合双晶。少数具边缘环带结构，在⊥ a切面上，测得其为An65号的拉长石。\n伊丁石（8%）：棕红色，交代橄榄石而成，具较自形或具熔蚀结构的橄榄石假象，常见颜色不均匀构成的环带结构；正高突起，可见一组解理，最高干涉色可达三级红，但多被本身颜色所掩盖；平行消光 (查看消光测定方法)，正延性 (查看延性测定方法)；有时可见橄榄石交代残余（图1）。\n普通辉石（2%）:半自形粒状至短柱状，正高突起，具两组近于直交的完全解理，最高干涉色二级橙，少数见环带结构。\n\n【基质】主要由斜长石微晶和辉石微粒组成。\n\n斜长石（57%）：约占基质的60％，呈半自形长条状，大小不一，杂乱排列构成许多三角状孔隙，微粒状的辉石、磁铁矿、玻璃质及显微隐晶质物质充填其中，构成典型的间粒间隐结构；具聚片双晶，斜长石主要为An47-50的拉长石。\n普通辉石（13%）：它形粒状，正高突起，光性与斑晶中的辉石相似，常分布于斜长石微晶之间的空隙之中。\n伊丁石（5%）：它形微粒状，其光性特征与斑晶相似，常见橄榄石残余。\n黑色不透明针状、粒状磁铁矿和红色透明细小片状的赤铁矿（共约9％）。\n\n       此外，局部还有黄绿色、褐黄色的火山玻璃分布；岩石中偶见少量圆或椭圆的气孔，部分气孔被方解石充填。\n       可能的的结晶顺序为：橄榄石、拉长石、普通辉石（斑晶）→中长石（基质）→微粒状的普通辉石、磁铁矿（基质）→玻璃。方解石和伊丁石是次生矿物，前者充填在气孔中，后者交代橄榄石。\n【次生变化】多发生伊丁石化、绿泥石化、帘石化、碳酸盐化、黏土化等。\n伊丁石化：低温氧化条件下橄榄石蚀变成伊丁石的次生变化。\n钠黝帘石化：这是基性斜长石经常发生的一种蚀变现象。“钠黝帘石”就是钠长石、黝帘石和绿帘石等矿物的集合体，无或有少量的绢云母、绿泥石、石英、葡萄石、石榴石等矿物。\n绿泥石化：绿泥石是分布很广的岩浆期后矿物，流体交代角闪石、黑云母等铁镁暗色矿物生成绿泥石的变化。\n碳酸盐化：岩石遭受热液（中、低温热液为主）蚀变后，产生相当数量的碳酸盐矿物，如方解石、菱铁矿、铁白云石、白云石及菱镁矿等的作用。大多数岩石都能发生碳酸盐化。\n【结构和构造】\n斑状结构：在玄武岩中存在少量结晶程度较高的辉石和长石斑晶，斑晶的粒径明显比周围的基质大（图2）。\n       间粒结构：是玄武岩的一种典型结构。在偏光显微镜下，可见斜长石呈板条状的微晶交叉生长，在其空隙中充填有细小的辉石、磁铁矿或其他深色矿物晶粒。具这种结构的玄武岩比一般的玄武岩肉眼看来颗粒要粗一些，故又称粗玄结构（图3）。\n       间隐结构：又称“填间结构”。是玄武岩常见的一种结构。多见于隐晶质或半晶质的玄武岩中，由微晶和玻璃组成。密集的斜长石板条状晶体组成架状，在其空隙中充填有玻璃质物质。如晶体间隙中除玻璃质之外，还有粒状矿物，如辉石、磁铁矿等，则称为“拉斑玄武结构”。\n       枕状构造：海底喷发的基性熔岩所形成的一种特殊构造。熔岩多呈枕状椭球体，互相堆叠。枕状熔岩常与沉积岩伴生，枕状椭球体之间常有沉积物充填，其中还可以找到海生化石。多数枕状体在生成固结时常残留塑性变形遗迹，有因重力向下方间隙下垂的形迹，由此特征可以判断沉积当时的上下方向。枕状椭球体表层坚硬，结晶程度比内层要差，以此可与球状风化所成的椭球体区别开来。\n       柱状节理：火山岩特别是中—基性熔岩和某些次火山岩中发育的呈多角柱状的节理。由岩浆或熔岩流冷却收缩而成，柱体垂直于冷却面发生，断面近六角形。例如玄武岩、安山岩等的柱状节理。                            \n        详细定名： 伊丁石化橄榄玄武岩","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"899":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：橄榄玄武岩</td>\n                        <td>英文名：Olivine Basalt</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=4\" target=\"_blank\" rel=\"noopener noreferrer\">岩石标本</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=160\" target=\"_blank\" rel=\"noopener noreferrer\">岩浆岩</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=162\" target=\"_blank\" rel=\"noopener noreferrer\">基性岩</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：If10.3</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p><strong>橄榄玄武岩内容综述：</strong></p>\n<p>       玄武岩是基性喷出岩的代表性岩石，主要呈熔岩产出，少数呈岩墙、岩床等形式的浅成侵入体。由辉石和基性斜长石组成，有些种属（如苦橄玄武岩、碱性玄武岩）含丰富的橄榄石，次要矿物是钛、铁氧化物（磁铁矿、钛铁矿、赤铁矿）、正长石、石英等。</p>\n<p>       玄武岩一般呈细粒隐晶至玻璃质，反应岩浆冷却速率较快的情况，常见斑状结构、显微斑状结构和聚斑结构，基质往往具间粒结构、间隐结构和填间结构，岩石常见绳状构造、柱状节理、枕状构造。其中，绳状构造和枕状构造的枕状体弧面可以指示岩流的顶底面。</p>\n<p><strong>橄榄玄武岩薄片镜下鉴定：</strong></p>\n<p>岩石具斑状结构（图1），基质主要为间粒结构，局部为间隐结构（图2）。</p>\n<p>【<strong>斑晶</strong>】</p>\n<ol>\n<li>橄榄石（5%）: 单偏光镜下无色，一般为半自形--自形粒状，正极高突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)，两组不完全解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)，干涉色可达二级顶部。可以包裹磁铁矿、铬铁矿、尖晶石，或出溶作用形成的针状、板状铁质矿物。在橄榄石外围可见伊丁石的反应边结构（图3），部分橄榄石完全蚀变成伊丁石，可见假象结构（图4）。</li>\n<li>伊丁石（5%）：棕红色，交代橄榄石而成，具较自形或具熔蚀结构的橄榄石假象，常见颜色不均匀构成的环带结构（图5）；正高突起，可见一组解理，最高干涉色可达三级红，但多被本身颜色所掩盖；平行消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)，正延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)；有时可见橄榄石交代残余。</li>\n<li>斜长石（6%）：无色，正低突起，半自形长板状，解理完全，具聚片双晶和卡纳复合双晶。少数具边缘环带结构，在⊥a切面上，测得其为An65号的拉长石。</li>\n</ol>\n<p>      4.辉石（&lt;3%）：单斜辉石镜下多呈无色或浅色，短柱状。正高突起。辉石式解理。斜消光，消光角一般&gt;35°。二级干涉色。见简单双晶。斜方辉石干涉色低（ 一级），多为平行消光。</p>\n<p>【<strong>基质</strong>】主要由斜长石微晶和辉石微粒组成。</p>\n<ol>\n<li>斜长石（60%）：约占基质的60％，呈半自形长条状，大小不一，杂乱排列构成许多三角状孔隙，微粒状的辉石、磁铁矿、玻璃质及显微隐晶质物质充填其中，构成典型的间粒间隐结构；具聚片双晶，斜长石主要为An47-50的拉长石。</li>\n<li>普通辉石（13%）：它形粒状，正高突起，光性与斑晶中的辉石相似，常分布于斜长石微晶之间的空隙之中。</li>\n<li>伊丁石（5%）：它形微粒状，其光性特征与斑晶相似，常见橄榄石残余。</li>\n<li>黑色不透明针状、粒状磁铁矿和红色透明细小片状的赤铁矿（共约5％）。</li>\n</ol>\n<p>       此外，局部还有黄绿色、褐黄色的火山玻璃分布；岩石中偶见少量圆或椭圆的气孔，部分气孔被方解石充填。</p>\n<p>【<strong>次生变化</strong>】多发生伊丁石化、绿泥石化、帘石化、碳酸盐化、黏土化等。</p>\n<p>        伊丁石化：低温氧化条件下橄榄石蚀变成伊丁石的次生变化。伊丁石是以针铁矿为主的含蒙脱石层混层矿物的集合体。</p>\n<p>【<strong>结构和构造</strong>】</p>\n<p>        间粒结构：是玄武岩的一种结构。在偏光显微镜下，可见斜长石呈板条状的微晶交叉生长，在其空隙中充填有细小的辉石、磁铁矿或其他深色矿物晶粒。具这种结构的玄武岩比一般的玄武岩肉眼看来颗粒要粗一些，故又称粗玄结构。</p>\n<p>        间隐结构：又称“填间结构”。是玄武岩常见的一种结构。多见于隐晶质或半晶质的玄武岩中，由微晶和玻璃组成。密集的斜长石板条状晶体组成架状，在其空隙中充填有玻璃质物质。如晶体间隙中除玻璃质之外，还有粒状矿物，如辉石、磁铁矿等，则称为“拉斑玄武结构”。</p>\n<p>        交代假象结构：交代结构的一种。其特征是，原有矿物被新矿物置换，但仍保留原有矿物的晶形，有时甚至还保留原有矿物的解理等内部特点。例如，蛇纹石交代橄榄石或斜方辉石后呈橄榄石或斜方辉石的假象，绿泥石交代黑云母或角闪石后呈黑云母或角闪石的假象，伊丁石交代橄榄石后呈现橄榄石的假象，等等。</p>\n<p>详细定名：（伊丁石化）橄榄玄武岩</p>\n<p> </p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529631568.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/899_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529631569.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/899_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529631569(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/899_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529631570.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/899_3.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529631570(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/899_4.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529631570(2).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/899_5.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529631571.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/899_6.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n        ","sourceFullDescriptionText":"描述\n            \n橄榄玄武岩内容综述：\n       玄武岩是基性喷出岩的代表性岩石，主要呈熔岩产出，少数呈岩墙、岩床等形式的浅成侵入体。由辉石和基性斜长石组成，有些种属（如苦橄玄武岩、碱性玄武岩）含丰富的橄榄石，次要矿物是钛、铁氧化物（磁铁矿、钛铁矿、赤铁矿）、正长石、石英等。\n       玄武岩一般呈细粒隐晶至玻璃质，反应岩浆冷却速率较快的情况，常见斑状结构、显微斑状结构和聚斑结构，基质往往具间粒结构、间隐结构和填间结构，岩石常见绳状构造、柱状节理、枕状构造。其中，绳状构造和枕状构造的枕状体弧面可以指示岩流的顶底面。\n橄榄玄武岩薄片镜下鉴定：\n岩石具斑状结构（图1），基质主要为间粒结构，局部为间隐结构（图2）。\n【斑晶】\n\n橄榄石（5%）: 单偏光镜下无色，一般为半自形--自形粒状，正极高突起 (查看突起测定方法)，两组不完全解理 (查看解理测定方法)，干涉色可达二级顶部。可以包裹磁铁矿、铬铁矿、尖晶石，或出溶作用形成的针状、板状铁质矿物。在橄榄石外围可见伊丁石的反应边结构（图3），部分橄榄石完全蚀变成伊丁石，可见假象结构（图4）。\n伊丁石（5%）：棕红色，交代橄榄石而成，具较自形或具熔蚀结构的橄榄石假象，常见颜色不均匀构成的环带结构（图5）；正高突起，可见一组解理，最高干涉色可达三级红，但多被本身颜色所掩盖；平行消光 (查看消光测定方法)，正延性 (查看延性测定方法)；有时可见橄榄石交代残余。\n斜长石（6%）：无色，正低突起，半自形长板状，解理完全，具聚片双晶和卡纳复合双晶。少数具边缘环带结构，在⊥a切面上，测得其为An65号的拉长石。\n\n      4.辉石（<3%）：单斜辉石镜下多呈无色或浅色，短柱状。正高突起。辉石式解理。斜消光，消光角一般>35°。二级干涉色。见简单双晶。斜方辉石干涉色低（ 一级），多为平行消光。\n【基质】主要由斜长石微晶和辉石微粒组成。\n\n斜长石（60%）：约占基质的60％，呈半自形长条状，大小不一，杂乱排列构成许多三角状孔隙，微粒状的辉石、磁铁矿、玻璃质及显微隐晶质物质充填其中，构成典型的间粒间隐结构；具聚片双晶，斜长石主要为An47-50的拉长石。\n普通辉石（13%）：它形粒状，正高突起，光性与斑晶中的辉石相似，常分布于斜长石微晶之间的空隙之中。\n伊丁石（5%）：它形微粒状，其光性特征与斑晶相似，常见橄榄石残余。\n黑色不透明针状、粒状磁铁矿和红色透明细小片状的赤铁矿（共约5％）。\n\n       此外，局部还有黄绿色、褐黄色的火山玻璃分布；岩石中偶见少量圆或椭圆的气孔，部分气孔被方解石充填。\n【次生变化】多发生伊丁石化、绿泥石化、帘石化、碳酸盐化、黏土化等。\n        伊丁石化：低温氧化条件下橄榄石蚀变成伊丁石的次生变化。伊丁石是以针铁矿为主的含蒙脱石层混层矿物的集合体。\n【结构和构造】\n        间粒结构：是玄武岩的一种结构。在偏光显微镜下，可见斜长石呈板条状的微晶交叉生长，在其空隙中充填有细小的辉石、磁铁矿或其他深色矿物晶粒。具这种结构的玄武岩比一般的玄武岩肉眼看来颗粒要粗一些，故又称粗玄结构。\n        间隐结构：又称“填间结构”。是玄武岩常见的一种结构。多见于隐晶质或半晶质的玄武岩中，由微晶和玻璃组成。密集的斜长石板条状晶体组成架状，在其空隙中充填有玻璃质物质。如晶体间隙中除玻璃质之外，还有粒状矿物，如辉石、磁铁矿等，则称为“拉斑玄武结构”。\n        交代假象结构：交代结构的一种。其特征是，原有矿物被新矿物置换，但仍保留原有矿物的晶形，有时甚至还保留原有矿物的解理等内部特点。例如，蛇纹石交代橄榄石或斜方辉石后呈橄榄石或斜方辉石的假象，绿泥石交代黑云母或角闪石后呈黑云母或角闪石的假象，伊丁石交代橄榄石后呈现橄榄石的假象，等等。\n详细定名：（伊丁石化）橄榄玄武岩","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"900":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：闪长岩</td>\n                        <td>英文名：Dendrobium</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=4\" target=\"_blank\" rel=\"noopener noreferrer\">岩石标本</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=160\" target=\"_blank\" rel=\"noopener noreferrer\">岩浆岩</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=163\" target=\"_blank\" rel=\"noopener noreferrer\">中性岩</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：If10.4</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p><strong>闪长岩内容概述：</strong></p>\n<p>       闪长岩属于中性岩类，SiO2含量为52wt%--65wt%，色率小于40，一般为20-35。矿物成分的主要特征包括：浅色矿物/暗色矿物约等于2:1；浅色矿物以斜长石为主，且其含量占长石总含量的2/3以上，常为更-中长石，常具环带结构；不含或仅含少量碱性长石，石英含量&lt;5%；暗色矿物多为20%-35%，最常见的为角闪石，也有以黑云母或辉石为主者。据暗色矿物种属不同，可进一步细分为辉石闪长岩、黑云母闪长岩和角闪闪长岩等。</p>\n<p>       岩石多具半自形粒状结构，且斜长石和暗色矿物的自形程度多高于碱性长石和石英。常具块状构造，有时可见带状构造（浅色矿物和暗色矿物分别组成条带）和斑杂状构造。</p>\n<p>该类岩石分布较少，几乎不独立产出，一般与基性岩、酸性岩或碱性岩伴生。</p>\n<p><strong>闪长岩薄片镜下鉴定：</strong></p>\n<p>       该薄片主要由斜长石组成，含少量普通角闪石、正长石和石英，具半自形不等粒粒状结构（图1），块状构造。</p>\n<p>【<strong>主要矿物</strong>】</p>\n<p>       斜长石（60-65%）：主要为更-中长石，An＞10。无色或浅褐色，正低突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)，多为自形—半自形的板状，具两组完全解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)，解理夹角为86°-87°，干涉色多为一级灰至一级白，斜消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)，但多呈现环带状消光（图2），环带结构发育（中心斜长石成分较基性、边缘较酸性的称为正环带构造，与此相反的称反环带构造，若同成分的环带反复出现，则称韵律环带构造），且多为韵律环带构造，双晶一般不发育，少数可见聚片双晶。长石中常含矿物包裹体，包括铁、钛氧化物及其早结晶的铁镁矿物，常发生钠黝帘石化、黏土化，绢云母化等次生变化（图3）。</p>\n<p>【<strong>次要矿物</strong>】</p>\n<ol>\n<li>普通角闪石（15-20%）：单偏光镜下呈绿色，多色性明显，旋转物台一周，颜色呈深绿—黄绿—淡黄绿变化，正中-正高突起，具角闪石式解理（横切面具两组完全解理，解理夹角为56°、124°，纵切面具一组完全解理），多为自形-半自形长柱状，最高干涉色达二级黄绿，横切面呈对称消光，纵切面为斜消光，消光角一般小于25°，正延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)，负光性，常见简单双晶（图4）或聚片双晶，横切面上双晶缝平行菱形解理长对角线。</li>\n<li>正长石（5-10%）：单偏光镜下多为无色透明，发生次生变化分解以后，则呈浑浊状；负低突起；解理{001}完全、{010}清楚，两组解理夹角90°；晶体呈短柱状或平行宽板状，自形程度低，多于石英一起呈填隙物方式充填于斜长石或普通角闪石所构成的空隙中；干涉色为一级灰至灰白；（001）面上为平行消光，（010）面上为斜消光，消光角较小，多为5°-12°；负延性；双晶发育，多为卡斯巴双晶，不可见聚片双晶；局部可见其发生绢云母化。</li>\n<li>石英（3-5%）：无色透明，正低突起，无解理，表面较干净；呈他形粒状，粒度较细，多呈填隙物方式充填于斜长石或普通角闪石所构成的空隙中；干涉色一级灰白到一级淡黄；平行消光，有时受应力影响呈波状消光，正延性。</li>\n</ol>\n<p>【<strong>副矿物</strong>】主要为磁铁矿、磷灰石、榍石、钛铁矿等。总含量不超过2%。</p>\n<p>【<strong>结构</strong>】主要为半自形粒状结构，且斜长石和暗色矿物的自形程度多高于碱性长石和石英。</p>\n<p>       半自形粒状结构：组成岩石的矿物自形程度不一致，既有自形，也有它形，但多数呈半自形，大部分侵入岩具有这种结构。</p>\n<p> 【<strong>次生变化</strong>】多发生钠黝帘石化、黏土化，绢云母化等。</p>\n<p>       钠黝帘石化：多为斜长石的次生变化，斜长石被钠黝帘石所替代，“钠黝帘石”就是钠长石、黝帘石和绿帘石等矿物的集合体，无或有少量的绢云母、绿泥石、石英、葡萄石、石榴石等矿物。</p>\n<p>       黏土化：黏土矿物为含水的铝硅酸盐，具层状构造，种类很多。所有黏土矿物结晶都很细或呈非晶质的胶状，并可呈各种类型的片状或致密结晶状。大部分黏土矿物为负突起，都含水。多为岩浆岩和变质岩中的长石和似长石风化和水热变化而成的产物，也常见于金属和非金属矿脉中。</p>\n<p>       绢云母化：绢云母在薄片中为密集的鳞片状集合体，常为长石类及副长石类的此生蚀变矿物，尤其是斜长石，比钾长石更易发生绢云母化。正交偏光镜间，绢云母由于在集合体中的方位不同，因而呈现五彩缤纷的干涉色交织在一起。根据研究，绢云母的成因有两种，一是水热蚀变的产物，二是风化成因。</p>\n<p>详细定名：闪长岩</p>\n<p> <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528851765.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/900_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528851765(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/900_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>                                                                                           <strong>图1a 单偏光下半自形不等粒粒状结构                                                                                        图1b 正交偏光下半自形不等粒粒状结构</strong></p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528851766.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/900_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528851766(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/900_3.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>                                                                                                                          <strong>图2a 正交偏光下环带结构                                                                                                             图2b 正交偏光下环带结构</strong></p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528851767.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/900_4.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528851766(2).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/900_5.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><br>    </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>                                                              <strong>图3a 单偏光下长石的粘土化、钠黝帘石化                                                                                 图3b 正交偏光下长石的粘土化、钠黝帘石化</strong></p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528851767(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/900_6.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p><strong>                                                图4b 正交偏光下角闪石双晶</strong></p>\n\n        ","sourceFullDescriptionText":"描述\n            \n闪长岩内容概述：\n       闪长岩属于中性岩类，SiO2含量为52wt%--65wt%，色率小于40，一般为20-35。矿物成分的主要特征包括：浅色矿物/暗色矿物约等于2:1；浅色矿物以斜长石为主，且其含量占长石总含量的2/3以上，常为更-中长石，常具环带结构；不含或仅含少量碱性长石，石英含量<5%；暗色矿物多为20%-35%，最常见的为角闪石，也有以黑云母或辉石为主者。据暗色矿物种属不同，可进一步细分为辉石闪长岩、黑云母闪长岩和角闪闪长岩等。\n       岩石多具半自形粒状结构，且斜长石和暗色矿物的自形程度多高于碱性长石和石英。常具块状构造，有时可见带状构造（浅色矿物和暗色矿物分别组成条带）和斑杂状构造。\n该类岩石分布较少，几乎不独立产出，一般与基性岩、酸性岩或碱性岩伴生。\n闪长岩薄片镜下鉴定：\n       该薄片主要由斜长石组成，含少量普通角闪石、正长石和石英，具半自形不等粒粒状结构（图1），块状构造。\n【主要矿物】\n       斜长石（60-65%）：主要为更-中长石，An＞10。无色或浅褐色，正低突起 (查看突起测定方法)，多为自形—半自形的板状，具两组完全解理 (查看解理测定方法)，解理夹角为86°-87°，干涉色多为一级灰至一级白，斜消光 (查看消光测定方法)，但多呈现环带状消光（图2），环带结构发育（中心斜长石成分较基性、边缘较酸性的称为正环带构造，与此相反的称反环带构造，若同成分的环带反复出现，则称韵律环带构造），且多为韵律环带构造，双晶一般不发育，少数可见聚片双晶。长石中常含矿物包裹体，包括铁、钛氧化物及其早结晶的铁镁矿物，常发生钠黝帘石化、黏土化，绢云母化等次生变化（图3）。\n【次要矿物】\n\n普通角闪石（15-20%）：单偏光镜下呈绿色，多色性明显，旋转物台一周，颜色呈深绿—黄绿—淡黄绿变化，正中-正高突起，具角闪石式解理（横切面具两组完全解理，解理夹角为56°、124°，纵切面具一组完全解理），多为自形-半自形长柱状，最高干涉色达二级黄绿，横切面呈对称消光，纵切面为斜消光，消光角一般小于25°，正延性 (查看延性测定方法)，负光性，常见简单双晶（图4）或聚片双晶，横切面上双晶缝平行菱形解理长对角线。\n正长石（5-10%）：单偏光镜下多为无色透明，发生次生变化分解以后，则呈浑浊状；负低突起；解理{001}完全、{010}清楚，两组解理夹角90°；晶体呈短柱状或平行宽板状，自形程度低，多于石英一起呈填隙物方式充填于斜长石或普通角闪石所构成的空隙中；干涉色为一级灰至灰白；（001）面上为平行消光，（010）面上为斜消光，消光角较小，多为5°-12°；负延性；双晶发育，多为卡斯巴双晶，不可见聚片双晶；局部可见其发生绢云母化。\n石英（3-5%）：无色透明，正低突起，无解理，表面较干净；呈他形粒状，粒度较细，多呈填隙物方式充填于斜长石或普通角闪石所构成的空隙中；干涉色一级灰白到一级淡黄；平行消光，有时受应力影响呈波状消光，正延性。\n\n【副矿物】主要为磁铁矿、磷灰石、榍石、钛铁矿等。总含量不超过2%。\n【结构】主要为半自形粒状结构，且斜长石和暗色矿物的自形程度多高于碱性长石和石英。\n       半自形粒状结构：组成岩石的矿物自形程度不一致，既有自形，也有它形，但多数呈半自形，大部分侵入岩具有这种结构。\n 【次生变化】多发生钠黝帘石化、黏土化，绢云母化等。\n       钠黝帘石化：多为斜长石的次生变化，斜长石被钠黝帘石所替代，“钠黝帘石”就是钠长石、黝帘石和绿帘石等矿物的集合体，无或有少量的绢云母、绿泥石、石英、葡萄石、石榴石等矿物。\n       黏土化：黏土矿物为含水的铝硅酸盐，具层状构造，种类很多。所有黏土矿物结晶都很细或呈非晶质的胶状，并可呈各种类型的片状或致密结晶状。大部分黏土矿物为负突起，都含水。多为岩浆岩和变质岩中的长石和似长石风化和水热变化而成的产物，也常见于金属和非金属矿脉中。\n       绢云母化：绢云母在薄片中为密集的鳞片状集合体，常为长石类及副长石类的此生蚀变矿物，尤其是斜长石，比钾长石更易发生绢云母化。正交偏光镜间，绢云母由于在集合体中的方位不同，因而呈现五彩缤纷的干涉色交织在一起。根据研究，绢云母的成因有两种，一是水热蚀变的产物，二是风化成因。\n详细定名：闪长岩\n \n \n \n \n \n \n \n \n \n                                                                                           图1a 单偏光下半自形不等粒粒状结构                                                                                        图1b 正交偏光下半自形不等粒粒状结构\n\n \n \n \n \n \n \n \n \n                                                                                                                          图2a 正交偏光下环带结构                                                                                                             图2b 正交偏光下环带结构\n    \n \n \n \n \n \n \n \n \n                                                              图3a 单偏光下长石的粘土化、钠黝帘石化                                                                                 图3b 正交偏光下长石的粘土化、钠黝帘石化\n\n                                                图4b 正交偏光下角闪石双晶","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"901":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：石英闪长岩</td>\n                        <td>英文名：quartz diorite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=4\" target=\"_blank\" rel=\"noopener noreferrer\">岩石标本</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=160\" target=\"_blank\" rel=\"noopener noreferrer\">岩浆岩</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=163\" target=\"_blank\" rel=\"noopener noreferrer\">中性岩</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：Ig20.6</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p><strong>石英闪长岩内容概述：</strong></p>\n<p>       石英闪长岩为闪长岩的一个种属，指的是石英含量占5%-20%的闪长岩，暗色矿物含量在15%左右，斜长石（中长石）占一半以上，它是闪长岩向花岗岩过渡的种属。矿物成分的主要特征包括：浅色矿物以斜长石为主，且其含量占长石总含量的2/3以上，常为更-中长石，常具环带结构；不含或仅含少量碱性长石，石英含量小于占5%-20%；暗色矿物多为15%左右，最常见的为角闪石，也有以黑云母或辉石为主者。</p>\n<p>岩石多具半自形粒状结构，且斜长石和暗色矿物的自形程度多高于碱性长石和石英。常具块状构造，有时可见带状构造（浅色矿物和暗色矿物分别组成条带）和斑杂状构造。</p>\n<p>该类岩石分布较少，几乎不独立产出，一般与基性岩、酸性岩或碱性岩伴生。</p>\n<p><strong>石英闪长岩薄片镜下鉴定：</strong></p>\n<p>       该薄片主要由斜长石组成，含少量正长石和石英，暗色矿物主要为黑云母。具半自形粒状结构，局部见环带结构（图1）、交代净边结构（图2）和包含结构（图3）；块状构造。</p>\n<p>【<strong>主要矿物</strong>】</p>\n<p>1.斜长石（65-70%）：无色或浅褐色，正低突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)，多为自形—半自形的板状，干涉色多为一级灰至一级白，斜消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)，多见中长石的环带状消光和中基性斜长石的聚片双晶（图4）。晶体多发生绢云母化。</p>\n<p>【<strong>次要矿物</strong>】</p>\n<ol>\n<li>黑云母（5—10%左右）：镜下为片状，具浅黄色至棕色多色性，正中突起，解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)极完全，干涉色最高为二级橙，平行消光，多蚀变为绿泥石（图5）。</li>\n<li>石英（10%左右）：无色透明，正低突起，无解理，表面较干净；呈它形粒状，干涉色一级灰白到一级淡黄；平行消光。</li>\n<li>正长石（5-8%）：无色透明，因发生次生变化分解呈浑浊状；负低突起；晶体呈短柱状或平行宽板状，自形程度低，多于石英一起呈填隙物方式充填于斜长石所构成的空隙中；干涉色为一级灰至灰白；双晶发育，多为卡斯巴双晶，不可见聚片双晶。</li>\n</ol>\n<p>【<strong>副矿物</strong>】主要为磁铁矿、磷灰石、榍石、钛铁矿等。总含量不超过2%。</p>\n<p>【<strong>结构</strong>】半自形粒状结构、环带结构、交代净边结构、包含结构</p>\n<p>       半自形粒状结构：组成岩石的矿物自形程度不一致，既有自形，也有他形，但多数呈半自形，大部分侵入岩具有这种结构。</p>\n<p>       环带结构：单偏光镜下为一个晶体晶形，正交偏光下明显看到干涉色和消光不一致的环带。</p>\n<p>       交代净边结构：交代结构的一种。主要发育在斜长石中，在蚀变的（绢云母化和黏土化）斜长石边缘可见洁净的钠长石边。</p>\n<p>       包含结构： 又称“嵌晶状结构”。泛指岩石中大晶体包含小晶体的一种结构。根据包裹和被包裹的关系可分为主晶和客晶。主晶指大的包裹矿物，客晶指小的被包裹矿物。这种结构说明：客晶矿物形成早于主晶矿物。主晶常有熔蚀和交代早期客晶的现象。</p>\n<p>【<strong>次生变化</strong>】长石多发生钠黝帘石化、黏土化，绢云母化等。黑云母多发生绿泥石化。</p>\n<p>       绿泥石化：绿泥石是分布很广的岩浆期后矿物，交代角闪石、黑云母等铁镁暗色矿物。有时也交代长石、石英。绿泥石属层状硅酸盐，结晶均为单斜晶系，多数呈鳞片状集合体。薄片中浅绿色和浅黄色，有多色性。正低-正中突起。双折射率较低，干涉色不超过一级。有些绿泥石具靛蓝色或铁锈色的异常干涉色。</p>\n<p> </p>\n<p>详细定名：石英闪长岩</p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528859174.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/901_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528859175.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/901_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a>哈</p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>                                                                                       <strong>        图1 正交偏光下斜长石环带结构                                                                                           图4 正交偏光下斜长石环带结构和聚片双晶</strong></p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528859175(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/901_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528859175(2).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/901_3.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a>                                                                                                                                                                                                                                                                                                                                                                                                                    <strong>    图2a 单偏光下交代净边结构                                                                                                       图2b 正交偏光下交代净边结构</strong></p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528859176.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/901_4.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528859176(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/901_5.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a>   </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>                                                <strong>                                                     图3a 单偏光下包含结构                                                                                                          图3b 正交偏光下包含结构</strong></p>\n<p><strong><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528859176(2).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/901_6.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1528859177.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/901_7.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></strong></p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p><strong>                                                                       <strong>图5a 单偏光下黑云母绿泥石化                                                                                                  图5b 正交偏光下黑云母绿泥石化</strong></strong></p>\n<p><br><br></p>\n\n        ","sourceFullDescriptionText":"描述\n            \n石英闪长岩内容概述：\n       石英闪长岩为闪长岩的一个种属，指的是石英含量占5%-20%的闪长岩，暗色矿物含量在15%左右，斜长石（中长石）占一半以上，它是闪长岩向花岗岩过渡的种属。矿物成分的主要特征包括：浅色矿物以斜长石为主，且其含量占长石总含量的2/3以上，常为更-中长石，常具环带结构；不含或仅含少量碱性长石，石英含量小于占5%-20%；暗色矿物多为15%左右，最常见的为角闪石，也有以黑云母或辉石为主者。\n岩石多具半自形粒状结构，且斜长石和暗色矿物的自形程度多高于碱性长石和石英。常具块状构造，有时可见带状构造（浅色矿物和暗色矿物分别组成条带）和斑杂状构造。\n该类岩石分布较少，几乎不独立产出，一般与基性岩、酸性岩或碱性岩伴生。\n石英闪长岩薄片镜下鉴定：\n       该薄片主要由斜长石组成，含少量正长石和石英，暗色矿物主要为黑云母。具半自形粒状结构，局部见环带结构（图1）、交代净边结构（图2）和包含结构（图3）；块状构造。\n【主要矿物】\n1.斜长石（65-70%）：无色或浅褐色，正低突起 (查看突起测定方法)，多为自形—半自形的板状，干涉色多为一级灰至一级白，斜消光 (查看消光测定方法)，多见中长石的环带状消光和中基性斜长石的聚片双晶（图4）。晶体多发生绢云母化。\n【次要矿物】\n\n黑云母（5—10%左右）：镜下为片状，具浅黄色至棕色多色性，正中突起，解理 (查看解理测定方法)极完全，干涉色最高为二级橙，平行消光，多蚀变为绿泥石（图5）。\n石英（10%左右）：无色透明，正低突起，无解理，表面较干净；呈它形粒状，干涉色一级灰白到一级淡黄；平行消光。\n正长石（5-8%）：无色透明，因发生次生变化分解呈浑浊状；负低突起；晶体呈短柱状或平行宽板状，自形程度低，多于石英一起呈填隙物方式充填于斜长石所构成的空隙中；干涉色为一级灰至灰白；双晶发育，多为卡斯巴双晶，不可见聚片双晶。\n\n【副矿物】主要为磁铁矿、磷灰石、榍石、钛铁矿等。总含量不超过2%。\n【结构】半自形粒状结构、环带结构、交代净边结构、包含结构\n       半自形粒状结构：组成岩石的矿物自形程度不一致，既有自形，也有他形，但多数呈半自形，大部分侵入岩具有这种结构。\n       环带结构：单偏光镜下为一个晶体晶形，正交偏光下明显看到干涉色和消光不一致的环带。\n       交代净边结构：交代结构的一种。主要发育在斜长石中，在蚀变的（绢云母化和黏土化）斜长石边缘可见洁净的钠长石边。\n       包含结构： 又称“嵌晶状结构”。泛指岩石中大晶体包含小晶体的一种结构。根据包裹和被包裹的关系可分为主晶和客晶。主晶指大的包裹矿物，客晶指小的被包裹矿物。这种结构说明：客晶矿物形成早于主晶矿物。主晶常有熔蚀和交代早期客晶的现象。\n【次生变化】长石多发生钠黝帘石化、黏土化，绢云母化等。黑云母多发生绿泥石化。\n       绿泥石化：绿泥石是分布很广的岩浆期后矿物，交代角闪石、黑云母等铁镁暗色矿物。有时也交代长石、石英。绿泥石属层状硅酸盐，结晶均为单斜晶系，多数呈鳞片状集合体。薄片中浅绿色和浅黄色，有多色性。正低-正中突起。双折射率较低，干涉色不超过一级。有些绿泥石具靛蓝色或铁锈色的异常干涉色。\n \n详细定名：石英闪长岩\n哈\n \n \n \n \n \n \n \n \n                                                                                               图1 正交偏光下斜长石环带结构                                                                                           图4 正交偏光下斜长石环带结构和聚片双晶\n                                                                                                                                                                                                                                                                                                                                                                                                                        图2a 单偏光下交代净边结构                                                                                                       图2b 正交偏光下交代净边结构\n   \n \n \n \n \n \n \n \n \n                                                                                                     图3a 单偏光下包含结构                                                                                                          图3b 正交偏光下包含结构\n\n \n \n \n \n \n \n \n \n \n \n                                                                       图5a 单偏光下黑云母绿泥石化                                                                                                  图5b 正交偏光下黑云母绿泥石化","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"902":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：粗面岩</td>\n                        <td>英文名：Trachyte</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=4\" target=\"_blank\" rel=\"noopener noreferrer\">岩石标本</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=160\" target=\"_blank\" rel=\"noopener noreferrer\">岩浆岩</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=163\" target=\"_blank\" rel=\"noopener noreferrer\">中性岩</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：Io10.6</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p><strong>粗面岩内容概述：</strong></p>\n<p>       粗面岩是指成分相当于正长岩的喷出岩。具浅灰、浅灰黄和粉红等色，具粗糙的断口。斑晶常见碱性长石（正长石和透长石），其次是斜长石（主要是更长石），斜长石斑晶含量变化较大、它可以多于碱性长石斑晶，这时碱性长石主要存在于基质中。暗色矿物主要是角闪石、黑云母，它们常同时存在，普通辉石和透辉石有时可出现，偶见紫苏辉石。</p>\n<p>       粗面岩主要分布在大洋内部岛屿以及大陆内部的深大断裂附近，如大西洋、太平洋、印度洋的一些岛屿内。我国的粗面岩常与中生代安山岩、流纹岩共生。</p>\n<p><strong>粗面岩薄片镜下鉴定</strong>：</p>\n<p>       岩石具斑状结构，斑晶常见碱性长石（正长石和透长石），其次是斜长石（主要是更长石），基质常具粗面结构、玻基交织结构，局部见杏仁体（石英为充填物）和气孔。暗色矿物少见。</p>\n<p><strong>【斑晶】</strong>粗面岩斑晶可为碱性长石和斜长石，镜下以透长石和正长石为主，偶见极少量斜长石。</p>\n<p>       透长石（10-15%）：粗面岩中的主要矿物，在斑晶和基质中都大量存在。在薄片中无色透明，负低突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)，表面光滑，多为半自形板状，在酸性和碱性新相喷出岩中常呈自形的斑晶存在。具两组完全解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)，夹角为90°，但在镜下多看到一组，常具双晶，为卡式双晶（即卡斯巴双晶）（如图3）；干涉色为一级灰至灰白，不同切面呈现不同消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)类型，平行消光和斜消光都可出现，为负延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)。</p>\n<p>       正长石（5%）：单偏光镜下多为无色透明，发生次生变化分解以后，则呈浑浊状，负低突起，解理{001}完全、{010}清楚，两组解理夹角90°；晶体呈短柱状或平行宽板状，自形程度低，多于石英一起呈填隙物方式充填于斜长石或普通角闪石所构成的空隙中；干涉色为一级灰至灰白；（001）面上为平行消光，（010）面上为斜消光，消光角较小，多为5°-12°；负延性；双晶发育，多为卡斯巴双晶，不可见聚片双晶。</p>\n<p><strong>【基质】</strong>基质主要由碱性长石（透长石、正长石）和斜长石微晶组成。基质中的长石微晶呈半平行而又相互交织排列，在其空隙中充填有玻璃质，构成玻基交织结构。</p>\n<p>       透长石（40-50%）：粗面岩的主要矿物，在基质中大量存在。常呈宽板状，干涉色为一级灰至灰白。显示半定向性。</p>\n<p>       正长石（15-20%）：在薄片中无色透明，负低突起，多发生次生变化而使表面较脏，自形程度不及暗色矿物，多为半自形板状，具两组完全解理，夹角为90°，但在镜下多看到一组，常具双晶，为卡式双晶（即卡斯巴双晶）；干涉色为一级灰至灰白，不同切面呈不同消光类型，平行消光和斜消光都可出现，为负延性。</p>\n<p>       斜长石（5-10%）：主要为更-中长石，An＞10。无色或浅褐色，正低突起，多为自形—半自形的板状，具两组完全解理，解理夹角为86°-87°，干涉色多为一级灰至一级白，斜消光，双晶一般不发育，少数可见聚片双晶。</p>\n<p>       石英（5%）：无色透明，正低突起，无解理，表面较干净；呈他形粒状，粒度较细，充填于气孔空隙中构成杏仁体构造；干涉色一级灰白到一级淡黄；平行消光，有时受应力影响呈波状消光，正延性。</p>\n<p><strong>【副矿物】</strong>主要为磁铁矿、磷灰石、钛铁矿、赤铁矿等。总含量3-5%。</p>\n<p>【<strong>结构构造</strong>】粗面岩中常见的结构、构造主要由斑状结构、粗面结构、玻基交织结构、气孔构造、杏仁构造等。</p>\n<p>        斑状结构：岩石中矿物颗粒分为大小截然不同的两群，大的称为斑晶，小的及不结晶的玻璃质称为基质。其间没有中等大小的颗粒，可与不等粒结构相区别（如图1）。</p>\n<p>       粗面结构：粗面岩所常具的一种特征结构。其特点是，在偏光显微镜下，基质中的碱性长石微晶呈大致平行的排列，这反映熔岩凝固时的流动情况。</p>\n<p>       玻基交织结构：基质中的斜长石微晶呈半平行而又相互交织排列，在其空隙中充填有玻璃质（如图2）。</p>\n<p>       气孔构造和杏仁体构造：是火山岩中常见的一种构造。指岩浆喷溢地表冷凝时，其中的挥发分逸散后留下的空洞，常分布于熔岩流顶部。这些空洞呈圆形、椭圆形或不规则状，其量或多或少，分布有疏有密，或定向或不定向。当气孔被后来的物质所充填则形成杏仁体，称为杏仁体构造（如图4）。</p>\n<p>                                                  详细定名：粗面岩</p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529139603.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/902_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529139603(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/902_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>                                                                                                      <strong> 图1a 单偏光下斑状结构                                                                                                          图1b正交偏光下斑状结构            </strong></p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529139604.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/902_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529139604(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/902_3.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>                                                                                                 <strong> 图2a 单偏光下玻基交织结构                                                                                                        图2b正交偏光下玻基交织结构 </strong></p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529139604(2).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/902_4.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529139605.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/902_5.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>                                                                                              <strong> 图3a 单偏光下透长石卡式双晶                                                                                                     图3b正交偏光下透长石卡式双晶</strong></p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529139605(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/902_6.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529139606.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/902_7.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>                                                                                       <strong> 图4a 单偏光下 气孔构造和杏仁体构造                                                                                           图4b正交偏光下 气孔构造和杏仁体构造</strong></p>\n<p> </p>\n<p> </p>\n\n        ","sourceFullDescriptionText":"描述\n            \n粗面岩内容概述：\n       粗面岩是指成分相当于正长岩的喷出岩。具浅灰、浅灰黄和粉红等色，具粗糙的断口。斑晶常见碱性长石（正长石和透长石），其次是斜长石（主要是更长石），斜长石斑晶含量变化较大、它可以多于碱性长石斑晶，这时碱性长石主要存在于基质中。暗色矿物主要是角闪石、黑云母，它们常同时存在，普通辉石和透辉石有时可出现，偶见紫苏辉石。\n       粗面岩主要分布在大洋内部岛屿以及大陆内部的深大断裂附近，如大西洋、太平洋、印度洋的一些岛屿内。我国的粗面岩常与中生代安山岩、流纹岩共生。\n粗面岩薄片镜下鉴定：\n       岩石具斑状结构，斑晶常见碱性长石（正长石和透长石），其次是斜长石（主要是更长石），基质常具粗面结构、玻基交织结构，局部见杏仁体（石英为充填物）和气孔。暗色矿物少见。\n【斑晶】粗面岩斑晶可为碱性长石和斜长石，镜下以透长石和正长石为主，偶见极少量斜长石。\n       透长石（10-15%）：粗面岩中的主要矿物，在斑晶和基质中都大量存在。在薄片中无色透明，负低突起 (查看突起测定方法)，表面光滑，多为半自形板状，在酸性和碱性新相喷出岩中常呈自形的斑晶存在。具两组完全解理 (查看解理测定方法)，夹角为90°，但在镜下多看到一组，常具双晶，为卡式双晶（即卡斯巴双晶）（如图3）；干涉色为一级灰至灰白，不同切面呈现不同消光 (查看消光测定方法)类型，平行消光和斜消光都可出现，为负延性 (查看延性测定方法)。\n       正长石（5%）：单偏光镜下多为无色透明，发生次生变化分解以后，则呈浑浊状，负低突起，解理{001}完全、{010}清楚，两组解理夹角90°；晶体呈短柱状或平行宽板状，自形程度低，多于石英一起呈填隙物方式充填于斜长石或普通角闪石所构成的空隙中；干涉色为一级灰至灰白；（001）面上为平行消光，（010）面上为斜消光，消光角较小，多为5°-12°；负延性；双晶发育，多为卡斯巴双晶，不可见聚片双晶。\n【基质】基质主要由碱性长石（透长石、正长石）和斜长石微晶组成。基质中的长石微晶呈半平行而又相互交织排列，在其空隙中充填有玻璃质，构成玻基交织结构。\n       透长石（40-50%）：粗面岩的主要矿物，在基质中大量存在。常呈宽板状，干涉色为一级灰至灰白。显示半定向性。\n       正长石（15-20%）：在薄片中无色透明，负低突起，多发生次生变化而使表面较脏，自形程度不及暗色矿物，多为半自形板状，具两组完全解理，夹角为90°，但在镜下多看到一组，常具双晶，为卡式双晶（即卡斯巴双晶）；干涉色为一级灰至灰白，不同切面呈不同消光类型，平行消光和斜消光都可出现，为负延性。\n       斜长石（5-10%）：主要为更-中长石，An＞10。无色或浅褐色，正低突起，多为自形—半自形的板状，具两组完全解理，解理夹角为86°-87°，干涉色多为一级灰至一级白，斜消光，双晶一般不发育，少数可见聚片双晶。\n       石英（5%）：无色透明，正低突起，无解理，表面较干净；呈他形粒状，粒度较细，充填于气孔空隙中构成杏仁体构造；干涉色一级灰白到一级淡黄；平行消光，有时受应力影响呈波状消光，正延性。\n【副矿物】主要为磁铁矿、磷灰石、钛铁矿、赤铁矿等。总含量3-5%。\n【结构构造】粗面岩中常见的结构、构造主要由斑状结构、粗面结构、玻基交织结构、气孔构造、杏仁构造等。\n        斑状结构：岩石中矿物颗粒分为大小截然不同的两群，大的称为斑晶，小的及不结晶的玻璃质称为基质。其间没有中等大小的颗粒，可与不等粒结构相区别（如图1）。\n       粗面结构：粗面岩所常具的一种特征结构。其特点是，在偏光显微镜下，基质中的碱性长石微晶呈大致平行的排列，这反映熔岩凝固时的流动情况。\n       玻基交织结构：基质中的斜长石微晶呈半平行而又相互交织排列，在其空隙中充填有玻璃质（如图2）。\n       气孔构造和杏仁体构造：是火山岩中常见的一种构造。指岩浆喷溢地表冷凝时，其中的挥发分逸散后留下的空洞，常分布于熔岩流顶部。这些空洞呈圆形、椭圆形或不规则状，其量或多或少，分布有疏有密，或定向或不定向。当气孔被后来的物质所充填则形成杏仁体，称为杏仁体构造（如图4）。\n                                                  详细定名：粗面岩\n\n \n \n \n \n \n \n \n \n                                                                                                       图1a 单偏光下斑状结构                                                                                                          图1b正交偏光下斑状结构            \n\n \n \n \n \n \n \n \n \n                                                                                                  图2a 单偏光下玻基交织结构                                                                                                        图2b正交偏光下玻基交织结构 \n\n \n \n \n \n \n \n \n \n                                                                                               图3a 单偏光下透长石卡式双晶                                                                                                     图3b正交偏光下透长石卡式双晶\n\n \n \n \n \n \n \n \n \n                                                                                        图4a 单偏光下 气孔构造和杏仁体构造                                                                                           图4b正交偏光下 气孔构造和杏仁体构造","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"903":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：花岗岩</td>\n                        <td>英文名：Granite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=4\" target=\"_blank\" rel=\"noopener noreferrer\">岩石标本</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=160\" target=\"_blank\" rel=\"noopener noreferrer\">岩浆岩</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=164\" target=\"_blank\" rel=\"noopener noreferrer\">酸性岩</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：Ig12.7</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p><strong>花岗岩内容概述：</strong></p>\n<p>       花岗岩属于酸性岩类，，其化学成分特点是SiO<sub>2</sub>含量高，大于65wt％，一般为65wt％-78wt％，属于SiO<sub>2</sub>过饱和岩石；富碱，全碱（K<sub>2</sub>O+Na<sub>2</sub>O）含量平均6wt％-8wt％.矿物成分以浅色矿物为主，石英、碱性长石、斜长石含量总和大于90％，其中石英含量大于20％，铁镁矿物含量低于10％，种属主要为黑云母，因此岩石色调浅、色率低，密度小。</p>\n<p>花岗岩分布极广，是自然界分布最广的侵入岩，它们主要产在大陆陆壳，约占陆壳所有火山岩的50％以上，在大洋中仅有少量分布。</p>\n<p><strong>花岗岩薄片镜下鉴定特征： </strong></p>\n<p>       主要由碱性长石、斜长石、石英等组成，其中石英、碱性长石和斜长石三者总含量&gt;85%，次要矿物为黑云母、角闪石以及少量白云母和辉石。具有明显的花岗结构，即岩石中大部分矿物为半自形晶，副矿物的自形程度往往高于暗色矿物，暗色矿物自形程度高于浅色矿物，这种结构常表现出的结晶顺序为副矿物—暗色矿物—斜长石—钾长石—石英。此外，长石中还可见蠕虫结构。</p>\n<p>【<strong>主要矿物</strong>】</p>\n<p>1.斜长石（20-30%）：主要为中长石。矿物多为自形-半自形粒状结构，但也有近于板状。无色，正低突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)。干涉色一级灰。聚片双晶发育，环带结构发育。常发生绿泥石化，绢云母化等次生变化。</p>\n<p>2.石英（20-25%）：无色透明，正低突起，无解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)，表面较干净。多呈细小的他形粒状分布于斜长石、碱性长石之间；干涉色一级灰白到一级淡黄；平行消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)，有时受应力影响呈波状消光，正延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)。</p>\n<p>3.微斜长石（30-40%）：常呈它形不规则粒状，也有半自形到自形者。无色，负低突起。干涉色一级灰—灰白，为斜消光。格子状双晶发育，发育少量卡斯巴双晶。</p>\n<p>4.条纹长石（5-10%）：条纹长石是有钾长石和钠长石组成，其中钾长石为主晶，起含量大于钠长石。矿物颗粒呈自形-半自形，板状。无色，负低突起。干涉色一级灰。（如图5）</p>\n<p>【<strong>次要矿物</strong>】</p>\n<p>黑云母（5-10%）：黑云母镜下为片状，具浅黄色至棕色多色性，正中突起，解理极完全，干涉色最高为二级橙，平行消光，有时可见波状消光，常发生绿泥石化。</p>\n<p>【<strong>副矿物</strong>】主要为磷灰石、锆石、榍石等。总含量不超过2%。</p>\n<p>【<strong>次生变化</strong>】多发生绿泥石化（如图1），绢云母化（如图4）、黏土化等。</p>\n<p>绿泥石化：绿泥石是分布很广的岩浆期后矿物，交代角闪石、黑云母等铁镁暗色矿物。有时也交代长石、石英。</p>\n<p>       绢云母化：绢云母在薄片中为密集的鳞片状集合体，常为长石类及副长石类的此生蚀变矿物，尤其是斜长石，比钾长石更易发生绢云母化。正交偏光镜间，绢云母由于在集合体中的方位不同，因而呈现五彩缤纷的干涉色交织在一起。根据研究，绢云母的成因有两种，一是水热蚀变的产物，二是风化成因。</p>\n<p>       黏土化：黏土矿物为含水的铝硅酸盐，具层状构造，种类很多。所有黏土矿物结晶都很细或呈非晶质的胶状，并可呈各种类型的片状或致密结晶状。大部分黏土矿物为负突起，都含水。多为岩浆岩和变质岩中的长石和似长石风化和水热变化而成的产物，也常见于金属和非金属矿脉中。</p>\n<p>【<strong>结构构造</strong>】主要为花岗结构（如图2），局部可见有蠕虫结构（如图3）。</p>\n<p>花岗结构：岩石中大部分矿物为半自形晶，副矿物的自形程度往往高于暗色矿物，暗色矿物自形程度高于浅色矿物，这种结构常表现出的结晶顺序为副矿物—暗色矿物—斜长石—钾长石—石英。   </p>\n<p>蠕虫结构：石英和谐尝试斜长石的交生，在酸性斜长石中，许多细小的形似蠕虫状或指状石英穿插生长在长石中 。</p>\n<p>环带结构：单偏光镜下为一个晶体晶形，正交偏光下明显看到干涉色和消光不一致的环带。</p>\n<p>       条纹结构：由两种长石（钾长石和钠长石）作有规律地交生。具有条纹结构的长石叫条纹长石。条纹结构小至x射线才能确定，大到肉眼也能见到。常见的是钾长石晶体中包含有很多小的钠长石条纹，条纹多具定向性，常沿一定接警方向均匀分布，消光一致，无定向着少见。条纹结构常有两种成因，一是固溶体出溶（分解）而形成的分解条纹，这是分布最广的一类。是由于钾长石和钠长石在高温下可以形成完全固溶体（无限混溶），是一个成分均匀的固相。一为钾长石，一为钠长石，一个量多，一个量少，从而形成条纹结构。如果这种成因的钠长石成细小的条纹定向分布在钾长石中，即称之为正条纹结构。另一成因的钠长石条纹，是岩浆期后钠质交代钾长石形成的交代条纹，交代作用形成的钠长石条纹，常常较新鲜，多呈不规则的树枝状、网脉状分布，定向性不明显，常顺裂隙、解理、边缘等处分布。此外，还有少量相反情况，就是在较大的钠长石晶体中包含有钾长石的小条纹，这种结构称为反条纹结构（如图5）。</p>\n<p>                                                详细定名：花岗岩</p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529141197.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/903_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529141198.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/903_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>                                                                                                                            <strong> 图1a 单偏光下绿泥石化                                                                                                           图1b 正交偏光下绿泥石化                     </strong></p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529141198(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/903_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529141198(2).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/903_3.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>                                                                                                     <strong> 图2a 单偏光下花岗结构                                                                                                           图2b 正交偏光下花岗结构 </strong></p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529141199.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/903_4.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529141199(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/903_5.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>                                                                     <strong>                                 图3a 单偏光下蠕虫结构                                                                                                           图3b 正交偏光下蠕虫结构</strong></p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529141199(2).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/903_6.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529141200.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/903_7.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a>                                                  <strong> 图4a 单偏光下绢云母化                                                                                                            图4b 正交偏光下绢云母化</strong></p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529141200(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/903_8.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529141201.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/903_9.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>                                                                                                       <strong> 图5a 单偏光下条纹结构                                                                                                          图5b 正交偏光下条纹结构</strong></p>\n<p> </p>\n\n        ","sourceFullDescriptionText":"描述\n            \n花岗岩内容概述：\n       花岗岩属于酸性岩类，，其化学成分特点是SiO2含量高，大于65wt％，一般为65wt％-78wt％，属于SiO2过饱和岩石；富碱，全碱（K2O+Na2O）含量平均6wt％-8wt％.矿物成分以浅色矿物为主，石英、碱性长石、斜长石含量总和大于90％，其中石英含量大于20％，铁镁矿物含量低于10％，种属主要为黑云母，因此岩石色调浅、色率低，密度小。\n花岗岩分布极广，是自然界分布最广的侵入岩，它们主要产在大陆陆壳，约占陆壳所有火山岩的50％以上，在大洋中仅有少量分布。\n花岗岩薄片镜下鉴定特征： \n       主要由碱性长石、斜长石、石英等组成，其中石英、碱性长石和斜长石三者总含量>85%，次要矿物为黑云母、角闪石以及少量白云母和辉石。具有明显的花岗结构，即岩石中大部分矿物为半自形晶，副矿物的自形程度往往高于暗色矿物，暗色矿物自形程度高于浅色矿物，这种结构常表现出的结晶顺序为副矿物—暗色矿物—斜长石—钾长石—石英。此外，长石中还可见蠕虫结构。\n【主要矿物】\n1.斜长石（20-30%）：主要为中长石。矿物多为自形-半自形粒状结构，但也有近于板状。无色，正低突起 (查看突起测定方法)。干涉色一级灰。聚片双晶发育，环带结构发育。常发生绿泥石化，绢云母化等次生变化。\n2.石英（20-25%）：无色透明，正低突起，无解理 (查看解理测定方法)，表面较干净。多呈细小的他形粒状分布于斜长石、碱性长石之间；干涉色一级灰白到一级淡黄；平行消光 (查看消光测定方法)，有时受应力影响呈波状消光，正延性 (查看延性测定方法)。\n3.微斜长石（30-40%）：常呈它形不规则粒状，也有半自形到自形者。无色，负低突起。干涉色一级灰—灰白，为斜消光。格子状双晶发育，发育少量卡斯巴双晶。\n4.条纹长石（5-10%）：条纹长石是有钾长石和钠长石组成，其中钾长石为主晶，起含量大于钠长石。矿物颗粒呈自形-半自形，板状。无色，负低突起。干涉色一级灰。（如图5）\n【次要矿物】\n黑云母（5-10%）：黑云母镜下为片状，具浅黄色至棕色多色性，正中突起，解理极完全，干涉色最高为二级橙，平行消光，有时可见波状消光，常发生绿泥石化。\n【副矿物】主要为磷灰石、锆石、榍石等。总含量不超过2%。\n【次生变化】多发生绿泥石化（如图1），绢云母化（如图4）、黏土化等。\n绿泥石化：绿泥石是分布很广的岩浆期后矿物，交代角闪石、黑云母等铁镁暗色矿物。有时也交代长石、石英。\n       绢云母化：绢云母在薄片中为密集的鳞片状集合体，常为长石类及副长石类的此生蚀变矿物，尤其是斜长石，比钾长石更易发生绢云母化。正交偏光镜间，绢云母由于在集合体中的方位不同，因而呈现五彩缤纷的干涉色交织在一起。根据研究，绢云母的成因有两种，一是水热蚀变的产物，二是风化成因。\n       黏土化：黏土矿物为含水的铝硅酸盐，具层状构造，种类很多。所有黏土矿物结晶都很细或呈非晶质的胶状，并可呈各种类型的片状或致密结晶状。大部分黏土矿物为负突起，都含水。多为岩浆岩和变质岩中的长石和似长石风化和水热变化而成的产物，也常见于金属和非金属矿脉中。\n【结构构造】主要为花岗结构（如图2），局部可见有蠕虫结构（如图3）。\n花岗结构：岩石中大部分矿物为半自形晶，副矿物的自形程度往往高于暗色矿物，暗色矿物自形程度高于浅色矿物，这种结构常表现出的结晶顺序为副矿物—暗色矿物—斜长石—钾长石—石英。   \n蠕虫结构：石英和谐尝试斜长石的交生，在酸性斜长石中，许多细小的形似蠕虫状或指状石英穿插生长在长石中 。\n环带结构：单偏光镜下为一个晶体晶形，正交偏光下明显看到干涉色和消光不一致的环带。\n       条纹结构：由两种长石（钾长石和钠长石）作有规律地交生。具有条纹结构的长石叫条纹长石。条纹结构小至x射线才能确定，大到肉眼也能见到。常见的是钾长石晶体中包含有很多小的钠长石条纹，条纹多具定向性，常沿一定接警方向均匀分布，消光一致，无定向着少见。条纹结构常有两种成因，一是固溶体出溶（分解）而形成的分解条纹，这是分布最广的一类。是由于钾长石和钠长石在高温下可以形成完全固溶体（无限混溶），是一个成分均匀的固相。一为钾长石，一为钠长石，一个量多，一个量少，从而形成条纹结构。如果这种成因的钠长石成细小的条纹定向分布在钾长石中，即称之为正条纹结构。另一成因的钠长石条纹，是岩浆期后钠质交代钾长石形成的交代条纹，交代作用形成的钠长石条纹，常常较新鲜，多呈不规则的树枝状、网脉状分布，定向性不明显，常顺裂隙、解理、边缘等处分布。此外，还有少量相反情况，就是在较大的钠长石晶体中包含有钾长石的小条纹，这种结构称为反条纹结构（如图5）。\n                                                详细定名：花岗岩\n\n \n \n \n \n \n \n \n                                                                                                                             图1a 单偏光下绿泥石化                                                                                                           图1b 正交偏光下绿泥石化                     \n\n \n \n \n \n \n \n \n \n                                                                                                      图2a 单偏光下花岗结构                                                                                                           图2b 正交偏光下花岗结构 \n\n \n \n \n \n \n \n \n \n                                                                                                      图3a 单偏光下蠕虫结构                                                                                                           图3b 正交偏光下蠕虫结构\n                                                   图4a 单偏光下绢云母化                                                                                                            图4b 正交偏光下绢云母化\n\n \n \n \n \n \n \n \n \n                                                                                                        图5a 单偏光下条纹结构                                                                                                          图5b 正交偏光下条纹结构","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"904":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：花岗闪长岩</td>\n                        <td>英文名：Granodiorite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=4\" target=\"_blank\" rel=\"noopener noreferrer\">岩石标本</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=160\" target=\"_blank\" rel=\"noopener noreferrer\">岩浆岩</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=164\" target=\"_blank\" rel=\"noopener noreferrer\">酸性岩</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：Ig20.2</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p><strong>花岗闪长岩内容概述：</strong></p>\n<p>       花岗闪长岩属于花岗岩类的一种，也属于酸性岩类，其化学成分特点是SiO<sub>2</sub>含量高，大于65wt％，一般为65wt％-78wt％，属于SiO<sub>2</sub>过饱和岩石；富碱，全碱（K<sub>2</sub>O+Na<sub>2</sub>O）含量平均6wt％-8wt％.矿物成分以浅色矿物为主，石英、碱性长石、斜长石含量总和大于90％，其中石英含量大于20％，铁镁矿物含量低于10％，种属主要为黑云母，因此岩石色调浅、色率低，密度小。</p>\n<p>       花岗岩分布极广，是自然界分布最广的侵入岩，它们主要产在大陆陆壳，约占陆壳所有火山岩的50％以上，在大洋中仅有少量分布。花岗闪长岩多与花岗岩伴生，见于花岗岩岩体中心或构成岩体的边缘相，可呈岩基产出。岩石中斜长石含量较高，并含有少量角闪石，角闪石常发生绿泥石化。</p>\n<p>       这类岩石多与花岗岩伴生，见于花岗岩岩体中心或构成岩体的边缘相，可呈岩基产出。</p>\n<p><strong>花岗闪长岩镜下鉴定： </strong></p>\n<p>       主要由石英、斜长石和少量碱性长石组成，并含有少量角闪石和黑云母，岩石中斜长石一般为中长石，常发育明显的环带结构。岩石中斜长石含量较高，并含有少量角闪石，角闪石常发生绿泥石化。</p>\n<p>【<strong>主要矿物</strong>】</p>\n<p>1.斜长石（50-55%）：以中性斜长石为主，矿物呈自形—半自形的板状，正低突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)。干涉色一级灰。发育聚片双晶，环带结构。常发生绿泥石化，绢云母化等次生变化。</p>\n<p>2.石英（15-20%）：无色透明，正低突起，无解理 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#jieli\" target=\"_blank\" rel=\"noopener noreferrer\">查看解理测定方法</a>)，表面较干净。多呈细小的他形粒状分布于斜长石、碱性长石之间；干涉色一级灰白到一级淡黄；平行消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)，有时受应力影响呈波状消光，正延性 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#yanxing\" target=\"_blank\" rel=\"noopener noreferrer\">查看延性测定方法</a>)。</p>\n<p>3.微斜长石（20-25%）：常呈它形不规则粒状，也有半自形到自形者。无色，负低突起。干涉色一级灰到一级灰白，为斜消光。格子状双晶发育，发育少量卡斯巴双晶。</p>\n<p>4.条纹长石（5-10%）：条纹长石是有钾长石和钠长石组成，其中钾长石为主晶，起含量大于钠长石。矿物颗粒呈自形-半自形，板状。无色，负低突起。干涉色一级灰。条纹结构发育。</p>\n<p>【<strong>次要矿物</strong>】</p>\n<p>       黑云母（2-5%）：黑云母镜下为片状，具浅黄色至棕色多色性，正中突起，解理极完全，干涉色最高为二级橙，平行消光，有时可见波状消光，常发生绿泥石化。</p>\n<p>       角闪石（2-5%）：单偏光镜下呈绿色，多色性明显，旋转物台一周，颜色呈深绿—黄绿—淡黄绿变化，正中-正高突起，具角闪石式解理（横切面具两组完全解理，解理夹角为56°、124°，纵切面具一组完全解理），多为自形-半自形长柱状，最高干涉色达二级黄绿，横切面呈对称消光，纵切面为斜消光，消光角一般小于25°，正延性，负光性，常见简单双晶或聚片双晶，横切面上双晶缝平行菱形解理长对角线（图3）。常发生绿泥石化（图2）。</p>\n<p>【<strong>副矿物</strong>】主要为磷灰石、锆石、榍石等，总含量不超过2%。</p>\n<p>【<strong>次生变化</strong>】多发生绢云母化、绿泥石化等。</p>\n<p>        绢云母化：绢云母在薄片中为密集的鳞片状集合体，常为长石类及副长石类的此生蚀变矿物，尤其是斜长石，比钾长石更易发生绢云母化。正交偏光镜间，绢云母由于在集合体中的方位不同，因而呈现五彩缤纷的干涉色交织在一起。根据研究，绢云母的成因有两种，一是水热蚀变的产物，二是风化成因。</p>\n<p>绿泥石化：绿泥石是分布很广的岩浆期后矿物，交代角闪石、黑云母等铁镁暗色矿物。有时也交代长石、石英（图2）。</p>\n<p>【<strong>结构</strong>】主要为花岗结构，局部可见有蠕虫结构。</p>\n<p>花岗结构：岩石中大部分矿物为半自形晶，副矿物的自形程度往往高于暗色矿物，暗色矿物自形程度高于浅色矿物，这种结构常表现出的结晶顺序为副矿物—暗色矿物—斜长石—钾长石—石英（图1）。</p>\n<p>环带结构：单偏光镜下为一个晶体晶形，正交偏光下明显看到干涉色和消光不一致的环带（图4）。</p>\n<p>条纹结构：是石英与斜长石的交生，在酸性斜长石中，许多细小的形似蠕虫状或指状石英穿插生长在长石中 。</p>\n<p>                                              详细定名：花岗闪长岩</p>\n<p> </p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529143575.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/904_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529143576.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/904_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>                                                                       <strong>图1a 单偏光下                             图1b 正交偏光下        </strong></p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529143576(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/904_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529143577.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/904_3.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>                                                           <strong>图2a 单偏光下                             图2b 正交偏光下   </strong></p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529143577(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/904_4.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529143577(2).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/904_5.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>                                                                                       <strong>图3a 单偏光下                             图3b 正交偏光下   </strong></p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529143578.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/904_6.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529143578(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/904_7.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>                                                                     <strong>图4a 单偏光下                             图4b 正交偏光下   </strong></p>\n<p> </p>\n<p> </p>\n<p> </p>\n\n        ","sourceFullDescriptionText":"描述\n            \n花岗闪长岩内容概述：\n       花岗闪长岩属于花岗岩类的一种，也属于酸性岩类，其化学成分特点是SiO2含量高，大于65wt％，一般为65wt％-78wt％，属于SiO2过饱和岩石；富碱，全碱（K2O+Na2O）含量平均6wt％-8wt％.矿物成分以浅色矿物为主，石英、碱性长石、斜长石含量总和大于90％，其中石英含量大于20％，铁镁矿物含量低于10％，种属主要为黑云母，因此岩石色调浅、色率低，密度小。\n       花岗岩分布极广，是自然界分布最广的侵入岩，它们主要产在大陆陆壳，约占陆壳所有火山岩的50％以上，在大洋中仅有少量分布。花岗闪长岩多与花岗岩伴生，见于花岗岩岩体中心或构成岩体的边缘相，可呈岩基产出。岩石中斜长石含量较高，并含有少量角闪石，角闪石常发生绿泥石化。\n       这类岩石多与花岗岩伴生，见于花岗岩岩体中心或构成岩体的边缘相，可呈岩基产出。\n花岗闪长岩镜下鉴定： \n       主要由石英、斜长石和少量碱性长石组成，并含有少量角闪石和黑云母，岩石中斜长石一般为中长石，常发育明显的环带结构。岩石中斜长石含量较高，并含有少量角闪石，角闪石常发生绿泥石化。\n【主要矿物】\n1.斜长石（50-55%）：以中性斜长石为主，矿物呈自形—半自形的板状，正低突起 (查看突起测定方法)。干涉色一级灰。发育聚片双晶，环带结构。常发生绿泥石化，绢云母化等次生变化。\n2.石英（15-20%）：无色透明，正低突起，无解理 (查看解理测定方法)，表面较干净。多呈细小的他形粒状分布于斜长石、碱性长石之间；干涉色一级灰白到一级淡黄；平行消光 (查看消光测定方法)，有时受应力影响呈波状消光，正延性 (查看延性测定方法)。\n3.微斜长石（20-25%）：常呈它形不规则粒状，也有半自形到自形者。无色，负低突起。干涉色一级灰到一级灰白，为斜消光。格子状双晶发育，发育少量卡斯巴双晶。\n4.条纹长石（5-10%）：条纹长石是有钾长石和钠长石组成，其中钾长石为主晶，起含量大于钠长石。矿物颗粒呈自形-半自形，板状。无色，负低突起。干涉色一级灰。条纹结构发育。\n【次要矿物】\n       黑云母（2-5%）：黑云母镜下为片状，具浅黄色至棕色多色性，正中突起，解理极完全，干涉色最高为二级橙，平行消光，有时可见波状消光，常发生绿泥石化。\n       角闪石（2-5%）：单偏光镜下呈绿色，多色性明显，旋转物台一周，颜色呈深绿—黄绿—淡黄绿变化，正中-正高突起，具角闪石式解理（横切面具两组完全解理，解理夹角为56°、124°，纵切面具一组完全解理），多为自形-半自形长柱状，最高干涉色达二级黄绿，横切面呈对称消光，纵切面为斜消光，消光角一般小于25°，正延性，负光性，常见简单双晶或聚片双晶，横切面上双晶缝平行菱形解理长对角线（图3）。常发生绿泥石化（图2）。\n【副矿物】主要为磷灰石、锆石、榍石等，总含量不超过2%。\n【次生变化】多发生绢云母化、绿泥石化等。\n        绢云母化：绢云母在薄片中为密集的鳞片状集合体，常为长石类及副长石类的此生蚀变矿物，尤其是斜长石，比钾长石更易发生绢云母化。正交偏光镜间，绢云母由于在集合体中的方位不同，因而呈现五彩缤纷的干涉色交织在一起。根据研究，绢云母的成因有两种，一是水热蚀变的产物，二是风化成因。\n绿泥石化：绿泥石是分布很广的岩浆期后矿物，交代角闪石、黑云母等铁镁暗色矿物。有时也交代长石、石英（图2）。\n【结构】主要为花岗结构，局部可见有蠕虫结构。\n花岗结构：岩石中大部分矿物为半自形晶，副矿物的自形程度往往高于暗色矿物，暗色矿物自形程度高于浅色矿物，这种结构常表现出的结晶顺序为副矿物—暗色矿物—斜长石—钾长石—石英（图1）。\n环带结构：单偏光镜下为一个晶体晶形，正交偏光下明显看到干涉色和消光不一致的环带（图4）。\n条纹结构：是石英与斜长石的交生，在酸性斜长石中，许多细小的形似蠕虫状或指状石英穿插生长在长石中 。\n                                              详细定名：花岗闪长岩\n \n\n \n \n \n \n \n \n \n \n                                                                       图1a 单偏光下                             图1b 正交偏光下        \n\n \n \n \n \n \n \n \n \n                                                           图2a 单偏光下                             图2b 正交偏光下   \n\n \n \n \n \n \n \n \n \n                                                                                       图3a 单偏光下                             图3b 正交偏光下   \n\n \n \n \n \n \n \n \n \n                                                                     图4a 单偏光下                             图4b 正交偏光下","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"905":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：流纹岩</td>\n                        <td>英文名：rhyolite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=4\" target=\"_blank\" rel=\"noopener noreferrer\">岩石标本</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=160\" target=\"_blank\" rel=\"noopener noreferrer\">岩浆岩</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=164\" target=\"_blank\" rel=\"noopener noreferrer\">酸性岩</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：Il10.1</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p><strong>流纹岩鉴定：</strong></p>\n<p>       一种分布较广的酸性喷出岩，是与花岗岩对应的喷出岩，主要由碱性长石、斜长石、石英等组成，其中石英、碱性长石和斜长石三者总含量&gt;85%，次要矿物为黑云母、角闪石以及少量白云母和辉石。具有典型斑状结构（图1）和流纹构造（图2）。</p>\n<p>【<strong>斑晶】</strong></p>\n<ol>\n<li>石英（20-25%）：无色、正低突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)，最高干涉色为一级黄白，多呈他形粒状，多为高温β石英，常具有熔蚀而呈浑圆状、港湾状，边界较圆滑弯曲（图3）。</li>\n<li>碱性长石（15-20%）：常呈短柱状或它形不规则粒状，也有半自形到自形者。无色，负低突起，干涉色一级灰到一级灰白，斜消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)，常具有卡式双晶（图4）。</li>\n<li>斜长石（2-5%）：呈斑晶出现，以中性斜长石为主，矿物呈自形—半自形的板状，正低突起。干涉色一级灰。发育聚片双晶，发育环带结构。常发生绿泥石化，绢云母化等次生变化。</li>\n<li>暗色矿物（2-5%）：主要为黑云母，含极少量角闪石。</li>\n</ol>\n<p>【<strong>基质</strong>】</p>\n<p>       主要为玻璃质以及细小的石英、碱性长石。其中，玻璃质物质呈灰色，为隐晶质，有时可见有脱玻化现象，常常呈定向流动状围绕分布斑晶分布而呈现一定的流纹构造的特征。石英和碱性长石粒度都较小，呈无色，光性特征有时不太明显，但石英主要为粒状，碱性长石呈板状，分布于玻璃质中。基质中孔隙或孔洞较为发育，有时还可见一空洞中，沸石垂直于孔洞壁生长分布，最内侧有时还有石英，整体呈现一种栉壳状构造的特征（图5）。</p>\n<p>【<strong>副矿物</strong>】主要为磷灰石、赤铁矿、磁铁矿等。总含量不超过2%。</p>\n<p>【<strong>次生变化</strong>】多发生绢云母化等。</p>\n<p>       绢云母化：绢云母在薄片中为密集的鳞片状集合体，常为长石类及副长石类的此生蚀变矿物，尤其是斜长石，比钾长石更易发生绢云母化。正交偏光镜间，绢云母由于在集合体中的方位不同，因而呈现五彩缤纷的干涉色交织在一起。根据研究，绢云母的成因有两种，一是水热蚀变的产物，二是风化成因。</p>\n<p>【<strong>结构</strong>】主要为斑状结构。</p>\n<p>       斑状结构：岩石中大部分矿物为半自形晶，副矿物的自形程度往往高于暗色矿物，暗色矿物自形程度高于浅色矿物，这种结构常表现出的结晶顺序为副矿物—暗色矿物—斜长石—钾长石—石英。</p>\n<p>      详细定名：流纹岩</p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529144981.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/905_0.jpg\" alt=\"  图1a 单偏光下斑状结构  \" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529144981(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/905_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>                                                                                                                         <strong> 图1a 单偏光下斑状结构                                                                                                          图1b 正交偏光下斑状结构</strong></p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529144982.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/905_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529144982(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/905_3.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>                                                                                                                            <strong> 图2a 单偏光下流纹构造                                                                                                             图2b 正交偏光下流纹构造</strong></p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529144983.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/905_4.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529144983(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/905_5.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>                                                                                                                <strong> 图3a 单偏光下石英被熔蚀呈浑圆状                                                                                            图3b 正交偏光下石英被熔蚀呈浑圆状</strong></p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529144983(2).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/905_6.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529144984.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/905_7.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>                                                                                                                              <strong> 图4a 单偏光下卡式双晶                                                                                                          图4b 正交偏光下卡式双晶</strong></p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529144984(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/905_8.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529144984(2).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/905_9.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>                                                                                                                          <strong> 图5a 单偏光下栉壳状构造                                                                                                           图5b 正交偏光下栉壳状构造</strong></p>\n<p> </p>\n\n        ","sourceFullDescriptionText":"描述\n            \n流纹岩鉴定：\n       一种分布较广的酸性喷出岩，是与花岗岩对应的喷出岩，主要由碱性长石、斜长石、石英等组成，其中石英、碱性长石和斜长石三者总含量>85%，次要矿物为黑云母、角闪石以及少量白云母和辉石。具有典型斑状结构（图1）和流纹构造（图2）。\n【斑晶】\n\n石英（20-25%）：无色、正低突起 (查看突起测定方法)，最高干涉色为一级黄白，多呈他形粒状，多为高温β石英，常具有熔蚀而呈浑圆状、港湾状，边界较圆滑弯曲（图3）。\n碱性长石（15-20%）：常呈短柱状或它形不规则粒状，也有半自形到自形者。无色，负低突起，干涉色一级灰到一级灰白，斜消光 (查看消光测定方法)，常具有卡式双晶（图4）。\n斜长石（2-5%）：呈斑晶出现，以中性斜长石为主，矿物呈自形—半自形的板状，正低突起。干涉色一级灰。发育聚片双晶，发育环带结构。常发生绿泥石化，绢云母化等次生变化。\n暗色矿物（2-5%）：主要为黑云母，含极少量角闪石。\n\n【基质】\n       主要为玻璃质以及细小的石英、碱性长石。其中，玻璃质物质呈灰色，为隐晶质，有时可见有脱玻化现象，常常呈定向流动状围绕分布斑晶分布而呈现一定的流纹构造的特征。石英和碱性长石粒度都较小，呈无色，光性特征有时不太明显，但石英主要为粒状，碱性长石呈板状，分布于玻璃质中。基质中孔隙或孔洞较为发育，有时还可见一空洞中，沸石垂直于孔洞壁生长分布，最内侧有时还有石英，整体呈现一种栉壳状构造的特征（图5）。\n【副矿物】主要为磷灰石、赤铁矿、磁铁矿等。总含量不超过2%。\n【次生变化】多发生绢云母化等。\n       绢云母化：绢云母在薄片中为密集的鳞片状集合体，常为长石类及副长石类的此生蚀变矿物，尤其是斜长石，比钾长石更易发生绢云母化。正交偏光镜间，绢云母由于在集合体中的方位不同，因而呈现五彩缤纷的干涉色交织在一起。根据研究，绢云母的成因有两种，一是水热蚀变的产物，二是风化成因。\n【结构】主要为斑状结构。\n       斑状结构：岩石中大部分矿物为半自形晶，副矿物的自形程度往往高于暗色矿物，暗色矿物自形程度高于浅色矿物，这种结构常表现出的结晶顺序为副矿物—暗色矿物—斜长石—钾长石—石英。\n      详细定名：流纹岩\n\n \n \n \n \n \n \n \n \n                                                                                                                          图1a 单偏光下斑状结构                                                                                                          图1b 正交偏光下斑状结构\n\n \n \n \n \n \n \n \n \n                                                                                                                             图2a 单偏光下流纹构造                                                                                                             图2b 正交偏光下流纹构造\n\n \n \n \n \n \n \n \n \n                                                                                                                 图3a 单偏光下石英被熔蚀呈浑圆状                                                                                            图3b 正交偏光下石英被熔蚀呈浑圆状\n\n \n \n \n \n \n \n \n \n                                                                                                                               图4a 单偏光下卡式双晶                                                                                                          图4b 正交偏光下卡式双晶\n\n \n \n \n \n \n \n \n \n                                                                                                                           图5a 单偏光下栉壳状构造                                                                                                           图5b 正交偏光下栉壳状构造","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"},"906":{"sourceBasicHtml":"<table>\n                    <tbody><tr>\n                        <td>标本名：花岗细晶岩</td>\n                        <td>英文名：Granite aplite</td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"2\">标本分类： <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=4\" target=\"_blank\" rel=\"noopener noreferrer\">岩石标本</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=160\" target=\"_blank\" rel=\"noopener noreferrer\">岩浆岩</a> / <a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/21-1.html?c=164\" target=\"_blank\" rel=\"noopener noreferrer\">酸性岩</a></td>\n                    </tr>\n                    <tr>\n                        <td>产地：</td>\n                        <td>年代：</td>\n                    </tr>\n                    <tr>\n                        <td>编号：Iu20.2</td>\n                        <td>捐赠人：</td>\n                    </tr>\n                </tbody></table>","sourceDescriptionHtml":"\n            <h4>描述</h4>\n            \n<p><strong>细晶岩内容概述：</strong></p>\n<p>       细晶岩的命名是根据其具有典型的细粒他形粒状结构（即细晶结构），其成分多种多样，从辉长质到花岗质，所以细晶岩是一个较为笼统的概念。岩石进一步命名因在其前加上与其成分相似的侵入岩作为前缀。自然界分布最多的细晶岩成分为花岗质，岩体多呈脉状产出。</p>\n<p>       细晶岩买的宽度一般不大，多产于深成岩体的裂隙或附近围岩中。从成分和产状来看，细晶岩显然是由大部分岩浆结晶之后的残余岩浆沿岩体及附近围岩中的裂隙充填冷却而成。细晶岩颗粒小的原因可能是由于围岩破裂、压力骤降，导致残余岩浆中挥发分逸散，降低了石英和长石在岩浆中的可溶性，使相应组分趋于饱和，于是结晶中心大量出现，而压力骤降致使参与演讲上升到地壳浅部位置的过冷度较之深成环境要大，这时晶体生长速度较小，从而形成细粒结构。</p>\n<p><strong>细晶岩薄片镜下鉴定：</strong></p>\n<p>        细晶岩几乎全部为浅色矿物组成，主要矿物为石英和碱性长石，偶见少量云母。具有典型的细粒他形粒状结构（即细晶结构）（图1），石英和长石粒度都较小，自形程度较差。</p>\n<p>【<strong>矿物组成</strong>】</p>\n<p>       石英：无色，正低突起 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#tuqi\" target=\"_blank\" rel=\"noopener noreferrer\">查看突起测定方法</a>)，最高干涉色为一级黄白，多呈他形粒状，粒度较细，与碱性长石分布在一起。</p>\n<p>       碱性长石：常呈短柱状或它形不规则粒状，也有半自形到自形者。无色，负低突起，干涉色一级灰到一级灰白，为斜消光 (<a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/netdcg/70-1.html#xiaoguang\" target=\"_blank\" rel=\"noopener noreferrer\">查看消光测定方法</a>)，多为微斜长石、条纹长石和正长石，分别具有格子双晶、条纹结构和卡式双晶，有时可见微斜长石中包含有石英而呈包含结构（图2），局部还可见长石中石英呈弯弯曲曲的形态构成文象结构（图3）。</p>\n<p><strong>【结构】</strong></p>\n<p>       细晶结构：又称细粒他形粒状结构，矿物粒度都较小，自形程度较差，主要为细晶岩所具有的结构特征。</p>\n<p>       包含结构：又称“嵌晶状结构”。泛指岩石中大晶体包含小晶体的一种结构。根据包裹和被包裹的关系可分为主晶和客晶。主晶指大的包裹矿物，客晶指小的被包裹矿物。这种结构说明：客晶矿物形成早于主晶矿物。主晶常有熔蚀和交代早期客晶的现象。</p>\n<p>       文象结构：一种矿物呈一定的外形（楔形、象形文字状等）且有规律的镶嵌在另一种矿物中，其中嵌晶在相当大的范围内同时消光。钾长石和石英构成的文象结构最常见，见于伟晶岩、部分花岗岩、花岗斑岩中。</p>\n<p>定名：花岗细晶岩</p>\n<p><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529227397.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/906_0.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529227398.jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/906_1.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a><a href=\"http://www.netdcg.cdut.edu.cn/simmicro/public/media/samples/micro_pics/i_1529227398(1).jpg\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"img/pic/906_2.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p>       </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>                                   <strong> 图1 正交偏光下细晶结构                                                                      图2 正交偏光下包含结构                                                               图3 正交偏光下文象结构</strong></p>\n\n        ","sourceFullDescriptionText":"描述\n            \n细晶岩内容概述：\n       细晶岩的命名是根据其具有典型的细粒他形粒状结构（即细晶结构），其成分多种多样，从辉长质到花岗质，所以细晶岩是一个较为笼统的概念。岩石进一步命名因在其前加上与其成分相似的侵入岩作为前缀。自然界分布最多的细晶岩成分为花岗质，岩体多呈脉状产出。\n       细晶岩买的宽度一般不大，多产于深成岩体的裂隙或附近围岩中。从成分和产状来看，细晶岩显然是由大部分岩浆结晶之后的残余岩浆沿岩体及附近围岩中的裂隙充填冷却而成。细晶岩颗粒小的原因可能是由于围岩破裂、压力骤降，导致残余岩浆中挥发分逸散，降低了石英和长石在岩浆中的可溶性，使相应组分趋于饱和，于是结晶中心大量出现，而压力骤降致使参与演讲上升到地壳浅部位置的过冷度较之深成环境要大，这时晶体生长速度较小，从而形成细粒结构。\n细晶岩薄片镜下鉴定：\n        细晶岩几乎全部为浅色矿物组成，主要矿物为石英和碱性长石，偶见少量云母。具有典型的细粒他形粒状结构（即细晶结构）（图1），石英和长石粒度都较小，自形程度较差。\n【矿物组成】\n       石英：无色，正低突起 (查看突起测定方法)，最高干涉色为一级黄白，多呈他形粒状，粒度较细，与碱性长石分布在一起。\n       碱性长石：常呈短柱状或它形不规则粒状，也有半自形到自形者。无色，负低突起，干涉色一级灰到一级灰白，为斜消光 (查看消光测定方法)，多为微斜长石、条纹长石和正长石，分别具有格子双晶、条纹结构和卡式双晶，有时可见微斜长石中包含有石英而呈包含结构（图2），局部还可见长石中石英呈弯弯曲曲的形态构成文象结构（图3）。\n【结构】\n       细晶结构：又称细粒他形粒状结构，矿物粒度都较小，自形程度较差，主要为细晶岩所具有的结构特征。\n       包含结构：又称“嵌晶状结构”。泛指岩石中大晶体包含小晶体的一种结构。根据包裹和被包裹的关系可分为主晶和客晶。主晶指大的包裹矿物，客晶指小的被包裹矿物。这种结构说明：客晶矿物形成早于主晶矿物。主晶常有熔蚀和交代早期客晶的现象。\n       文象结构：一种矿物呈一定的外形（楔形、象形文字状等）且有规律的镶嵌在另一种矿物中，其中嵌晶在相当大的范围内同时消光。钾长石和石英构成的文象结构最常见，见于伟晶岩、部分花岗岩、花岗斑岩中。\n定名：花岗细晶岩\n\n       \n \n \n \n \n                                    图1 正交偏光下细晶结构                                                                      图2 正交偏光下包含结构                                                               图3 正交偏光下文象结构","sourceVideos":[],"sourceVideoStatus":"not-published-in-saved-source"}};Object.keys(records).forEach(function(sid){Object.assign(DATA.manifest.samples[sid],records[sid])});})();
